globalThis.ORDO_PROPERS_MONTHS ||= {}; globalThis.ORDO_PROPERS_MONTHS["2027-11"] = {"month":"2027-11","days":{"2027-11-01":{"date":"2027-11-01","title":"Todos os Santos","forms":[{"number":1,"title":"Omnium Sanctorum Duplex I classis cum octava communi vide Commune Plurium Martyrum Pontificum (Missa Intret) [Commune/C3.txt]","winner":"Sancti/11-01.txt","rule":"9 lectiones\nGloria\nCredo\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>audeámus omnes in Dómino, diem festum celebrántes sub honóre Sanctórum ómnium: de quorum sollemnitáte gaudent Angeli et colláudant Fílium Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 32:1\u003c/I>\u003c/FONT>\u003cbr/>\nExsultáte, justi, in Dómino: rectos decet collaudátio.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>audeámus omnes in Dómino, diem festum celebrántes sub honóre Sanctórum ómnium: de quorum sollemnitáte gaudent Angeli et colláudant Fílium Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>legremo-nos todos no Senhor, neste dia em que celebramos a festa em honra de Todos os Santos, de cuja solenidade se regozijam os Anjos, louvando unissonamente o Filho de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 32:1\u003c/I>\u003c/FONT>\u003cbr/>\nAclamai o Senhor, ó justos; pois é aos que possuem o coração recto que pertence louvar o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>legremo-nos todos no Senhor, neste dia em que celebramos a festa em honra de Todos os Santos, de cuja solenidade se regozijam os Anjos, louvando unissonamente o Filho de Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui nos ómnium Sanctórum tuórum mérita sub una tribuísti celebritáte venerári: quǽsumus; ut desiderátam nobis tuæ propitiatiónis abundántiam, multiplicátis intercessóribus, largiáris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nOmnipotente e eterno Deus, que nos permitistes a graça de celebrar em uma só festividade os méritos de todos vossos Santos, concedei-nos, Vos rogamos, que, assistidos de tão numerosos intercessores, alcancemos cada vez mais a abundância tão desejada das vossas graças.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Apocalýpsis beáti Joánnis Apóstoli.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 7:2-12\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Ecce, ego Joánnes vidi álterum Angelum ascendéntem ab ortu solis, habéntem signum Dei vivi: et clamávit voce magna quátuor Angelis, quibus datum est nocére terræ et mari, dicens: Nolíte nocére terræ et mari neque arbóribus, quoadúsque signémus servos Dei nostri in fróntibus eórum. Et audívi númerum signatórum, centum quadragínta quátuor mília signáti, ex omni tribu filiórum Israël. Ex tribu Juda duódecim mília signáti. Ex tribu Ruben duódecim mília signáti. Ex tribu Gad duódecim mília signati. Ex tribu Aser duódecim mília signáti. Ex tribu Néphthali duódecim mília signáti. Ex tribu Manásse duódecim mília signáti. Ex tribu Símeon duódecim mília signáti. Ex tribu Levi duódecim mília signáti. Ex tribu Issachar duódecim mília signati. Ex tribu Zábulon duódecim mília signáti. Ex tribu Joseph duódecim mília signati. Ex tribu Bénjamin duódecim mília signáti. Post hæc vidi turbam magnam, quam dinumeráre nemo póterat, ex ómnibus géntibus et tríbubus et pópulis et linguis: stantes ante thronum et in conspéctu Agni, amícti stolis albis, et palmæ in mánibus eórum: et clamábant voce magna, dicéntes: Salus Deo nostro, qui sedet super thronum, et Agno. Et omnes Angeli stabant in circúitu throni et seniórum et quátuor animálium: et cecidérunt in conspéctu throni in fácies suas et adoravérunt Deum, dicéntes: Amen. Benedíctio et cláritas et sapiéntia et gratiárum áctio, honor et virtus et fortitúdo Deo nostro in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro do Apocalipse do B. Ap.º João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 7:2-12\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, eu, João, vi um outro Anjo que subia do lado do nascer do sol, tendo na mão o sinal de Deus vivo e clamando com voz forte aos quatro Anjos, que haviam recebido o poder de ferirem a terra e o mar, e dizendo: «Não prejudiqueis nem a terra, nem o mar, nem as árvores, enquanto não houvermos marcado na fronte os servos do nosso Deus». E ouvi que o número daqueles que haviam sido marcados com o sinal, eram cento e quarenta e quatro mil de todas as tribos de Israel: havia doze mil da tribo de Judá, marcados com o sinal; doze mil da tribo de Ruben, marcados com o sinal; doze mil da tribo de Gad, marcados com o sinal; doze mil da tribo de Aser, marcados com o sinal; doze mil da tribo de Naftali, marcados com o sinal; doze mil da tribo de Manassés, marcados com o sinal; doze mil da tribo de Simeão, marcados com o sinal; doze mil da tribo de Levi, marcados com o sinal; doze mil da tribo de Issacar, marcados com o sinal; doze mil da tribo de Zabulão, marcados com o sinal; doze mil da tribo de José, marcados com o sinal; e doze mil da tribo de Benjamim, marcados com o sinal. Depois disto vi uma grande multidão \u003cFONT SIZE='1' COLOR=\"red\">que ninguém podia contar\u003c/FONT> de todas as nações, de todas as tribos, de todos os povos e de todas as línguas, que estavam de pé, diante do trono e do Cordeiro, vestidos com túnicas brancas, empunhando palmas e clamando com voz forte: «Glória ao nosso Deus, que está sentado no trono, e ao Cordeiro!». E todos os Anjos se conservaram em volta do trono, dos anciãos e dos quatro animais. E, prostrados diante do trono e com o rosto em terra, adoravam Deus, dizendo: «Amen! Bênção, glória, sabedoria, acção de graças, honra, soberania e império ao nosso Deus em todos os séculos. Amen».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 33:10; 33:11\u003c/I>\u003c/FONT>\u003cbr/>\nTiméte Dóminum, omnes Sancti ejus: quóniam nihil deest timéntibus eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Inquiréntes autem Dóminum, non defícient omni bono. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 11:28\u003c/I>\u003c/FONT>\u003cbr/>\nVeníte ad me, omnes, qui laborátis et oneráti estis: et ego refíciam vos. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 33:10; 33:11\u003c/I>\u003c/FONT>\u003cbr/>\nTemei o Senhor, ó vós, que sois os seus Anjos; pois àqueles que O temem nada faltará.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Aqueles que procuram o Senhor não serão privados de nenhum bem. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 11:28\u003c/I>\u003c/FONT>\u003cbr/>\nVinde a mim, vós, todos, que estais aflitos: e Eu vos aliviarei. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:1-12\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Videns Jesus turbas, ascéndit in montem, et cum sedísset, accessérunt ad eum discípuli ejus, et apériens os suum, docébat eos, dicens: Beáti páuperes spíritu: quóniam ipsórum est regnum cœlórum. Beáti mites: quóniam ipsi possidébunt terram. Beáti, qui lugent: quóniam ipsi consolabúntur. Beáti, qui esúriunt et sítiunt justítiam: quóniam ipsi saturabúntur. Beáti misericórdes: quóniam ipsi misericórdiam consequántur. Beáti mundo corde: quóniam ipsi Deum vidébunt. Beáti pacífici: quóniam fílii Dei vocabúntur. Beáti, qui persecutiónem patiúntur propter justítiam: quóniam ipsórum est regnum cœlórum. Beáti estis, cum maledíxerint vobis et persecúti vos fúerint, et díxerint omne malum advérsum vos, mentiéntes, propter me: gaudete et exsultáte, quóniam merces vestra copiósa est in cœlis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:1-12\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, vendo Jesus as turbas do povo, que O seguiam, subiu para uma montanha. Então assentou-se, aproximando-se d’Ele os discípulos. Depois, tomando a palavra, pregou assim aos seus discípulos: «Bem-aventurados os pobres de espírito, porque deles é o reino dos céus. Bem-aventurados os mansos, porque possuirão a terra. Bem-aventurados os que choram, porque serão consolados. Bem-aventurados os que têm fome e sede de justiça, porque serão saciados. Bem-aventurados os misericordiosos, porque serão tratados com misericórdia. Bem-aventurados os que possuem o coração puro, porque verão Deus. Bem-aventurados os pacíficos, porque serão chamados filhos de Deus. Bem-aventurados os que sofrem perseguição por amor da justiça, porque lhes pertencerá o reino dos céus. Bem-aventurados, vós, quando os homens vos amaldiçoarem, perseguirem e caluniarem por minha causa: regozijai-vos, então, e exultai de alegria, pois uma copiosa recompensa vos está preparada nos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sap 3:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nJustórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 3:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nAs almas dos justos estão nas mãos de Deus e o tormento da malícia as não tocará! Aos olhos dos insensatos pareciam quase a morrer, todavia estão na paz. Aleluia.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nMúnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos oferecemos, Senhor, estes dons da nossa devoção; e, em atenção aos merecimentos dos vossos justos, dignai-Vos aceitá-los, e pela vossa misericórdia fazei que nos sejam salutares.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti mundo corde, quóniam ipsi Deum vidébunt; beáti pacífici, quóniam filii Dei vocabúntur: beáti, qui persecutiónem patiúntur propter justítiam, quóniam ipsórum est regnum cœlórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados os que possuem o coração puro, porque verão a Deus; bem-aventurados os pacíficos, porque serão chamados filhos de Deus; bem-aventurados os que sofrem perseguição por amor da justiça, porque o reino do céu lhes pertence.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDa, quǽsumus, Dómine, fidélibus pópulis ómnium Sanctórum semper veneratióne lætári: et eórum perpétua supplicatióne muníri.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, Vos rogamos, fazei que os vossos povos fiéis venerem sempre com alegria os vossos Santos e sejam sempre protegidos pela sua intercessão.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-02":{"date":"2027-11-02","title":"Todos os Fiéis Defuntos","forms":[{"number":1,"title":"In Commemoratione Omnium Fidelium Defunctorum I. classis ex Officium defunctorum [Commune/C9.txt]","winner":"Sancti/11-02m1.txt","rule":"ex C9\nno Gloria\nno Credo\nPrefatio=Defunctorum\nmultiple3\nSequentia\n\n","gloria":false,"credo":false,"omitPsalm":true,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFidélium, Deus, ómnium Cónditor et Redémptor: animábus famulórum famularúmque tuárum remissiónem cunctórum tríbue peccatórum; ut indulgéntiam, quam semper optavérunt, piis supplicatiónibus consequántur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, Criador e Redentor de todos os fiéis, concedei às almas dos vossos servos a remissão de todos seus pecados, a fim de que pelas nossas humilíssimas orações alcancem da vossa misericórdia o perdão que sempre desejaram.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:51-57\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Ecce, mystérium vobis dico: Omnes quidem resurgámus, sed non omnes immutábimur. In moménto, in ictu óculi, in novíssima tuba: canet enim tuba, et mórtui resúrgent incorrúpti: et nos immutábimur. Opórtet enim corruptíbile hoc induere incorruptiónem: et mortále hoc indúere immortalitátem. Cum autem mortále hoc indúerit immortalitátem, tunc fiet sermo, qui scriptus est: Absórpta est mors in victória. Ubi est, mors, victória tua? Ubi est, mors, stímulus tuus? Stímulus autem mortis peccátum est: virtus vero peccáti lex. Deo autem grátias, qui dedit nobis victóriam per Dóminum nostrum Jesum Christum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:51-57\u003c/I>\u003c/FONT>\u003cbr/>\nIrmãos: Eis um mystério que vos revelo: Ressuscitaremos todos certamente; mas não seremos todos mudados. Num instante, num abrir e fechar de olhos, ao som da última trombeta, porque, então a trombeta soará e os mortos ressuscitarão incorruptíveis, e nós seremos transmudados. Pois é preciso que este corpo corruptível se revista da incorruptibilidade, e que este corpo mortal se revista da imortalidade. Quando este corpo corruptível se revestir da incorruptibilidade e este corpo mortal se revestir da imortalidade, então se cumprirá a palavra que está escrita: «A morte foi absorvida pela vitória. Onde está, ó morte, a tua vitória? Onde está, ó morte, o teu aguilhão?». Ora, o aguilhão da morte é o pecado; e a força do pecado é a lei. Graças, pois, sejam rendidas a Deus, que nos concedeu a vitória por Jesus Cristo, Senhor nosso.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 5:25-29\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Amen, amen, dico vobis, quia venit hora, et nunc est, quando mórtui áudient vocem Fílii Dei: et qui audíerint, vivent. Sicut enim Pater habet vitam in semetípso, sic dedit et Fílio habére vitam in semetípso: et potestátem dedit ei judícium fácere, quia Fílius hóminis est. Nolíte mirári hoc, quia venit hora, in qua omnes, qui in monuméntis sunt, áudient vocem Fílii Dei: et procédent, qui bona fecérunt, in resurrectiónem vitæ: qui vero mala egérunt, in resurrectiónem judícii.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 5:25-29\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas dos judeus: «Em verdade, em verdade vos digo: A hora chega \u003cFONT SIZE='1' COLOR=\"red\">ela chegou já\u003c/FONT> em que os mortos ouvirão a voz do Filho de Deus; e os que a ouvirem, viverão. Porque, assim como o Pai tem a vida em si, assim Ele deu ao Filho o poder de ter a vida em si; e deu-lhe, também, o poder de julgar, pois Ele é o Filho do homem. Não vos admireis disto, pois vem a hora em que todos aqueles que estão nos túmulos ouvirão a voz do Filho de Deus. Então, aqueles que tiverem praticado obras boas sairão para a ressurreição da vida eterna; e aqueles que tiverem praticado obras más ressuscitarão para a condenação».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias, quǽsumus, Dómine, quas tibi pro animábus famulórum famularúmque tuárum offérimus, propitiátus inténde: ut, quibus fídei christiánæ méritum contulísti, dones et prǽmium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOlhai benigno, Senhor, Vos suplicamos, para as hóstias que Vos oferecemos pelas almas dos vossos servos, a fim de que, depois de lhes haverdes concedido o dom da fé cristã, lhes proporcioneis a recompensa.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nAnimábus, quǽsumus, Dómine, famulórum famularúmque tuárum orátio profíciat supplicántium: ut eas et a peccátis ómnibus éxuas, et tuæ redemptiónis fácias esse partícipes:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue as nossas humildes preces sejam proveitosas às almas dos vossos servos e servas, a fim de que, soltas das cadeias dos seus pecados, participem dos frutos da vossa redenção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[],"full":[{"label":"Incipit","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Incipit\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos paratus cum ingreditur ad Altare, facta illi debita reverentia, signat se signo crucis a fronte ad pectus, et clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n nómine Patris, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> et Fílii, et Spíritus Sancti. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Início\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>De pé, diante dos degraus do altar, o Sacerdote começa a Missa, fazendo o sinal da cruz e com uma voz clara e audível diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m nome do Pai, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e do Filho, e do Espírito Santo. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum, et in Missis de Tempore a Dominica Passionis usque ad Sabbatum sanctum exclusive, omittitur Psalmus Júdica me, Deus, cum Glória Patri, et repetitione Antiphonæ, sed dicto In nómine Patris, Introíbo, et Adjutórium, fit conféssio, ut sequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos e do Tempo da Paixão este salmo omite-se.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus ante pectus, incipit Antiphonam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Introíbo ad altáre Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Ad Deum, qui lætíficat juventútem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Juntando as mãos no peito, começa a antífona:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu irei até ao altar de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Até Deus, que é a alegria da minha juventude.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Signat se, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Adjutórium nostrum \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> in nómine Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Qui fecit cælum et terram.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde junctis manibus profunde inclinatus facit Confessionem.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onfíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et vobis, fratres: quia peccávi nimis cogitatióne, verbo et ópere: \u003cFONT SIZE='1' COLOR=\"red\">Percutit sibi pectus ter, dicens:\u003c/FONT> mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et vos, fratres, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Misereátur tui omnípotens Deus, et, dimíssis peccátis tuis, perdúcat te ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>et erigit se. Deinde Ministri repetunt Confessionem: et ubi a Sacerdote dicebatur vobis, fratres, et vos, fratres, a Ministris dicitur tibi, pater, et te, pater.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et ópere: mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea Sacerdos, junctis manibus, facit absolutionem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Signat se signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Indulgéntiam, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> absolutiónem et remissiónem peccatórum nostrórum tríbuat nobis omnípotens et miséricors Dóminus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote fazendo o sinal da cruz diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O nosso auxílio está \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> no nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que criou o céu e a terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz o Confíteor, humilhando-se publicamente:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, irmãos:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, irmãos, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Compadeça-se de ti o Senhor omnipotente; perdoe os teus pecados e te guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito diz o confiteor.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, Padre:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, Padre, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote, juntando as mãos, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Compadeça-se de vós o Senhor omnipotente; perdoe os vossos pecados e vos guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Fazendo o sinal da cruz, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que o Senhor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipotente e misericordioso nos conceda o perdão, a absolvição e a remissão dos nossos pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Et inclinatus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Deus, tu convérsus vivificábis nos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et plebs tua lætábitur in te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Osténde nobis, Dómine, misericórdiam tuam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et salutáre tuum da nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, exáudi oratiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et clamor meus ad te véniat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et extendens ac jungens manus, clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus, \u003cFONT SIZE='1' COLOR=\"red\">ei ascendens ad Altare, dicit secreto: \u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ufer a nobis, quǽsumus, Dómine, iniquitátes nostras: ut ad Sancta sanctórum puris mereámur méntibus introíre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus junctis super Altare, inclinatus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rámus te, Dómine, per mérita Sanctórum tuórum, \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare in medio\u003c/FONT> quorum relíquiæ hic sunt, et ómnium Sanctórum: ut indulgére dignéris ómnia peccáta mea. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, prossegue:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ó Deus, volvei-Vos para nós, e alcançaremos a vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E o vosso povo alegrar-se-á em Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Mostrai-nos, Senhor, a vossa misericórdia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E concedei-nos a vossa salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ouvi, Senhor, a minha oração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E que o meu clamor chegue até Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote sobe ao altar dizendo, entretanto:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>fastai de nós, Senhor, Vos imploramos, as nossas iniquidades,  \u003cbr/>\npara que mereçamos entrar no santuário com as almas purificadas.  \u003cbr/>\nPor Cristo, Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com as mãos juntas, inclinado sobre o altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os pedimos, Senhor, pelos méritos dos vossos Santos, cujas relíquias estão aqui \u003cFONT SIZE='1' COLOR=\"red\">beija o altar\u003c/FONT>,  \u003cbr/>\ne de todos os Santos, que Vos digneis perdoar os nossos pecados. Amém.\u003cbr/>\n"},{"label":"Introitus","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"},{"label":"Kyrie","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Qua finita, junctis manibus, et alternatim cum Ministris, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O celebrante, no meio do altar, diz, alternadamente com os assistentes:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n"},{"label":"Gloria","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Gloria\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Glória\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Oratio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare in medio, et versus ad populum dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Orationes, unam aut plures, ut ordo Officii postulat. Sequitur Epistola, Graduale, Tractus, vel Allelúja cum Versu, aut Sequentia, prout Tempus aut qualitas Missæ postulat.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFidélium, Deus, ómnium Cónditor et Redémptor: animábus famulórum famularúmque tuárum remissiónem cunctórum tríbue peccatórum; ut indulgéntiam, quam semper optavérunt, piis supplicatiónibus consequántur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote benze-se, beija o altar, volta-se para os fiéis e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Breve oração que resume e apresenta a Deus os votos de todos os fiéis, votos estes sugeridos pelo mistério ou solenidade do dia.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, Criador e Redentor de todos os fiéis, concedei às almas dos vossos servos a remissão de todos seus pecados, a fim de que pelas nossas humilíssimas orações alcancem da vossa misericórdia o perdão que sempre desejaram.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"},{"label":"Lectio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:51-57\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Ecce, mystérium vobis dico: Omnes quidem resurgámus, sed non omnes immutábimur. In moménto, in ictu óculi, in novíssima tuba: canet enim tuba, et mórtui resúrgent incorrúpti: et nos immutábimur. Opórtet enim corruptíbile hoc induere incorruptiónem: et mortále hoc indúere immortalitátem. Cum autem mortále hoc indúerit immortalitátem, tunc fiet sermo, qui scriptus est: Absórpta est mors in victória. Ubi est, mors, victória tua? Ubi est, mors, stímulus tuus? Stímulus autem mortis peccátum est: virtus vero peccáti lex. Deo autem grátias, qui dedit nobis victóriam per Dóminum nostrum Jesum Christum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 15:51-57\u003c/I>\u003c/FONT>\u003cbr/>\nIrmãos: Eis um mystério que vos revelo: Ressuscitaremos todos certamente; mas não seremos todos mudados. Num instante, num abrir e fechar de olhos, ao som da última trombeta, porque, então a trombeta soará e os mortos ressuscitarão incorruptíveis, e nós seremos transmudados. Pois é preciso que este corpo corruptível se revista da incorruptibilidade, e que este corpo mortal se revista da imortalidade. Quando este corpo corruptível se revestir da incorruptibilidade e este corpo mortal se revestir da imortalidade, então se cumprirá a palavra que está escrita: «A morte foi absorvida pela vitória. Onde está, ó morte, a tua vitória? Onde está, ó morte, o teu aguilhão?». Ora, o aguilhão da morte é o pecado; e a força do pecado é a lei. Graças, pois, sejam rendidas a Deus, que nos concedeu a vitória por Jesus Cristo, Senhor nosso.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Graduale","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"},{"label":"Evangelium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur Munda cor meum, sed non petitur benedictio, non deferuntur luminaria, nec Celebrans osculatur librum.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>unda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, conversus ad librum, junctis manibus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et pronuntians: Inítium, sive Sequéntia sancti Evangélii, signat librum, et se in fronte, ore et pectore, et legit Evangelium, ut dictum est. Quo finito, respondet Minister: Laus tibi, Christe.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 5:25-29\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Amen, amen, dico vobis, quia venit hora, et nunc est, quando mórtui áudient vocem Fílii Dei: et qui audíerint, vivent. Sicut enim Pater habet vitam in semetípso, sic dedit et Fílio habére vitam in semetípso: et potestátem dedit ei judícium fácere, quia Fílius hóminis est. Nolíte mirári hoc, quia venit hora, in qua omnes, qui in monuméntis sunt, áudient vocem Fílii Dei: et procédent, qui bona fecérunt, in resurrectiónem vitæ: qui vero mala egérunt, in resurrectiónem judícii.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos, o Munda cor é dito, mas a bênção não é pedida, e o padre não beija o Evangelho.\u003c/I>\u003c/FONT>\u003cbr/>\nÓ omnipotente Deus, assim como purificastes os lábios do Profeta Isaías com uma brasa de fogo,  \u003cbr/>\nassim também purificais agora o meu coração e os meus lábios.  \u003cbr/>\nDignai-Vos, pela vossa benigna misericórdia, purificar-me inteiramente,  \u003cbr/>\npara que possa anunciar dignamente o vosso Evangelho. Por Cristo Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Virando-se para o livro, com as mãos juntas diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 5:25-29\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas dos judeus: «Em verdade, em verdade vos digo: A hora chega \u003cFONT SIZE='1' COLOR=\"red\">ela chegou já\u003c/FONT> em que os mortos ouvirão a voz do Filho de Deus; e os que a ouvirem, viverão. Porque, assim como o Pai tem a vida em si, assim Ele deu ao Filho o poder de ter a vida em si; e deu-lhe, também, o poder de julgar, pois Ele é o Filho do homem. Não vos admireis disto, pois vem a hora em que todos aqueles que estão nos túmulos ouvirão a voz do Filho de Deus. Então, aqueles que tiverem praticado obras boas sairão para a ressurreição da vida eterna; e aqueles que tiverem praticado obras más ressuscitarão para a condenação».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"},{"label":"Credo","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo&nbsp;\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Offertorium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare, et versus ad populum, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Offertorium.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O padre beija o altar, e virando-se para o povo diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois o padre entra no Sacrifício da Missa e exalta os fiéis para rezarem com ele.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Quo dicto, si est Missa sollemnis, Diaconus porrigit Celebranti Patenam cum Hostia: si privata, Sacerdos ipse accipit Patenam cum Hostia, quam offerens, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancte Pater, omnípotens ætérne Deus, hanc immaculátam hóstiam, quam ego indígnus fámulus tuus óffero tibi Deo meo vivo et vero, pro innumerabílibus peccátis, et offensiónibus, et neglegéntiis meis, et pro ómnibus circumstántibus, sed et pro ómnibus fidélibus christiánis vivis atque defúnctis: ut mihi, et illis profíciat ad salútem in vitam ætérnam. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Terminada esta leitura, o Sacerdote descobre o Cálice e toma nas mãos a patena com o pão, que vai ser consagrado. O Sacerdote oferece-os a Deus, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Pai santo, Deus omnipotente e eterno, esta hóstia imaculada, que eu, vosso indigno servo, Vos ofereço,  \u003cbr/>\nó meu Deus vivo e verdadeiro, pelos meus inumeráveis pecados, ofensas e negligências, por todos os assistentes  \u003cbr/>\ne por todos os cristãos vivos e mortos, a fim de que sirva de proveito para a minha salvação,  \u003cbr/>\npara a deles e para a vida eterna. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde faciens crucem cum eadem Patena, deponit Hostiam super Corporale. Diaconus ministrat vinum, Subdiaconus aquam in Calice: vel si privata est Missa, utrumque infundit Sacerdos, et aquam miscendam in Calice benedicit signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> qui humánæ substántiæ dignitátem mirabíliter condidísti, et mirabílius reformásti: da nobis per hujus aquæ et vini mystérium, ejus divinitátis esse consórtes, qui humanitátis nostræ fíeri dignátus est párticeps, Jesus Christus, Fílius tuus, Dóminus noster: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Ao lado direito do altar, o celebrante coloca vinho no cálice, ao qual mistura umas gotas de água, dizendo a seguinte oração:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> que maravilhosamente criastes a dignidade da natureza humana e que mais prodigiosamente ainda a reformastes,  \u003cbr/>\npermiti que pela mistura simbólica desta água e deste vinho sejamos participantes da divindade  \u003cbr/>\ndaquele que quis assumir a nossa humanidade, Jesus Cristo, vosso Filho, Nosso Senhor, que, sendo Deus,  \u003cbr/>\nvive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur prædicta Oratio: sed aqua non benedicitur.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Em Missas para Defuntos, a seguinte oração é dita, mas a água não é abençoada.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea accipit Calicem, et offert dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>fférimus tibi, Dómine, cálicem salutáris, tuam deprecántes cleméntiam: ut in conspéctu divínæ majestátis tuæ, pro nostra et totíus mundi salúte, cum odóre suavitátis ascéndat. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde facit signum crucis cum Calice, et illum ponit super Corporale, et Palla cooperit: tum, junctis manibus super Altare, aliquantulum inclinatus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n spíritu humilitátis et in ánimo contríto suscipiámur a te, Dómine: et sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi, Dómine Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Erectus expandit manus, easque in altum porrectas jungens, elevátis ad cælum oculis et statim demissis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eni, sanctificátor omnípotens ætérne Deus: \u003cFONT SIZE='1' COLOR=\"red\">Benedicit Oblata, prosequendo:\u003c/FONT> et béne \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dic hoc sacrifícium, tuo sancto nómini præparátum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>No meio do altar, o celebrante faz o oferecimento do cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>ós Vos oferecemos, Senhor, o Cálice da salvação; e Vos suplicamos que misericordiosamente o façais subir,  \u003cbr/>\ncomo suave perfume, diante da vossa divina majestade, para a nossa salvação e de todo o mundo. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, inclinando-se diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m humildade e contrição, sejamos recebidos por Vós, Senhor;  \u003cbr/>\ne assim este sacrifício, ó Deus, se torne agradável aos vossos olhos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Invocação do Espírito Santo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>inde, ó Santificador omnipotente, Deus eterno, e abençoai \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> este sacrifício, preparado para a glória do vosso Santo Nome.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Sacerdos lavat manus, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps. 25, 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avábo inter innocéntes manus meas: et circúmdabo altáre tuum, Dómine: Ut áudiam vocem laudis, et enárrem univérsa mirabília tua. Dómine, diléxi decórem domus tuæ et locum habitatiónis glóriæ tuæ. Ne perdas cum ímpiis, Deus, ánimam meam, et cum viris sánguinum vitam meam: In quorum mánibus iniquitátes sunt: déxtera eórum repléta est munéribus. Ego autem in innocéntia mea ingréssus sum: rédime me et miserére mei. Pes meus stetit in dirécto: in ecclésiis benedícam te, Dómine.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O lavar das mãos simboliza a pureza da alma, necessária para oferecer o santo Sacrifício. O Sacerdote vai à direita do altar e lava as mãos, dizendo, entretanto, os seguintes versículos do salmo 25:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Psalm 25. 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avarei as minhas mãos, como os inocentes, e rodearei, Senhor o vosso altar:  \u003cbr/>\nPara ouvir a voz dos vossos louvores e publicar todas as vossas maravilhas.  \u003cbr/>\nAmei, Senhor, o decoro da vossa casa e o lugar onde reside a vossa glória.  \u003cbr/>\nNão deixeis, ó meu Deus, que a minha alma se perca com os ímpios, nem a minha vida com os homens sanguinários,  \u003cbr/>\nque têm as mãos manchadas de iniquidades e a mão direita cheia de dádivas.  \u003cbr/>\nPois que tenho vivido na inocência, salvai-me e tende misericórdia de mim.  \u003cbr/>\nOs meus pés continuam firmes no caminho direito: e hei-de bendizer-Vos, Senhor, em todas as assembleias.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, aliquantulum inclinatus in medio Altaris, junctis manibus super eo, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancta Trínitas, hanc oblatiónem, quam tibi offérimus ob memóriam passiónis, resurrectiónis, et ascensiónis Jesu Christi, Dómini nostri: et in honórem beátæ Maríæ semper Vírginis, et beáti Joannis Baptistæ, et sanctórum Apostolórum Petri et Pauli, et istórum et ómnium Sanctórum: ut illis profíciat ad honórem, nobis autem ad salútem: et illi pro nobis intercédere dignéntur in cælis, quorum memóriam ágimus in terris. Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, ao meio do altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Santíssima Trindade, esta oblação, que Vos oferecemos em memória da Paixão, da Ressurreição  \u003cbr/>\ne da Ascensão de Nosso Senhor Jesus Cristo: e em honra da bem-aventurada sempre Virgem Maria, do bem-aventurado João Baptista  \u003cbr/>\ne dos Santos Apóstolos Pedro e Paulo, e destes, que estão aqui, e de todos os Santos: para que esta oblação  \u003cbr/>\nlhes sirva de glória e a nós de salvação: e aqueles, cuja memória honramos na terra, se dignem interceder por nós no céu.  \u003cbr/>\nPelo mesmo Jesus Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea osculatur Altare, et versus ad populum extendens, et jungens manus, voce paululum elevata, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Oráte, fratres: ut meum ac vestrum sacrifícium acceptábile fiat apud Deum Patrem omnipoténtem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Minister, seu circumstantes respondent: alioquin ipsemet Sacerdos:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Suscípiat Dóminus sacrifícium de mánibus tuis \u003cFONT SIZE='1' COLOR=\"red\">vel meis\u003c/FONT> ad laudem et glóriam nominis sui, ad utilitátem quoque nostram, totiúsque Ecclésiæ suæ sanctæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos submissa voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus extensis, absolute sine Orémus subjungit Orationes secretas.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias, quǽsumus, Dómine, quas tibi pro animábus famulórum famularúmque tuárum offérimus, propitiátus inténde: ut, quibus fídei christiánæ méritum contulísti, dones et prǽmium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Beija o Altar e voltando-se para os fiéis, o Sacerdote convida-os a orar com ele:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Orai, meus irmãos, a fim de que o meu sacrifício, que é também vosso, seja recebido por Deus Pai omnipotente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que o Senhor receba pelas tuas mãos este sacrifício para a honra e glória do seu Nome,  \u003cbr/>\ne também para a nossa utilidade e de toda sua santa Igreja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde, em voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Em seguida lê a Secreta. À Secreta principal, podem, em certas Missas, juntar-se outras, em número igual \u003c/I>\u003c/FONT> \u003cbr/>\ne segundo as mesmas regras da Colecta.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOlhai benigno, Senhor, Vos suplicamos, para as hóstias que Vos oferecemos pelas almas dos vossos servos, a fim de que, depois de lhes haverdes concedido o dom da fé cristã, lhes proporcioneis a recompensa.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Præfatio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Præfatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus finitis, cum pervenerit ad conclusionem, clara voce dicit: Per ómnia sǽcula sæculórum, cum Præfatione, ut in sequentibus. Præfationem incipit ambabus manibus positis hinc inde super Altare: quas aliquantulum elevat, cum dicit: Sursum corda. Jungit eas ante pectus, et caput inclinat, cum dicit: Grátias agamus Dómino, Deo nostro. Deinde disjungit manus, et disjunctas tenet usque ad finem Præfationis: qua finita, iterum jungit eas, et inclinatus dicit: Sanctus. Et cum dicit: Benedíctus, qui venit, signum crucis sibi producit a fronte ad pectus.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sursum corda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Habémus ad Dóminum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Grátias agámus Dómino, Deo nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Dignum et justum est.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctus, Sanctus, Sanctus Dóminus, Deus Sábaoth. Pleni sunt cæli et terra glória tua. Hosánna in excélsis. Benedíctus, qui venit in nómine Dómini. Hosánna in excélsis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com o Prefácio, começa a grande, a solene oração sacerdotal da Igreja e a oblação propriamente dita do Sacrifício. Curto diálogo introdutório entre o Sacerdote e os fiéis desperta nas almas os sentimentos de acção de graças que convêm à celebração dos santos mistérios.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Corações ao alto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim os temos para o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Demos graças ao Senhor, Nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim é digno e justo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anto, Santo, Santo, Senhor Deus do Universo. O céu e a terra proclamam a vossa glória. Hossana nas alturas.  \u003cbr/>\nBendito o que vem em nome do Senhor. Hosana nas alturas.\u003cbr/>\n"},{"label":"Canon","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Canon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finita præfatione, sacerdos extendens, elevans aliquantulum et iungens manus, elevansque ad cælum oculos, et statim demittens, profunde inclinatus ante Altare, manibus super eo positis, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>e ígitur, clementíssime Pater, per Jesum Christum, Fílium tuum, Dóminum nostrum, súpplices rogámus, ac pétimus, \u003cFONT SIZE='1' COLOR=\"red\">osculatur Altare et, junctis manibus ante pectus, dicit:\u003c/FONT> uti accépta hábeas et benedícas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam et Calicem simul, dicens:\u003c/FONT> hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dona, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> múnera, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sancta sacrifícia illibáta, \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT> in primis, quæ tibi offérimus pro Ecclésia tua sancta cathólica: quam pacificáre, custodíre, adunáre et régere dignéris toto orbe terrárum: una cum fámulo tuo Papa nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et Antístite nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et ómnibus orthodóxis, atque cathólicæ et apostólicæ fídei cultóribus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Cânon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós, pois, rogamos e pedimos, ó clementíssimo Pai, por Jesus Cristo, vosso Filho e Nosso Senhor,  \u003cbr/>\nque estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dons, estas \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ofertas, estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sacrifícios santos e imaculados Vos sejam agradáveis e os abençoeis,  \u003cbr/>\nos quais, antes de tudo, Vos oferecemos pela nossa santa Igreja Católica: dignai-Vos conceder-lhe a paz, guardá-la,  \u003cbr/>\nuni-la e governá-la por toda a terra, em comunhão com vosso servo, o nosso Papa \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, com o nosso Bispo \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  \u003cbr/>\ne com todos os \u003cFONT SIZE='1' COLOR=\"red\">bispos\u003c/FONT> ortodoxos e os que professam a fé católica e apostólica.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro vivis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto, Dómine, famulórum famularúmque tuarum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquantulum pro quibus orare intendit: deinde manibus extensis prosequitur:\u003c/FONT> et ómnium circumstántium, quorum tibi fides cógnita est et nota devótio, pro quibus tibi offérimus: vel qui tibi ófferunt hoc sacrifícium laudis, pro se suísque ómnibus: pro redemptióne animárum suárum, pro spe salútis et incolumitátis suæ: tibíque reddunt vota sua ætérno Deo, vivo et vero.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Memento dos vivos\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, dos vossos servos \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e de todos os que aqui estão presentes, cuja fé Vos é conhecida  \u003cbr/>\ne a piedade é notória: pelos quais Vos oferecemos, ou eles Vos oferecem, este sacrifício de louvor por si próprios  \u003cbr/>\ne por todos os seus, pela redenção das suas almas, pela esperança da sua salvação: é a Vós que oferecem as homenagens,  \u003cbr/>\ncomo Deus eterno, vivo e verdadeiro, que sois.\u003cbr/>\n"},{"label":"communicantes","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n \u003cbr/>\net beatórum Apostolórum ac Mártyrum tuórum, Petri et Pauli, Andréæ, Jacóbi, Joánnis, Thomæ, Jacóbi, Philíppi, Bartholomǽi, Matthǽi, Simónis et Thaddǽi: Lini, Cleti, Cleméntis, Xysti, Cornélii, Cypriáni, Lauréntii, Chrysógoni, Joánnis et Pauli, Cosmæ et Damiáni: et ómnium Sanctórum tuórum; quorum méritis precibúsque concédas, ut in ómnibus protectiónis tuæ muniámur auxílio. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n \u003cbr/>\ne depois também a dos vossos bem-aventurados Apóstolos e Mártires: Pedro e Paulo, André, Tiago, João, Tomé, Tiago,  \u003cbr/>\nFilipe, Bartolomeu, Mateus, Simão e Tadeu: Lino, Cleto, Clemente, Xisto, Cornélio, Cipriano, Lourenço, Crisógono,  \u003cbr/>\nJoão e Paulo, Cosme e Damião: e de todos vossos Santos.  \u003cbr/>\nDignai-Vos permitir que pelos seus méritos e preces gozemos do poderoso auxílio da vossa protecção.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tenens manus expansas super Oblata, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>anc ígitur oblatiónem servitútis nostræ, sed et cunctæ famíliæ tuæ,\u003cbr/>\n\u003cbr/>\nquǽsumus, Dómine, ut placátus accípias: diésque nostros in tua pace dispónas, atque ab ætérna damnatióne nos éripi, et in electórum tuórum júbeas grege numerári. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Estendendo as mãos sobre as oblatas, o celebrante diz::\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, Vos rogamos que Vos digneis receber favoravelmente esta oferta que eu,  \u003cbr/>\nvosso indigno servo, e toda a vossa família Vos fazemos;\u003cbr/>\n\u003cbr/>\nconcedei-nos o gozo da vossa paz nos nossos dias, livrai-nos da condenação eterna  \u003cbr/>\ne admiti-nos ao número dos vossos escolhidos. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uam oblatiónem tu, Deus, in ómnibus, quǽsumus, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Oblata,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díctam, adscríp \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, ra \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, rationábilem, acceptabilémque fácere dignéris: \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam,\u003c/FONT> ut nobis Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem,\u003c/FONT> et San \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guis fiat dilectíssimi Fílii tui, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus,\u003c/FONT> Dómini nostri Jesu Christi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta oblação, ó Deus, Vos imploramos, seja abençoada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> aprovada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> confirmada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> digna e aceitável,  \u003cbr/>\na fim de que se converta para nós no Corpo e no Sangue do vosso amado Filho, Nosso Senhor Jesus Cristo.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui prídie quam paterétur, \u003cFONT SIZE='1' COLOR=\"red\">Accipit Hostiam,\u003c/FONT> accépit panem in sanctas ac venerábiles manus suas, \u003cFONT SIZE='1' COLOR=\"red\">Elevat oculos ad cælum,\u003c/FONT> et elevátis óculis in cælum ad te Deum, Patrem suum omnipoténtem, \u003cFONT SIZE='1' COLOR=\"red\">Caput inclinat,\u003c/FONT> tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Signat super Hostiam,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, fregit, dedítque discípulis suis, dicens: Accípite, et manducáte ex hoc omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> qual, na véspera da sua paixão tomou o pão nas suas santas e veneráveis mãos: e, erguendo os olhos ao céu,  \u003cbr/>\na Vós, Deus seu Pai omnipotente, e dando-Vos graças, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoou-o, partiu-o e deu-o aos seus discípulos, dizendo:  \u003cbr/>\nTomai todos e comei:\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tenens ambabus manibus Hostiam inter indices et pollices, profert verba consecrationis secrete, distincte et attente super Hostiam, et simul super omnes, si plures sint consecrandæ.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHOC EST ENIM CORPUS MEUM.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, statim Hostiam consecratam genuflexus adorat: surgit, ostendit populo, reponit super Corporale, et genuflexus iterum adorat: nec amplius pollices et indices disjungit, nisi quando Hostia tractanda est, usque ad ablutionem digitorum.\u003c/I>\u003c/FONT>\u003cbr/>\nwait5\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras de Consagração do Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O MEU CORPO.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois de pronunciar as palavras de consagração, o padre, ajoelhado, adora a Sagrada Hóstia; levanta-se, elevando-a. -- Olha-a com fé, piedade e amor, dizendo: \"Meu Senhor e meu Deus.\" -- e colocando-a de volta no corporal, novamente a adora. Depois, nunca mais separa os dedos e polegar, excepto quando toma a Hóstia, até à lavagem dos dedos.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tunc, detecto Calice, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ímili modo postquam cenátum est, \u003cFONT SIZE='1' COLOR=\"red\">Ambabus manibus accipit Calicem,\u003c/FONT> accípiens et hunc præclárum Cálicem in sanctas ac venerábiles manus suas: \u003cFONT SIZE='1' COLOR=\"red\">item Caput inclinat,\u003c/FONT> item tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Sinistra tenens Calicem, dextera signat super eum,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, dedítque discípulis suis, dicens: Accípite, et bíbite ex eo omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Consagração e Elevação do Cálice:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>o mesmo modo, Jesus, após a Ceia, tomou nas suas santas e veneráveis mãos este precioso Cálice,  \u003cbr/>\ne, novamente, dando-Vos graças, abençoou-o \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e deu-o aos seus discípulos dizendo: Tomai e bebei dele todos,\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profert verba consecrationis super Calicem, attente, continuate, et secrete, tenens illum parum elevatum.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHIC EST ENIM CALIX SANGUINIS MEI, NOVI ET ÆTERNI TESTAMENTI: MYSTERIUM FIDEI: QUI PRO VOBIS ET PRO MULTIS EFFUNDETUR IN REMISSIONEM PECCATORUM.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, deponit Calicem super Corporale, et dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc quotiescúmque fecéritis, in mei memóriam faciétis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Genuflexus adorat: surgit, ostendit populo, deponit, cooperit, et genuflexus iterum adorat.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras da Consagração do Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O CÁLICE DO MEU SANGUE DO NOVO E ETERNO TESTAMENTO, MISTÉRIO DA FÉ, QUE SERÁ DERRAMADO POR VÓS E POR MUITOS, PARA REMISSÃO DOS PECADOS.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois da consagração do Cálice, o Sacerdote diz com uma voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as vezes que fizerdes isto, fazei-o em memória de mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O padre ajoelha-se e adora o Precioso Sangue; levanta-se, elevando o Cálice, e quando o baixa e o cobre, novamente o adora.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Deinde disjunctis manibus dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nde et mémores, Dómine, nos servi tui, sed et plebs tua sancta, ejúsdem Christi Fílii tui, Dómini nostri, tam beátæ passiónis, nec non et ab ínferis resurrectiónis, sed et in cælos gloriósæ ascensiónis: offérimus præcláræ majestáti tuæ de tuis donis ac datis, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> puram, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctam, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> immaculátam, \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam, dicens:\u003c/FONT> Panem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctum vitæ ætérnæ, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem, dicens:\u003c/FONT> et Cálicem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> salútis perpétuæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">O Sacerdote continua depois as orações do Cânon:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, nós, vossos servos, e o vosso povo santo,  \u003cbr/>\nlembrando-nos da bem-aventurada Paixão do mesmo Cristo, vosso Filho e Senhor nosso,  \u003cbr/>\nassim como também da sua Ressurreição dos mortos e da sua gloriosa Ascensão aos céus,  \u003cbr/>\noferecemos à vossa divina majestade os mesmos dons que nos foram dados:  \u003cbr/>\na Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pura, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santa, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> imaculada, o Pão \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santo da vida eterna e o Cálice \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> da salvação perpétua.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>upra quæ propítio ac seréno vultu respícere dignéris: et accépta habére, sicúti accépta habére dignátus es múnera púeri tui justi Abel, et sacrifícium Patriárchæ nostri Abrahæ: et quod tibi óbtulit summus sacérdos tuus Melchísedech, sanctum sacrifícium, immaculátam hóstiam.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Com as mãos afastadas, contínua:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>obre estas ofertas dignai-Vos lançar um olhar propício e benévolo e aceitá-las,  \u003cbr/>\ncomo Vos dignastes receber os dons do justo Abel, vosso servo, o sacrifício do nosso Patriarca Abraão  \u003cbr/>\ne o que Vos ofereceu o Sumo sacerdote Melquisedeque, pois este é um sacrifício santo, uma hóstia imaculada.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profunde inclinatus, junctis manibus et super Altare positis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úpplices te rogámus, omnípotens Deus: jube hæc perférri per manus sancti Angeli tui in sublíme altáre tuum, in conspéctu divínæ majestátis tuæ: ut, quotquot \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare,\u003c/FONT> ex hac altáris participatióne sacrosánctum Fílii tui \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat semel super Hostiam, et semel super Calicem,\u003c/FONT> Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, et Sán \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guinem sumpsérimus, \u003cFONT SIZE='1' COLOR=\"red\">Seipsum signat, dicens:\u003c/FONT> omni benedictióne cælésti et grátia repleámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>umildemente Vos rogamos, ó Deus omnipotente, ordeneis que estas ofertas sejam apresentadas  \u003cbr/>\nno altar sublime pelas mãos do vosso Santo Anjo, na presença da vossa divina majestade,  \u003cbr/>\na fim de que todos aqueles que participam deste Altar pela recepção do Santíssimo Corpo \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e Sangue \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do vosso Filho  \u003cbr/>\nsejam repletos de todas as bênçãos do céu e de todas as graças. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro defunctis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto étiam, Dómine, famulórum famularúmque tuárum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, qui nos præcessérunt cum signo fídei, et dórmiunt in somno pacis.wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquántulum pro iis defunctis, pro quibus orare intendit, deinde extensis manibus prosequitur:\u003c/FONT> Ipsis, Dómine, et ómnibus in Christo quiescéntibus locum refrigérii, lucis, et pacis, ut indúlgeas, deprecámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et caput inclinat, dicens:\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Memento dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-Vos também Senhor, dos vossos servos e servas \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, que partiram antes de nós,  \u003cbr/>\nmarcados com o sinal da fé, e agora dormem o sono da paz.wait10  \u003cbr/>\n\u003cFONT SIZE='1' COLOR=\"red\">Junta as mãos e ora por estes defuntos, depois, estendendo as mãos, continua:\u003c/FONT>  \u003cbr/>\nNós Vos suplicamos, Senhor, dignai-Vos conceder a estes, assim como a todos os que descansam em Cristo,  \u003cbr/>\num lugar de consolação, de luz e de paz. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Manu dextera percutit sibi pectus, elata aliquantulum voce dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>obis quoque peccatóribus \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus ut prius, secrete prosequitur:\u003c/FONT> fámulis tuis, de multitúdine miseratiónum tuárum sperántibus, partem áliquam et societátem donáre dignéris, cum tuis sanctis Apóstolis et Martýribus: cum Joánne, Stéphano, Matthía, Bárnaba, Ignátio, Alexándro, Marcellíno, Petro, Felicitáte, Perpétua, Agatha, Lúcia, Agnéte, Cæcília, Anastásia, et ómnibus Sanctis tuis: intra quorum nos consórtium, non æstimátor mériti, sed véniæ, quǽsumus, largítor admítte. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per Christum, Dóminum nostrum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>o Sacerdote bate no peito, dizendo.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT> também a nós, pecadores, vossos servos, que esperamos na grandeza das vossas misericórdias,  \u003cbr/>\ndignai-Vos conceder-nos alguma parte na vossa herança e sociedade com vossos Santos Apóstolos e Mártires:  \u003cbr/>\nJoão, Estêvão, Matias, Barnabé, Inácio, Alexandre, Marcelino, Pedro, Felicidade, Perpétua, Águeda, Luzia, Inês,  \u003cbr/>\nCecília, Anastácia e com todos os Santos, em cuja companhia, Vos pedimos, nos recebais,  \u003cbr/>\nnão em consideração dos nossos merecimentos, mas segundo a liberalidade da vossa misericórdia. Por Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er quem hæc ómnia, Dómine, semper bona creas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> sanctí \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, viví \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dícis et præstas nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Discooperit Calicem, genuflectit, accipit Hostiam inter pollicem et indicem manus dexteræ: et tenens sinistra Calicem, cum Hostia signat ter a labio ad labium Calicis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sum, et cum Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, et in Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, \u003cFONT SIZE='1' COLOR=\"red\">Cum ipsa Hostia signat bis inter se et Calicem, dicens:\u003c/FONT> est tibi Deo Patri \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipoténti, in unitáte Spíritus \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Sancti, \u003cFONT SIZE='1' COLOR=\"red\">Elevans parum Calicem cum Hostia, dicit:\u003c/FONT> omnis honor, et glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>ponit Hostiam, Calicem Palla cooperit, genuflectit, surgit, et dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or quem, Senhor, sempre criais estes bens e os \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> vivificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoais e no-los concedeis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Descobre o Cálice, e genuflecte: depois tomando a Hóstia na sua mão direita, e segurando o Cálice na esquerda, assinala com o Sinal da Cruz três vezes pelo Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Ele +, com Ele \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e n’Ele +, a Vós, ó Deus Pai todo-poderoso +, na unidade do Espírito \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Santo\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eleva um pouco o Cálice com a Hóstia.\u003c/I>\u003c/FONT>\u003cbr/>\npertence, e Vos é dada, toda a honra e glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ajoelha-se e levantando-se, diz \u003cFONT SIZE='1' COLOR=\"red\">ou canta\u003c/FONT>:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"Preparatio Communionis","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparatio Communionis\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>\u003cFONT SIZE='1' COLOR=\"red\">Iungit manus.\u003c/FONT>\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus: Præcéptis salutáribus móniti, et divína institutióne formáti audémus dícere:\u003cFONT SIZE='1' COLOR=\"red\">Extendit manus.\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ater noster, qui es in cælis. Sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cælo et in terra. Panem nostrum quotidiánum da nobis hódie. Et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sed líbera nos a malo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> \u003cFONT SIZE='1' COLOR=\"red\">Sacerdos secrete dicit :\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparação para Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos. Instruídos com os salutares preceitos do Salvador e dirigidos pelos seus divinos ensinamentos, ousamos dizer:\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ai nosso que estais nos céus;  \u003cbr/>\nsantificado seja o vosso nome;  \u003cbr/>\nvenha a nós o vosso reino;  \u003cbr/>\nseja feita a vossa vontade,  \u003cbr/>\nassim na terra como no céu.  \u003cbr/>\nO pão nosso de cada dia nos dai hoje;  \u003cbr/>\nperdoai-nos as nossas dívidas,  \u003cbr/>\nassim como nós perdoamos aos nossos devedores  \u003cbr/>\ne não nos deixeis cair em tentação:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Mas livrai-nos do mal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde manu dextera accipit inter indicem et medium digitos Patenam, quam tenens super Altare erectam, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>íbera nos, quǽsumus, Dómine, ab ómnibus malis, prætéritis, præséntibus et futúris: et intercedénte beáta et gloriósa semper Vírgine Dei Genetríce María, cum beátis Apóstolis tuis Petro et Paulo, atque Andréa, et ómnibus Sanctis, \u003cFONT SIZE='1' COLOR=\"red\">Signat se cum Patena a fronte ad pectus,\u003c/FONT> da propítius pacem in diébus nostris: \u003cFONT SIZE='1' COLOR=\"red\">Patenam osculatur,\u003c/FONT> ut, ope misericórdiæ tuæ adjúti, et a peccáto simus semper líberi et ab omni perturbatióne secúri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Submittit Patenam Hostiæ, discooperit Calicem, genuflectit, surgit, accipit Hostiam, et eam super Calicem tenens utraque manu, frangit per medium, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum, Fílium tuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et mediam partem, quam in dextera manu tenet, ponit super Patenam. Deinde ex parte, quæ in sinistra remanserat, frangit particulam, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\nQui tecum vivit et regnat in unitáte Spíritus Sancti Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Aliam mediam partem, quam in sinistra manu habet, adjungit mediæ super Patenam positæ, et particulam parvam dextera retinens super Calicem, quem sinistra per nodum infra cuppam tenet, dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cum ipsa particula signat ter super Calicem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ax Dómini sit semper vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte e segura com os dedos polegar e indicador da mão direita a Hóstia e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>ivrai-nos, Senhor, Vos suplicamos, de todos os males passados, presentes e futuros;  \u003cbr/>\ne, pela intercessão da bem-aventurada e gloriosa sempre Virgem Maria, Mãe de Deus,  \u003cbr/>\ne dos bem-aventurados Apóstolos Pedro e Paulo e André, e de todos os Santos,  \u003cbr/>\ndai-nos, benignamente, a paz nos nossos dias, a fim de que auxiliados pela vossa misericórdia,  \u003cbr/>\nsejamos sempre livres do pecado e seguros de toda a perturbação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte, que ergue até ao cimo do cálice.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Nosso Senhor Jesus Cristo, vosso Filho, que é Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote parte a Hóstia ao meio, de uma das partes tira um pequeno fragmento que deita no preciosíssimo Sangue, \u003c/I>\u003c/FONT> \u003cbr/>\ntraçando antes, com ele, sobre o Cálice, três vezes, o sinal da cruz, e dizendo:\u003cbr/>\nQue convosco vive e reina na unidade do Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, o Sacerdote, tendo entre os dedos da mão direita a Partícula, que fraccionou, coloca-a sobre o Cálice, que segura pelos nós, e acrescenta em voz alta:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote faz três vezes o sinal da Cruz com a Divina Partícula sobre o Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que a paz \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do Senhor esteja \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sempre \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Particulam ipsam immittit in Calicem, dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc commíxtio, et consecrátio Córporis et Sánguinis Dómini nostri Jesu Christi, fiat accipiéntibus nobis in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cooperit Calicem, genuflectit, surgit, et inclinatus Sacramento, junctis manibus, et ter pectus percutiens, intellegibili voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Coloca a partícula no Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta mistura e esta consagração do Corpo e do Sangue de Nosso Senhor Jesus Cristo  \u003cbr/>\nsejam penhor de vida eterna para nós que a receberemos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cobre o Cálice, genuflecte e levanta-se; depois inclinando-se e batendo três vezes no peito, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non dicitur miserére nobis, sed ejus loco dona eis requiem, et in tertio additur sempitérnam.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem sempitérnam.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote bate três vezes no peito, e diz a oração seguinte. Nas Missas de Defuntos, não se bate no peito e em vez de miserére nobis, diz-se: Dona eis requiem; na terceira parte: dona eis requiem sempiternam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso eterno.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus super Altare, inclinatus dicit secrete sequentes Orationes:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, recita as três orações seguintes, pela paz, santificação e graça da Igreja:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur pax, neque dicitur oratio Domine Jesu Christe, qui dixisti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas dos Defuntos, o beijo da paz não é dado.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ómine Jesu Christe, Fili Dei vivi, qui ex voluntáte Patris, cooperánte Spíritu Sancto, per mortem tuam mundum vivificásti: líbera me per hoc sacrosánctum Corpus et Sánguinem tuum ab ómnibus iniquitátibus meis, et univérsis malis: et fac me tuis semper inhærére mandátis, et a te numquam separári permíttas: Qui cum eódem Deo Patre et Spíritu Sancto vivis et regnas Deus in sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, Filho do Deus vivo, que, por vontade do Pai, cooperando o Espírito Santo,  \u003cbr/>\npela vossa morte destes a vida ao mundo: livrai-nos de todos os males por este vosso sacrossanto Corpo e Sangue.  \u003cbr/>\nPermiti que cumpra sempre os vossos preceitos e nunca me afaste de Vós,  \u003cbr/>\nque sendo Deus, viveis e reinais com o mesmo Deus Pai e Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ercéptio Córporis tui, Dómine Jesu Christe, quod ego indígnus súmere præsúmo, non mihi provéniat in judícium et condemnatiónem: sed pro tua pietáte prosit mihi ad tutaméntum mentis et córporis, et ad medélam percipiéndam: Qui vivis et regnas cum Deo Patre in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, que este vosso Corpo, que eu, ainda que indigno, vou receber,  \u003cbr/>\nnão seja para o meu juízo e condenação, mas que, pela vossa misericórdia, sirva à minha alma e ao meu corpo  \u003cbr/>\nde defesa e de remédio salutar:  \u003cbr/>\nVós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Genuflectit, surgit, et dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>anem cæléstem accípiam, et nomen Dómini invocábo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde parum inclinatus, accipit ambas partes Hostiæ inter pollicem et indicem sinistræ manus, et Patenam inter eundem indicem et medium supponit, et dextera tribus vicibus percutiens pectus, elata aliquantulum voce, ter dicit devote et humiliter:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote genuflecte e pegando depois na sagrada Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>omarei o Pão do céu e invocarei o nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Inclinado, toma as duas metades da Hóstia entre o polegar e o indicador da mão esquerda, e a patena entre o mesmo indicador e o dedo do meio; Em seguida bate três vezes no peito, dizendo devotamente e humilhado:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dextera se signans cum Hostia super Patenam, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et se inclinans, reverenter sumit ambas partes Hostiæ: quibus sumptis, deponit Patenam super Corporale, et erigens se jungit manus, et quiescit aliquantulum in meditatione Sanctissimi Sacramenti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Faz sobre si o sinal da cruz com a sagrada Hóstia, antes de a comungar.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Corpo de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recolhe-se por uns instantes.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde discooperit Calicem, genuflectit, colligit fragmenta, si quæ sint, extergit Patenam super Calicem, interim dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uid retríbuam Dómino pro ómnibus, quæ retríbuit mihi? Cálicem salutáris accípiam, et nomen Dómini invocábo. Laudans invocábo Dóminum, et ab inimícis meis salvus ero.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Accipit Calicem manu dextera, et eo se signans, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anguis Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et sinistra supponens Patenam Calici, reverenter sumit totum Sanguinem cum particula. Quo sumpto, si qui sunt communicandi, eos communicet, antequam se purificet\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>De seguida descobre o Cálice, genuflecte, recolhe quaisquer fragmentos que estiverem no corporal e purifica a patena sobre o Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo retribuirei ao Senhor os bens que Ele se dignou dispensar-me?  \u003cbr/>\nTomarei o Cálice da salvação e invocarei o nome do Senhor, louvando-O, e ficarei livre dos meus inimigos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Toma o preciosíssimo Sangue, fazendo antes sobre si o sinal da cruz\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Sangue de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recebe depois todo o Precioso Sangue, junto com a Partícula.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n","pt":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uod ore súmpsimus, Dómine, pura mente capiámus: et de múnere temporáli fiat nobis remédium sempitérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Interim porrigit Calicem ministro, qui infundit in eo parum vini, quo se purificat: deinde prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus tuum, Dómine, quod sumpsi, et Sanguis, quem potávi, adhǽreat viscéribus meis: et præsta; ut in me non remáneat scélerum mácula, quem pura et sancta refecérunt sacraménta: Qui vivis et regnas in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Abluit et extergit digitos, ac sumit ablutionem: extergit os et Calicem, quem, plicato Corporali, operit et collocat in Altari ut prius: deinde prosequitur Missam.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Entretanto, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue conservemos com pureza de coração, Senhor, o que a boca acaba de receber;  \u003cbr/>\ne que esta dádiva temporal se torne para nós remédio sempiterno.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O Sacerdote purifica primeiro o cálice e depois os dedos, e toma as abluções.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, que o vosso Corpo, que recebi, e o vosso sangue, que bebi, se unam intimamente às minhas entranhas;  \u003cbr/>\ndignai-Vos permitir, Senhor, que não fique em mim mancha alguma de pecado,  \u003cbr/>\nagora que estou confortado com sacramentos tão puros e santos: Vós, que viveis e reinais em todos os séculos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Purifica o cálice e deixa-o, coberto, no meio do altar. Nas Missas solenes, é o subdiácono quem purifica o cálice e o leva para a credência. O Sacerdote passa para o lado direito do altar, e recita a antífona da Comunhão.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"},{"label":"Postcommunio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicta antiphona ad Communionem, osculatur altare, et versus ad populum dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, reversus ad altare, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nAnimábus, quǽsumus, Dómine, famulórum famularúmque tuárum orátio profíciat supplicántium: ut eas et a peccátis ómnibus éxuas, et tuæ redemptiónis fácias esse partícipes:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote volta ao meio do altar, beija-o, e, voltando-se para os fiéis saúda-os:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue as nossas humildes preces sejam proveitosas às almas dos vossos servos e servas, a fim de que, soltas das cadeias dos seus pecados, participem dos frutos da vossa redenção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"},{"label":"Conclusio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicto, post ultimam Orationem,\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>dicit pro Missæ qualitate, vel Ite, Missa est, vel Benedicámus Dómino. Deo grátias.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Vira-se para as pessoas e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"itemissaest","la":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiéscant in pace.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que descansem em paz.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tunc celebrans inclinat se ante medium altaris, et manibus junctis super illud, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>láceat tibi, sancta Trínitas, obséquium servitútis meæ: et præsta; ut sacrifícium, quod óculis tuæ majestátis indígnus óbtuli, tibi sit acceptábile, mihíque et ómnibus, pro quibus illud óbtuli, sit, te miseránte, propitiábile. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>antíssima Trindade, seja-Vos agradável a homenagem da minha escravidão, a fim de que este sacrifício, que,  \u003cbr/>\nainda indignamente, ofereci à vossa divina majestade, seja aceite por Vós, e, pela vossa misericórdia,  \u003cbr/>\nse torne propiciatório para mim e para todos aqueles por quem o ofereci. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur benedíctio, sed dicto Requiéscant in pace, dicit: Pláceat tibi, sancta Trinitas; deinde osculato Altari, legit Evangelium sancti Joannis, nisi sequatur absolutio super tumulum seu catafalcum \u003cFONT SIZE='1' COLOR=\"red\">cf. Rubr. 510e\u003c/FONT>.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos a bênção é omitida.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde sacerdos in cornu Evangelii, junctis manibus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et signans signo crucis primum Altare vel librum, deinde se in fronte, ore et pectore, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Inítium \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann. 1, 1-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Junctis manibus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt.\u003cbr/>\nFuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine.\u003cbr/>\nErat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt. \u003cFONT SIZE='1' COLOR=\"red\">Genuflectit dicens:\u003c/FONT> Et Verbum caro factum est, \u003cFONT SIZE='1' COLOR=\"red\">Et surgens prosequitur:\u003c/FONT> et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finito Evangelio sancti Joannis, discedens ab Altari, pro gratiarum actione dicit Ant. Trium puerórum, cum reliquis, ut habetur in principio Missalis.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Indo depois para o lado do Evangelho, o padre diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Despois faz o sinal da Cruz na Sacra \u003cFONT SIZE='1' COLOR=\"red\">ou no Missal\u003c/FONT> e na sua testa, boca e peito, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rincípio \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Jo. 1, 1-14.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Com as mãos juntas, continua:\u003c/I>\u003c/FONT>\u003cbr/>\nNo princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.  Ele estava no princípio em Deus.  Todas as coisas foram feitas por Ele, e sem Ele nada se fez do que foi feito.  N’Ele estava a vida, e a vida era a luz dos homens.  E a luz resplandece nas trevas, e as trevas não a receberam.\u003cbr/>\nHouve um homem, enviado por Deus, cujo nome era João.  Ele veio como testemunha, para dar testemunho da Luz,  a fim de que todos cressem por meio dele.\u003cbr/>\nEle não era a Luz, mas veio para dar testemunho da Luz.\u003cbr/>\nEstava no mundo, e o mundo foi feito por Ele, e o mundo não O reconheceu.  Veio para o que era seu, e os seus não O receberam.  Mas a todos quantos O receberam, deu o poder de se tornarem filhos de Deus àqueles que crêem no seu nome;  os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas nasceram de Deus.  E o Verbo fez-se carne \u003cFONT SIZE='1' COLOR=\"red\">genuflecte-se\u003c/FONT> e habitou entre nós;  e nós vimos a sua glória, glória como a do Unigénito do Pai, cheio de graça e de verdade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Orationes Leonis XIII","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orationes Leonis XIII\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Salve Regína, Mater misericórdiæ, vita, dulcédo, et spes nostra, salve. Ad te clamámus, éxsules fílii Evæ. Ad te suspirámus geméntes et flentes in hac lacrymárum valle. Eia ergo, Advocáta nostra, illos tuos misericórdes óculos ad nos convérte. Et Jesum, benedíctum fructum ventris tui, nobis, post hoc exílium, osténde. O clemens, o pia, o dulcis Virgo Mária.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ora pro nobis, sancta Dei Génitrix.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Ut digni efficiámur promissiónibus Christi.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Orémus. Deus, refúgium nostrum et virtus, pópulum ad te clamántem propítius réspice; et intercedénte gloriósa, et immaculáta Vírgine Dei Genitríce María, cum beáto Joseph, ejus Sponso, ac beatis Apóstolis tuis Petro et Paulo, et ómnibus Sanctis, quas pro conversióne peccatórum, pro libertáte et exaltatióne sanctæ Matris Ecclésiæ, preces effúndimus, miséricors et benígnus exáudi. Per eúndem Christum Dóminum nostrum. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancte Míchaël Archángele, defénde nos in prǽlio; contra nequítiam et insídias diáboli esto præsídium. Imperet illi Deus, súpplices deprecámur: tuque, Princeps milítiæ Cæléstis, sátanam aliósque spíritus malígnos, qui ad perditiónem animárum pervagántur in mundo, divína virtúte in inférnum detrúde. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orações Leoninas\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Dizer de joelhos depois da celebração de Missa rezada:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Salve, Rainha, mãe de misericórdia, vida, doçura, esperança nossa, salve!  \u003cbr/>\nA Vós bradamos, os degredados filhos de Eva. A Vós suspiramos, gemendo e chorando neste vale de lágrimas.  \u003cbr/>\nEia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei.  \u003cbr/>\nE, depois deste desterro, nos mostrai Jesus, bendito fruto do vosso ventre.  \u003cbr/>\nÓ clemente, ó piedosa, ó doce Virgem Maria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Rogai por nós, Santa Mãe de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Para que sejamos dignos das promessas de Cristo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Oremos. Meu Deus, refúgio e fortaleza nossa, atendei propício aos clamores do vosso povo, e,  \u003cbr/>\npela intercessão da gloriosa e imaculada Virgem Maria, Mãe de Deus, do Bem-aventurado S. José, seu esposo,  \u003cbr/>\ndos bem-aventurados Apóstolos S. Pedro e S. Paulo e de todos os Santos,  \u003cbr/>\nouvi benigno e misericordioso as preces que fervorosamente Vos dirigimos  \u003cbr/>\npela conversão dos pecadores e pela exaltação da santa Madre Igreja.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> São Miguel Arcanjo, defendei-nos no combate, sede o nosso auxílio contra a maldade e as ciladas do demónio.  \u003cbr/>\nInstantemente vos pedimos que Deus sobre ele impere; e vós, Príncipe da Milícia Celeste, pelo poder divino,  \u003cbr/>\nprecipitai no inferno a Satanás e aos outros espíritos malignos que vagueiam pelo mundo para perdição das almas.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n"}]},{"number":2,"title":"In Commemoratione Omnium Fidelium Defunctorum I. classis ex Officium defunctorum [Commune/C9.txt]","winner":"Sancti/11-02m2.txt","rule":"ex C9\nno Gloria\nno Credo\nPrefatio=Defunctorum\nmultiple3\nSequentia\n\n","gloria":false,"credo":false,"omitPsalm":true,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, indulgentiárum Dómine: da animábus famulórum famularúmque tuárum refrigérii sedem, quiétis beatitúdinem et lúminis claritátem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, Senhor das misericórdias, concedei às almas dos vossos servos o lugar do refrigério, a bem-aventurança do repouso e o esplendor da luz.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Machabæórum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Mach 12:43-46\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Vir fortíssimus Judas, facta collatióne, duódecim mília drachmas argénti misit Jerosólymam, offérri pro peccátis mortuórum sacrifícium, bene et religióse de resurrectióne cógitans, nisi enim eos, qui cecíderant, resurrectúros speráret, supérfluum viderétur et vanum oráre pro mórtuis: et quia considerábat, quod hi, qui cum pietáte dormitiónem accéperant, óptimam habérent repósitam grátiam. Sancta ergo et salúbris est cogitátio pro defunctis exoráre, ut a peccátis solvántur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do livro dos Macabeus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Mac 12:43-46\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, um varão forte chamado Judas, havendo feito um peditório, recolheu a quantia de doze mil dracmas de prata, que enviou para Jerusalém, para ser oferecido um sacrifício pelos pecados dos mortos; pois ele possuía bons e religiosos pensamentos acerca da ressurreição \u003cFONT SIZE='1' COLOR=\"red\">e, com efeito, se ele não esperasse que aqueles que haviam sucumbido ressuscitassem um dia, teria pensado que era vão e supérfluo orar pelos mortos\u003c/FONT>. Assim, acreditava que abundante misericórdia estava reservada para aqueles que morressem piedosamente. Na verdade, é um santo e salutar pensamento orar pelos mortos, para que sejam livres dos seus pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 6:37-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Omne, quod dat mihi Pater, ad me véniet: et eum, qui venit ad me, non ejíciam foras: quia descéndi de cælo, non ut fáciam voluntátem meam, sed voluntátem ejus, qui misit me. Hæc est autem volúntas ejus, qui misit me, Patris: ut omne, quod dedit mihi, non perdam ex eo, sed resúscitem illud in novíssimo die. Hæc est autem volúntas Patris mei, qui misit me: ut omnis, qui videt Fílium et credit in eum, hábeat vitam ætérnam, et ego resuscitábo eum in novíssimo die.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 6:37-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus à multidão dos judeus: «Todo o que o Pai me dá, virá a mim; e o que vem a mim o não desprezarei; porquanto desci do céu, não para fazer a minha vontade, mas de quem me enviou. Ora, a vontade de meu Pai, que me enviou, é que não perca nenhum daqueles que me deu, mas que os ressuscite no último dia. Esta é a vontade de meu Pai, que me enviou: que todo aquele que vê o Filho e acredita n’Ele alcance a vida eterna; e Eu o ressuscitarei no último dia».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPropitiáre, Dómine, supplicatiónibus nostris, pro animábus famulórum famularúmque tuárum, pro quibus tibi offérimus sacrifícium laudis; ut eas Sanctórum tuórum consórtio sociáre dignéris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSede propício, Senhor, às nossas súplicas em favor das almas dos vossos servos; nós Vos oferecemos por elas este sacrifício de louvor, a fim de que Vos digneis admiti-las na companhia dos vossos santos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, Dómine: ut ánimæ famulórum famularúmque tuárum, his purgátæ sacrifíciis, indulgéntiam páriter et réquiem cápiant sempitérnam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, Vos rogamos, permiti que a alma dos vossos servos, havendo sido purificada pela virtude destes sacrifícios, receba ao mesmo tempo a indulgência e o sempiterno perdão.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[],"full":[{"label":"Incipit","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Incipit\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos paratus cum ingreditur ad Altare, facta illi debita reverentia, signat se signo crucis a fronte ad pectus, et clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n nómine Patris, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> et Fílii, et Spíritus Sancti. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Início\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>De pé, diante dos degraus do altar, o Sacerdote começa a Missa, fazendo o sinal da cruz e com uma voz clara e audível diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m nome do Pai, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e do Filho, e do Espírito Santo. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum, et in Missis de Tempore a Dominica Passionis usque ad Sabbatum sanctum exclusive, omittitur Psalmus Júdica me, Deus, cum Glória Patri, et repetitione Antiphonæ, sed dicto In nómine Patris, Introíbo, et Adjutórium, fit conféssio, ut sequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos e do Tempo da Paixão este salmo omite-se.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus ante pectus, incipit Antiphonam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Introíbo ad altáre Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Ad Deum, qui lætíficat juventútem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Juntando as mãos no peito, começa a antífona:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu irei até ao altar de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Até Deus, que é a alegria da minha juventude.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Signat se, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Adjutórium nostrum \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> in nómine Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Qui fecit cælum et terram.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde junctis manibus profunde inclinatus facit Confessionem.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onfíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et vobis, fratres: quia peccávi nimis cogitatióne, verbo et ópere: \u003cFONT SIZE='1' COLOR=\"red\">Percutit sibi pectus ter, dicens:\u003c/FONT> mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et vos, fratres, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Misereátur tui omnípotens Deus, et, dimíssis peccátis tuis, perdúcat te ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>et erigit se. Deinde Ministri repetunt Confessionem: et ubi a Sacerdote dicebatur vobis, fratres, et vos, fratres, a Ministris dicitur tibi, pater, et te, pater.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et ópere: mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea Sacerdos, junctis manibus, facit absolutionem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Signat se signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Indulgéntiam, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> absolutiónem et remissiónem peccatórum nostrórum tríbuat nobis omnípotens et miséricors Dóminus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote fazendo o sinal da cruz diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O nosso auxílio está \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> no nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que criou o céu e a terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz o Confíteor, humilhando-se publicamente:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, irmãos:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, irmãos, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Compadeça-se de ti o Senhor omnipotente; perdoe os teus pecados e te guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito diz o confiteor.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, Padre:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, Padre, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote, juntando as mãos, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Compadeça-se de vós o Senhor omnipotente; perdoe os vossos pecados e vos guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Fazendo o sinal da cruz, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que o Senhor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipotente e misericordioso nos conceda o perdão, a absolvição e a remissão dos nossos pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Et inclinatus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Deus, tu convérsus vivificábis nos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et plebs tua lætábitur in te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Osténde nobis, Dómine, misericórdiam tuam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et salutáre tuum da nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, exáudi oratiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et clamor meus ad te véniat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et extendens ac jungens manus, clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus, \u003cFONT SIZE='1' COLOR=\"red\">ei ascendens ad Altare, dicit secreto: \u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ufer a nobis, quǽsumus, Dómine, iniquitátes nostras: ut ad Sancta sanctórum puris mereámur méntibus introíre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus junctis super Altare, inclinatus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rámus te, Dómine, per mérita Sanctórum tuórum, \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare in medio\u003c/FONT> quorum relíquiæ hic sunt, et ómnium Sanctórum: ut indulgére dignéris ómnia peccáta mea. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, prossegue:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ó Deus, volvei-Vos para nós, e alcançaremos a vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E o vosso povo alegrar-se-á em Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Mostrai-nos, Senhor, a vossa misericórdia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E concedei-nos a vossa salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ouvi, Senhor, a minha oração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E que o meu clamor chegue até Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote sobe ao altar dizendo, entretanto:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>fastai de nós, Senhor, Vos imploramos, as nossas iniquidades,  \u003cbr/>\npara que mereçamos entrar no santuário com as almas purificadas.  \u003cbr/>\nPor Cristo, Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com as mãos juntas, inclinado sobre o altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os pedimos, Senhor, pelos méritos dos vossos Santos, cujas relíquias estão aqui \u003cFONT SIZE='1' COLOR=\"red\">beija o altar\u003c/FONT>,  \u003cbr/>\ne de todos os Santos, que Vos digneis perdoar os nossos pecados. Amém.\u003cbr/>\n"},{"label":"Introitus","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"},{"label":"Kyrie","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Qua finita, junctis manibus, et alternatim cum Ministris, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O celebrante, no meio do altar, diz, alternadamente com os assistentes:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n"},{"label":"Gloria","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Gloria\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Glória\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Oratio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare in medio, et versus ad populum dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Orationes, unam aut plures, ut ordo Officii postulat. Sequitur Epistola, Graduale, Tractus, vel Allelúja cum Versu, aut Sequentia, prout Tempus aut qualitas Missæ postulat.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, indulgentiárum Dómine: da animábus famulórum famularúmque tuárum refrigérii sedem, quiétis beatitúdinem et lúminis claritátem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote benze-se, beija o altar, volta-se para os fiéis e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Breve oração que resume e apresenta a Deus os votos de todos os fiéis, votos estes sugeridos pelo mistério ou solenidade do dia.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, Senhor das misericórdias, concedei às almas dos vossos servos o lugar do refrigério, a bem-aventurança do repouso e o esplendor da luz.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Lectio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Machabæórum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Mach 12:43-46\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Vir fortíssimus Judas, facta collatióne, duódecim mília drachmas argénti misit Jerosólymam, offérri pro peccátis mortuórum sacrifícium, bene et religióse de resurrectióne cógitans, nisi enim eos, qui cecíderant, resurrectúros speráret, supérfluum viderétur et vanum oráre pro mórtuis: et quia considerábat, quod hi, qui cum pietáte dormitiónem accéperant, óptimam habérent repósitam grátiam. Sancta ergo et salúbris est cogitátio pro defunctis exoráre, ut a peccátis solvántur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do livro dos Macabeus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Mac 12:43-46\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, um varão forte chamado Judas, havendo feito um peditório, recolheu a quantia de doze mil dracmas de prata, que enviou para Jerusalém, para ser oferecido um sacrifício pelos pecados dos mortos; pois ele possuía bons e religiosos pensamentos acerca da ressurreição \u003cFONT SIZE='1' COLOR=\"red\">e, com efeito, se ele não esperasse que aqueles que haviam sucumbido ressuscitassem um dia, teria pensado que era vão e supérfluo orar pelos mortos\u003c/FONT>. Assim, acreditava que abundante misericórdia estava reservada para aqueles que morressem piedosamente. Na verdade, é um santo e salutar pensamento orar pelos mortos, para que sejam livres dos seus pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Graduale","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"},{"label":"Evangelium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur Munda cor meum, sed non petitur benedictio, non deferuntur luminaria, nec Celebrans osculatur librum.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>unda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, conversus ad librum, junctis manibus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et pronuntians: Inítium, sive Sequéntia sancti Evangélii, signat librum, et se in fronte, ore et pectore, et legit Evangelium, ut dictum est. Quo finito, respondet Minister: Laus tibi, Christe.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 6:37-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Omne, quod dat mihi Pater, ad me véniet: et eum, qui venit ad me, non ejíciam foras: quia descéndi de cælo, non ut fáciam voluntátem meam, sed voluntátem ejus, qui misit me. Hæc est autem volúntas ejus, qui misit me, Patris: ut omne, quod dedit mihi, non perdam ex eo, sed resúscitem illud in novíssimo die. Hæc est autem volúntas Patris mei, qui misit me: ut omnis, qui videt Fílium et credit in eum, hábeat vitam ætérnam, et ego resuscitábo eum in novíssimo die.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos, o Munda cor é dito, mas a bênção não é pedida, e o padre não beija o Evangelho.\u003c/I>\u003c/FONT>\u003cbr/>\nÓ omnipotente Deus, assim como purificastes os lábios do Profeta Isaías com uma brasa de fogo,  \u003cbr/>\nassim também purificais agora o meu coração e os meus lábios.  \u003cbr/>\nDignai-Vos, pela vossa benigna misericórdia, purificar-me inteiramente,  \u003cbr/>\npara que possa anunciar dignamente o vosso Evangelho. Por Cristo Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Virando-se para o livro, com as mãos juntas diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 6:37-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus à multidão dos judeus: «Todo o que o Pai me dá, virá a mim; e o que vem a mim o não desprezarei; porquanto desci do céu, não para fazer a minha vontade, mas de quem me enviou. Ora, a vontade de meu Pai, que me enviou, é que não perca nenhum daqueles que me deu, mas que os ressuscite no último dia. Esta é a vontade de meu Pai, que me enviou: que todo aquele que vê o Filho e acredita n’Ele alcance a vida eterna; e Eu o ressuscitarei no último dia».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"},{"label":"Credo","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo&nbsp;\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Offertorium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare, et versus ad populum, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Offertorium.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O padre beija o altar, e virando-se para o povo diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois o padre entra no Sacrifício da Missa e exalta os fiéis para rezarem com ele.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Quo dicto, si est Missa sollemnis, Diaconus porrigit Celebranti Patenam cum Hostia: si privata, Sacerdos ipse accipit Patenam cum Hostia, quam offerens, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancte Pater, omnípotens ætérne Deus, hanc immaculátam hóstiam, quam ego indígnus fámulus tuus óffero tibi Deo meo vivo et vero, pro innumerabílibus peccátis, et offensiónibus, et neglegéntiis meis, et pro ómnibus circumstántibus, sed et pro ómnibus fidélibus christiánis vivis atque defúnctis: ut mihi, et illis profíciat ad salútem in vitam ætérnam. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Terminada esta leitura, o Sacerdote descobre o Cálice e toma nas mãos a patena com o pão, que vai ser consagrado. O Sacerdote oferece-os a Deus, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Pai santo, Deus omnipotente e eterno, esta hóstia imaculada, que eu, vosso indigno servo, Vos ofereço,  \u003cbr/>\nó meu Deus vivo e verdadeiro, pelos meus inumeráveis pecados, ofensas e negligências, por todos os assistentes  \u003cbr/>\ne por todos os cristãos vivos e mortos, a fim de que sirva de proveito para a minha salvação,  \u003cbr/>\npara a deles e para a vida eterna. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde faciens crucem cum eadem Patena, deponit Hostiam super Corporale. Diaconus ministrat vinum, Subdiaconus aquam in Calice: vel si privata est Missa, utrumque infundit Sacerdos, et aquam miscendam in Calice benedicit signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> qui humánæ substántiæ dignitátem mirabíliter condidísti, et mirabílius reformásti: da nobis per hujus aquæ et vini mystérium, ejus divinitátis esse consórtes, qui humanitátis nostræ fíeri dignátus est párticeps, Jesus Christus, Fílius tuus, Dóminus noster: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Ao lado direito do altar, o celebrante coloca vinho no cálice, ao qual mistura umas gotas de água, dizendo a seguinte oração:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> que maravilhosamente criastes a dignidade da natureza humana e que mais prodigiosamente ainda a reformastes,  \u003cbr/>\npermiti que pela mistura simbólica desta água e deste vinho sejamos participantes da divindade  \u003cbr/>\ndaquele que quis assumir a nossa humanidade, Jesus Cristo, vosso Filho, Nosso Senhor, que, sendo Deus,  \u003cbr/>\nvive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur prædicta Oratio: sed aqua non benedicitur.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Em Missas para Defuntos, a seguinte oração é dita, mas a água não é abençoada.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea accipit Calicem, et offert dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>fférimus tibi, Dómine, cálicem salutáris, tuam deprecántes cleméntiam: ut in conspéctu divínæ majestátis tuæ, pro nostra et totíus mundi salúte, cum odóre suavitátis ascéndat. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde facit signum crucis cum Calice, et illum ponit super Corporale, et Palla cooperit: tum, junctis manibus super Altare, aliquantulum inclinatus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n spíritu humilitátis et in ánimo contríto suscipiámur a te, Dómine: et sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi, Dómine Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Erectus expandit manus, easque in altum porrectas jungens, elevátis ad cælum oculis et statim demissis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eni, sanctificátor omnípotens ætérne Deus: \u003cFONT SIZE='1' COLOR=\"red\">Benedicit Oblata, prosequendo:\u003c/FONT> et béne \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dic hoc sacrifícium, tuo sancto nómini præparátum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>No meio do altar, o celebrante faz o oferecimento do cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>ós Vos oferecemos, Senhor, o Cálice da salvação; e Vos suplicamos que misericordiosamente o façais subir,  \u003cbr/>\ncomo suave perfume, diante da vossa divina majestade, para a nossa salvação e de todo o mundo. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, inclinando-se diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m humildade e contrição, sejamos recebidos por Vós, Senhor;  \u003cbr/>\ne assim este sacrifício, ó Deus, se torne agradável aos vossos olhos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Invocação do Espírito Santo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>inde, ó Santificador omnipotente, Deus eterno, e abençoai \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> este sacrifício, preparado para a glória do vosso Santo Nome.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Sacerdos lavat manus, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps. 25, 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avábo inter innocéntes manus meas: et circúmdabo altáre tuum, Dómine: Ut áudiam vocem laudis, et enárrem univérsa mirabília tua. Dómine, diléxi decórem domus tuæ et locum habitatiónis glóriæ tuæ. Ne perdas cum ímpiis, Deus, ánimam meam, et cum viris sánguinum vitam meam: In quorum mánibus iniquitátes sunt: déxtera eórum repléta est munéribus. Ego autem in innocéntia mea ingréssus sum: rédime me et miserére mei. Pes meus stetit in dirécto: in ecclésiis benedícam te, Dómine.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O lavar das mãos simboliza a pureza da alma, necessária para oferecer o santo Sacrifício. O Sacerdote vai à direita do altar e lava as mãos, dizendo, entretanto, os seguintes versículos do salmo 25:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Psalm 25. 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avarei as minhas mãos, como os inocentes, e rodearei, Senhor o vosso altar:  \u003cbr/>\nPara ouvir a voz dos vossos louvores e publicar todas as vossas maravilhas.  \u003cbr/>\nAmei, Senhor, o decoro da vossa casa e o lugar onde reside a vossa glória.  \u003cbr/>\nNão deixeis, ó meu Deus, que a minha alma se perca com os ímpios, nem a minha vida com os homens sanguinários,  \u003cbr/>\nque têm as mãos manchadas de iniquidades e a mão direita cheia de dádivas.  \u003cbr/>\nPois que tenho vivido na inocência, salvai-me e tende misericórdia de mim.  \u003cbr/>\nOs meus pés continuam firmes no caminho direito: e hei-de bendizer-Vos, Senhor, em todas as assembleias.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, aliquantulum inclinatus in medio Altaris, junctis manibus super eo, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancta Trínitas, hanc oblatiónem, quam tibi offérimus ob memóriam passiónis, resurrectiónis, et ascensiónis Jesu Christi, Dómini nostri: et in honórem beátæ Maríæ semper Vírginis, et beáti Joannis Baptistæ, et sanctórum Apostolórum Petri et Pauli, et istórum et ómnium Sanctórum: ut illis profíciat ad honórem, nobis autem ad salútem: et illi pro nobis intercédere dignéntur in cælis, quorum memóriam ágimus in terris. Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, ao meio do altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Santíssima Trindade, esta oblação, que Vos oferecemos em memória da Paixão, da Ressurreição  \u003cbr/>\ne da Ascensão de Nosso Senhor Jesus Cristo: e em honra da bem-aventurada sempre Virgem Maria, do bem-aventurado João Baptista  \u003cbr/>\ne dos Santos Apóstolos Pedro e Paulo, e destes, que estão aqui, e de todos os Santos: para que esta oblação  \u003cbr/>\nlhes sirva de glória e a nós de salvação: e aqueles, cuja memória honramos na terra, se dignem interceder por nós no céu.  \u003cbr/>\nPelo mesmo Jesus Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea osculatur Altare, et versus ad populum extendens, et jungens manus, voce paululum elevata, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Oráte, fratres: ut meum ac vestrum sacrifícium acceptábile fiat apud Deum Patrem omnipoténtem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Minister, seu circumstantes respondent: alioquin ipsemet Sacerdos:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Suscípiat Dóminus sacrifícium de mánibus tuis \u003cFONT SIZE='1' COLOR=\"red\">vel meis\u003c/FONT> ad laudem et glóriam nominis sui, ad utilitátem quoque nostram, totiúsque Ecclésiæ suæ sanctæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos submissa voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus extensis, absolute sine Orémus subjungit Orationes secretas.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPropitiáre, Dómine, supplicatiónibus nostris, pro animábus famulórum famularúmque tuárum, pro quibus tibi offérimus sacrifícium laudis; ut eas Sanctórum tuórum consórtio sociáre dignéris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Beija o Altar e voltando-se para os fiéis, o Sacerdote convida-os a orar com ele:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Orai, meus irmãos, a fim de que o meu sacrifício, que é também vosso, seja recebido por Deus Pai omnipotente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que o Senhor receba pelas tuas mãos este sacrifício para a honra e glória do seu Nome,  \u003cbr/>\ne também para a nossa utilidade e de toda sua santa Igreja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde, em voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Em seguida lê a Secreta. À Secreta principal, podem, em certas Missas, juntar-se outras, em número igual \u003c/I>\u003c/FONT> \u003cbr/>\ne segundo as mesmas regras da Colecta.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSede propício, Senhor, às nossas súplicas em favor das almas dos vossos servos; nós Vos oferecemos por elas este sacrifício de louvor, a fim de que Vos digneis admiti-las na companhia dos vossos santos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Præfatio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Præfatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus finitis, cum pervenerit ad conclusionem, clara voce dicit: Per ómnia sǽcula sæculórum, cum Præfatione, ut in sequentibus. Præfationem incipit ambabus manibus positis hinc inde super Altare: quas aliquantulum elevat, cum dicit: Sursum corda. Jungit eas ante pectus, et caput inclinat, cum dicit: Grátias agamus Dómino, Deo nostro. Deinde disjungit manus, et disjunctas tenet usque ad finem Præfationis: qua finita, iterum jungit eas, et inclinatus dicit: Sanctus. Et cum dicit: Benedíctus, qui venit, signum crucis sibi producit a fronte ad pectus.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sursum corda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Habémus ad Dóminum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Grátias agámus Dómino, Deo nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Dignum et justum est.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctus, Sanctus, Sanctus Dóminus, Deus Sábaoth. Pleni sunt cæli et terra glória tua. Hosánna in excélsis. Benedíctus, qui venit in nómine Dómini. Hosánna in excélsis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com o Prefácio, começa a grande, a solene oração sacerdotal da Igreja e a oblação propriamente dita do Sacrifício. Curto diálogo introdutório entre o Sacerdote e os fiéis desperta nas almas os sentimentos de acção de graças que convêm à celebração dos santos mistérios.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Corações ao alto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim os temos para o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Demos graças ao Senhor, Nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim é digno e justo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anto, Santo, Santo, Senhor Deus do Universo. O céu e a terra proclamam a vossa glória. Hossana nas alturas.  \u003cbr/>\nBendito o que vem em nome do Senhor. Hosana nas alturas.\u003cbr/>\n"},{"label":"Canon","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Canon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finita præfatione, sacerdos extendens, elevans aliquantulum et iungens manus, elevansque ad cælum oculos, et statim demittens, profunde inclinatus ante Altare, manibus super eo positis, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>e ígitur, clementíssime Pater, per Jesum Christum, Fílium tuum, Dóminum nostrum, súpplices rogámus, ac pétimus, \u003cFONT SIZE='1' COLOR=\"red\">osculatur Altare et, junctis manibus ante pectus, dicit:\u003c/FONT> uti accépta hábeas et benedícas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam et Calicem simul, dicens:\u003c/FONT> hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dona, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> múnera, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sancta sacrifícia illibáta, \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT> in primis, quæ tibi offérimus pro Ecclésia tua sancta cathólica: quam pacificáre, custodíre, adunáre et régere dignéris toto orbe terrárum: una cum fámulo tuo Papa nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et Antístite nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et ómnibus orthodóxis, atque cathólicæ et apostólicæ fídei cultóribus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Cânon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós, pois, rogamos e pedimos, ó clementíssimo Pai, por Jesus Cristo, vosso Filho e Nosso Senhor,  \u003cbr/>\nque estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dons, estas \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ofertas, estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sacrifícios santos e imaculados Vos sejam agradáveis e os abençoeis,  \u003cbr/>\nos quais, antes de tudo, Vos oferecemos pela nossa santa Igreja Católica: dignai-Vos conceder-lhe a paz, guardá-la,  \u003cbr/>\nuni-la e governá-la por toda a terra, em comunhão com vosso servo, o nosso Papa \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, com o nosso Bispo \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  \u003cbr/>\ne com todos os \u003cFONT SIZE='1' COLOR=\"red\">bispos\u003c/FONT> ortodoxos e os que professam a fé católica e apostólica.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro vivis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto, Dómine, famulórum famularúmque tuarum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquantulum pro quibus orare intendit: deinde manibus extensis prosequitur:\u003c/FONT> et ómnium circumstántium, quorum tibi fides cógnita est et nota devótio, pro quibus tibi offérimus: vel qui tibi ófferunt hoc sacrifícium laudis, pro se suísque ómnibus: pro redemptióne animárum suárum, pro spe salútis et incolumitátis suæ: tibíque reddunt vota sua ætérno Deo, vivo et vero.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Memento dos vivos\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, dos vossos servos \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e de todos os que aqui estão presentes, cuja fé Vos é conhecida  \u003cbr/>\ne a piedade é notória: pelos quais Vos oferecemos, ou eles Vos oferecem, este sacrifício de louvor por si próprios  \u003cbr/>\ne por todos os seus, pela redenção das suas almas, pela esperança da sua salvação: é a Vós que oferecem as homenagens,  \u003cbr/>\ncomo Deus eterno, vivo e verdadeiro, que sois.\u003cbr/>\n"},{"label":"communicantes","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n \u003cbr/>\net beatórum Apostolórum ac Mártyrum tuórum, Petri et Pauli, Andréæ, Jacóbi, Joánnis, Thomæ, Jacóbi, Philíppi, Bartholomǽi, Matthǽi, Simónis et Thaddǽi: Lini, Cleti, Cleméntis, Xysti, Cornélii, Cypriáni, Lauréntii, Chrysógoni, Joánnis et Pauli, Cosmæ et Damiáni: et ómnium Sanctórum tuórum; quorum méritis precibúsque concédas, ut in ómnibus protectiónis tuæ muniámur auxílio. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n \u003cbr/>\ne depois também a dos vossos bem-aventurados Apóstolos e Mártires: Pedro e Paulo, André, Tiago, João, Tomé, Tiago,  \u003cbr/>\nFilipe, Bartolomeu, Mateus, Simão e Tadeu: Lino, Cleto, Clemente, Xisto, Cornélio, Cipriano, Lourenço, Crisógono,  \u003cbr/>\nJoão e Paulo, Cosme e Damião: e de todos vossos Santos.  \u003cbr/>\nDignai-Vos permitir que pelos seus méritos e preces gozemos do poderoso auxílio da vossa protecção.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tenens manus expansas super Oblata, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>anc ígitur oblatiónem servitútis nostræ, sed et cunctæ famíliæ tuæ,\u003cbr/>\n\u003cbr/>\nquǽsumus, Dómine, ut placátus accípias: diésque nostros in tua pace dispónas, atque ab ætérna damnatióne nos éripi, et in electórum tuórum júbeas grege numerári. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Estendendo as mãos sobre as oblatas, o celebrante diz::\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, Vos rogamos que Vos digneis receber favoravelmente esta oferta que eu,  \u003cbr/>\nvosso indigno servo, e toda a vossa família Vos fazemos;\u003cbr/>\n\u003cbr/>\nconcedei-nos o gozo da vossa paz nos nossos dias, livrai-nos da condenação eterna  \u003cbr/>\ne admiti-nos ao número dos vossos escolhidos. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uam oblatiónem tu, Deus, in ómnibus, quǽsumus, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Oblata,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díctam, adscríp \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, ra \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, rationábilem, acceptabilémque fácere dignéris: \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam,\u003c/FONT> ut nobis Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem,\u003c/FONT> et San \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guis fiat dilectíssimi Fílii tui, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus,\u003c/FONT> Dómini nostri Jesu Christi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta oblação, ó Deus, Vos imploramos, seja abençoada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> aprovada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> confirmada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> digna e aceitável,  \u003cbr/>\na fim de que se converta para nós no Corpo e no Sangue do vosso amado Filho, Nosso Senhor Jesus Cristo.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui prídie quam paterétur, \u003cFONT SIZE='1' COLOR=\"red\">Accipit Hostiam,\u003c/FONT> accépit panem in sanctas ac venerábiles manus suas, \u003cFONT SIZE='1' COLOR=\"red\">Elevat oculos ad cælum,\u003c/FONT> et elevátis óculis in cælum ad te Deum, Patrem suum omnipoténtem, \u003cFONT SIZE='1' COLOR=\"red\">Caput inclinat,\u003c/FONT> tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Signat super Hostiam,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, fregit, dedítque discípulis suis, dicens: Accípite, et manducáte ex hoc omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> qual, na véspera da sua paixão tomou o pão nas suas santas e veneráveis mãos: e, erguendo os olhos ao céu,  \u003cbr/>\na Vós, Deus seu Pai omnipotente, e dando-Vos graças, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoou-o, partiu-o e deu-o aos seus discípulos, dizendo:  \u003cbr/>\nTomai todos e comei:\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tenens ambabus manibus Hostiam inter indices et pollices, profert verba consecrationis secrete, distincte et attente super Hostiam, et simul super omnes, si plures sint consecrandæ.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHOC EST ENIM CORPUS MEUM.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, statim Hostiam consecratam genuflexus adorat: surgit, ostendit populo, reponit super Corporale, et genuflexus iterum adorat: nec amplius pollices et indices disjungit, nisi quando Hostia tractanda est, usque ad ablutionem digitorum.\u003c/I>\u003c/FONT>\u003cbr/>\nwait5\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras de Consagração do Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O MEU CORPO.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois de pronunciar as palavras de consagração, o padre, ajoelhado, adora a Sagrada Hóstia; levanta-se, elevando-a. -- Olha-a com fé, piedade e amor, dizendo: \"Meu Senhor e meu Deus.\" -- e colocando-a de volta no corporal, novamente a adora. Depois, nunca mais separa os dedos e polegar, excepto quando toma a Hóstia, até à lavagem dos dedos.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tunc, detecto Calice, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ímili modo postquam cenátum est, \u003cFONT SIZE='1' COLOR=\"red\">Ambabus manibus accipit Calicem,\u003c/FONT> accípiens et hunc præclárum Cálicem in sanctas ac venerábiles manus suas: \u003cFONT SIZE='1' COLOR=\"red\">item Caput inclinat,\u003c/FONT> item tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Sinistra tenens Calicem, dextera signat super eum,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, dedítque discípulis suis, dicens: Accípite, et bíbite ex eo omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Consagração e Elevação do Cálice:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>o mesmo modo, Jesus, após a Ceia, tomou nas suas santas e veneráveis mãos este precioso Cálice,  \u003cbr/>\ne, novamente, dando-Vos graças, abençoou-o \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e deu-o aos seus discípulos dizendo: Tomai e bebei dele todos,\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profert verba consecrationis super Calicem, attente, continuate, et secrete, tenens illum parum elevatum.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHIC EST ENIM CALIX SANGUINIS MEI, NOVI ET ÆTERNI TESTAMENTI: MYSTERIUM FIDEI: QUI PRO VOBIS ET PRO MULTIS EFFUNDETUR IN REMISSIONEM PECCATORUM.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, deponit Calicem super Corporale, et dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc quotiescúmque fecéritis, in mei memóriam faciétis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Genuflexus adorat: surgit, ostendit populo, deponit, cooperit, et genuflexus iterum adorat.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras da Consagração do Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O CÁLICE DO MEU SANGUE DO NOVO E ETERNO TESTAMENTO, MISTÉRIO DA FÉ, QUE SERÁ DERRAMADO POR VÓS E POR MUITOS, PARA REMISSÃO DOS PECADOS.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois da consagração do Cálice, o Sacerdote diz com uma voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as vezes que fizerdes isto, fazei-o em memória de mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O padre ajoelha-se e adora o Precioso Sangue; levanta-se, elevando o Cálice, e quando o baixa e o cobre, novamente o adora.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Deinde disjunctis manibus dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nde et mémores, Dómine, nos servi tui, sed et plebs tua sancta, ejúsdem Christi Fílii tui, Dómini nostri, tam beátæ passiónis, nec non et ab ínferis resurrectiónis, sed et in cælos gloriósæ ascensiónis: offérimus præcláræ majestáti tuæ de tuis donis ac datis, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> puram, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctam, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> immaculátam, \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam, dicens:\u003c/FONT> Panem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctum vitæ ætérnæ, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem, dicens:\u003c/FONT> et Cálicem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> salútis perpétuæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">O Sacerdote continua depois as orações do Cânon:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, nós, vossos servos, e o vosso povo santo,  \u003cbr/>\nlembrando-nos da bem-aventurada Paixão do mesmo Cristo, vosso Filho e Senhor nosso,  \u003cbr/>\nassim como também da sua Ressurreição dos mortos e da sua gloriosa Ascensão aos céus,  \u003cbr/>\noferecemos à vossa divina majestade os mesmos dons que nos foram dados:  \u003cbr/>\na Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pura, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santa, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> imaculada, o Pão \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santo da vida eterna e o Cálice \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> da salvação perpétua.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>upra quæ propítio ac seréno vultu respícere dignéris: et accépta habére, sicúti accépta habére dignátus es múnera púeri tui justi Abel, et sacrifícium Patriárchæ nostri Abrahæ: et quod tibi óbtulit summus sacérdos tuus Melchísedech, sanctum sacrifícium, immaculátam hóstiam.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Com as mãos afastadas, contínua:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>obre estas ofertas dignai-Vos lançar um olhar propício e benévolo e aceitá-las,  \u003cbr/>\ncomo Vos dignastes receber os dons do justo Abel, vosso servo, o sacrifício do nosso Patriarca Abraão  \u003cbr/>\ne o que Vos ofereceu o Sumo sacerdote Melquisedeque, pois este é um sacrifício santo, uma hóstia imaculada.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profunde inclinatus, junctis manibus et super Altare positis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úpplices te rogámus, omnípotens Deus: jube hæc perférri per manus sancti Angeli tui in sublíme altáre tuum, in conspéctu divínæ majestátis tuæ: ut, quotquot \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare,\u003c/FONT> ex hac altáris participatióne sacrosánctum Fílii tui \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat semel super Hostiam, et semel super Calicem,\u003c/FONT> Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, et Sán \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guinem sumpsérimus, \u003cFONT SIZE='1' COLOR=\"red\">Seipsum signat, dicens:\u003c/FONT> omni benedictióne cælésti et grátia repleámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>umildemente Vos rogamos, ó Deus omnipotente, ordeneis que estas ofertas sejam apresentadas  \u003cbr/>\nno altar sublime pelas mãos do vosso Santo Anjo, na presença da vossa divina majestade,  \u003cbr/>\na fim de que todos aqueles que participam deste Altar pela recepção do Santíssimo Corpo \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e Sangue \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do vosso Filho  \u003cbr/>\nsejam repletos de todas as bênçãos do céu e de todas as graças. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro defunctis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto étiam, Dómine, famulórum famularúmque tuárum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, qui nos præcessérunt cum signo fídei, et dórmiunt in somno pacis.wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquántulum pro iis defunctis, pro quibus orare intendit, deinde extensis manibus prosequitur:\u003c/FONT> Ipsis, Dómine, et ómnibus in Christo quiescéntibus locum refrigérii, lucis, et pacis, ut indúlgeas, deprecámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et caput inclinat, dicens:\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Memento dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-Vos também Senhor, dos vossos servos e servas \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, que partiram antes de nós,  \u003cbr/>\nmarcados com o sinal da fé, e agora dormem o sono da paz.wait10  \u003cbr/>\n\u003cFONT SIZE='1' COLOR=\"red\">Junta as mãos e ora por estes defuntos, depois, estendendo as mãos, continua:\u003c/FONT>  \u003cbr/>\nNós Vos suplicamos, Senhor, dignai-Vos conceder a estes, assim como a todos os que descansam em Cristo,  \u003cbr/>\num lugar de consolação, de luz e de paz. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Manu dextera percutit sibi pectus, elata aliquantulum voce dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>obis quoque peccatóribus \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus ut prius, secrete prosequitur:\u003c/FONT> fámulis tuis, de multitúdine miseratiónum tuárum sperántibus, partem áliquam et societátem donáre dignéris, cum tuis sanctis Apóstolis et Martýribus: cum Joánne, Stéphano, Matthía, Bárnaba, Ignátio, Alexándro, Marcellíno, Petro, Felicitáte, Perpétua, Agatha, Lúcia, Agnéte, Cæcília, Anastásia, et ómnibus Sanctis tuis: intra quorum nos consórtium, non æstimátor mériti, sed véniæ, quǽsumus, largítor admítte. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per Christum, Dóminum nostrum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>o Sacerdote bate no peito, dizendo.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT> também a nós, pecadores, vossos servos, que esperamos na grandeza das vossas misericórdias,  \u003cbr/>\ndignai-Vos conceder-nos alguma parte na vossa herança e sociedade com vossos Santos Apóstolos e Mártires:  \u003cbr/>\nJoão, Estêvão, Matias, Barnabé, Inácio, Alexandre, Marcelino, Pedro, Felicidade, Perpétua, Águeda, Luzia, Inês,  \u003cbr/>\nCecília, Anastácia e com todos os Santos, em cuja companhia, Vos pedimos, nos recebais,  \u003cbr/>\nnão em consideração dos nossos merecimentos, mas segundo a liberalidade da vossa misericórdia. Por Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er quem hæc ómnia, Dómine, semper bona creas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> sanctí \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, viví \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dícis et præstas nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Discooperit Calicem, genuflectit, accipit Hostiam inter pollicem et indicem manus dexteræ: et tenens sinistra Calicem, cum Hostia signat ter a labio ad labium Calicis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sum, et cum Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, et in Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, \u003cFONT SIZE='1' COLOR=\"red\">Cum ipsa Hostia signat bis inter se et Calicem, dicens:\u003c/FONT> est tibi Deo Patri \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipoténti, in unitáte Spíritus \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Sancti, \u003cFONT SIZE='1' COLOR=\"red\">Elevans parum Calicem cum Hostia, dicit:\u003c/FONT> omnis honor, et glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>ponit Hostiam, Calicem Palla cooperit, genuflectit, surgit, et dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or quem, Senhor, sempre criais estes bens e os \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> vivificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoais e no-los concedeis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Descobre o Cálice, e genuflecte: depois tomando a Hóstia na sua mão direita, e segurando o Cálice na esquerda, assinala com o Sinal da Cruz três vezes pelo Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Ele +, com Ele \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e n’Ele +, a Vós, ó Deus Pai todo-poderoso +, na unidade do Espírito \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Santo\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eleva um pouco o Cálice com a Hóstia.\u003c/I>\u003c/FONT>\u003cbr/>\npertence, e Vos é dada, toda a honra e glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ajoelha-se e levantando-se, diz \u003cFONT SIZE='1' COLOR=\"red\">ou canta\u003c/FONT>:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"Preparatio Communionis","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparatio Communionis\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>\u003cFONT SIZE='1' COLOR=\"red\">Iungit manus.\u003c/FONT>\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus: Præcéptis salutáribus móniti, et divína institutióne formáti audémus dícere:\u003cFONT SIZE='1' COLOR=\"red\">Extendit manus.\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ater noster, qui es in cælis. Sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cælo et in terra. Panem nostrum quotidiánum da nobis hódie. Et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sed líbera nos a malo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> \u003cFONT SIZE='1' COLOR=\"red\">Sacerdos secrete dicit :\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparação para Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos. Instruídos com os salutares preceitos do Salvador e dirigidos pelos seus divinos ensinamentos, ousamos dizer:\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ai nosso que estais nos céus;  \u003cbr/>\nsantificado seja o vosso nome;  \u003cbr/>\nvenha a nós o vosso reino;  \u003cbr/>\nseja feita a vossa vontade,  \u003cbr/>\nassim na terra como no céu.  \u003cbr/>\nO pão nosso de cada dia nos dai hoje;  \u003cbr/>\nperdoai-nos as nossas dívidas,  \u003cbr/>\nassim como nós perdoamos aos nossos devedores  \u003cbr/>\ne não nos deixeis cair em tentação:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Mas livrai-nos do mal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde manu dextera accipit inter indicem et medium digitos Patenam, quam tenens super Altare erectam, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>íbera nos, quǽsumus, Dómine, ab ómnibus malis, prætéritis, præséntibus et futúris: et intercedénte beáta et gloriósa semper Vírgine Dei Genetríce María, cum beátis Apóstolis tuis Petro et Paulo, atque Andréa, et ómnibus Sanctis, \u003cFONT SIZE='1' COLOR=\"red\">Signat se cum Patena a fronte ad pectus,\u003c/FONT> da propítius pacem in diébus nostris: \u003cFONT SIZE='1' COLOR=\"red\">Patenam osculatur,\u003c/FONT> ut, ope misericórdiæ tuæ adjúti, et a peccáto simus semper líberi et ab omni perturbatióne secúri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Submittit Patenam Hostiæ, discooperit Calicem, genuflectit, surgit, accipit Hostiam, et eam super Calicem tenens utraque manu, frangit per medium, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum, Fílium tuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et mediam partem, quam in dextera manu tenet, ponit super Patenam. Deinde ex parte, quæ in sinistra remanserat, frangit particulam, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\nQui tecum vivit et regnat in unitáte Spíritus Sancti Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Aliam mediam partem, quam in sinistra manu habet, adjungit mediæ super Patenam positæ, et particulam parvam dextera retinens super Calicem, quem sinistra per nodum infra cuppam tenet, dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cum ipsa particula signat ter super Calicem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ax Dómini sit semper vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte e segura com os dedos polegar e indicador da mão direita a Hóstia e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>ivrai-nos, Senhor, Vos suplicamos, de todos os males passados, presentes e futuros;  \u003cbr/>\ne, pela intercessão da bem-aventurada e gloriosa sempre Virgem Maria, Mãe de Deus,  \u003cbr/>\ne dos bem-aventurados Apóstolos Pedro e Paulo e André, e de todos os Santos,  \u003cbr/>\ndai-nos, benignamente, a paz nos nossos dias, a fim de que auxiliados pela vossa misericórdia,  \u003cbr/>\nsejamos sempre livres do pecado e seguros de toda a perturbação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte, que ergue até ao cimo do cálice.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Nosso Senhor Jesus Cristo, vosso Filho, que é Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote parte a Hóstia ao meio, de uma das partes tira um pequeno fragmento que deita no preciosíssimo Sangue, \u003c/I>\u003c/FONT> \u003cbr/>\ntraçando antes, com ele, sobre o Cálice, três vezes, o sinal da cruz, e dizendo:\u003cbr/>\nQue convosco vive e reina na unidade do Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, o Sacerdote, tendo entre os dedos da mão direita a Partícula, que fraccionou, coloca-a sobre o Cálice, que segura pelos nós, e acrescenta em voz alta:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote faz três vezes o sinal da Cruz com a Divina Partícula sobre o Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que a paz \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do Senhor esteja \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sempre \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Particulam ipsam immittit in Calicem, dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc commíxtio, et consecrátio Córporis et Sánguinis Dómini nostri Jesu Christi, fiat accipiéntibus nobis in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cooperit Calicem, genuflectit, surgit, et inclinatus Sacramento, junctis manibus, et ter pectus percutiens, intellegibili voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Coloca a partícula no Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta mistura e esta consagração do Corpo e do Sangue de Nosso Senhor Jesus Cristo  \u003cbr/>\nsejam penhor de vida eterna para nós que a receberemos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cobre o Cálice, genuflecte e levanta-se; depois inclinando-se e batendo três vezes no peito, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non dicitur miserére nobis, sed ejus loco dona eis requiem, et in tertio additur sempitérnam.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem sempitérnam.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote bate três vezes no peito, e diz a oração seguinte. Nas Missas de Defuntos, não se bate no peito e em vez de miserére nobis, diz-se: Dona eis requiem; na terceira parte: dona eis requiem sempiternam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso eterno.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus super Altare, inclinatus dicit secrete sequentes Orationes:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, recita as três orações seguintes, pela paz, santificação e graça da Igreja:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur pax, neque dicitur oratio Domine Jesu Christe, qui dixisti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas dos Defuntos, o beijo da paz não é dado.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ómine Jesu Christe, Fili Dei vivi, qui ex voluntáte Patris, cooperánte Spíritu Sancto, per mortem tuam mundum vivificásti: líbera me per hoc sacrosánctum Corpus et Sánguinem tuum ab ómnibus iniquitátibus meis, et univérsis malis: et fac me tuis semper inhærére mandátis, et a te numquam separári permíttas: Qui cum eódem Deo Patre et Spíritu Sancto vivis et regnas Deus in sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, Filho do Deus vivo, que, por vontade do Pai, cooperando o Espírito Santo,  \u003cbr/>\npela vossa morte destes a vida ao mundo: livrai-nos de todos os males por este vosso sacrossanto Corpo e Sangue.  \u003cbr/>\nPermiti que cumpra sempre os vossos preceitos e nunca me afaste de Vós,  \u003cbr/>\nque sendo Deus, viveis e reinais com o mesmo Deus Pai e Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ercéptio Córporis tui, Dómine Jesu Christe, quod ego indígnus súmere præsúmo, non mihi provéniat in judícium et condemnatiónem: sed pro tua pietáte prosit mihi ad tutaméntum mentis et córporis, et ad medélam percipiéndam: Qui vivis et regnas cum Deo Patre in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, que este vosso Corpo, que eu, ainda que indigno, vou receber,  \u003cbr/>\nnão seja para o meu juízo e condenação, mas que, pela vossa misericórdia, sirva à minha alma e ao meu corpo  \u003cbr/>\nde defesa e de remédio salutar:  \u003cbr/>\nVós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Genuflectit, surgit, et dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>anem cæléstem accípiam, et nomen Dómini invocábo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde parum inclinatus, accipit ambas partes Hostiæ inter pollicem et indicem sinistræ manus, et Patenam inter eundem indicem et medium supponit, et dextera tribus vicibus percutiens pectus, elata aliquantulum voce, ter dicit devote et humiliter:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote genuflecte e pegando depois na sagrada Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>omarei o Pão do céu e invocarei o nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Inclinado, toma as duas metades da Hóstia entre o polegar e o indicador da mão esquerda, e a patena entre o mesmo indicador e o dedo do meio; Em seguida bate três vezes no peito, dizendo devotamente e humilhado:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dextera se signans cum Hostia super Patenam, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et se inclinans, reverenter sumit ambas partes Hostiæ: quibus sumptis, deponit Patenam super Corporale, et erigens se jungit manus, et quiescit aliquantulum in meditatione Sanctissimi Sacramenti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Faz sobre si o sinal da cruz com a sagrada Hóstia, antes de a comungar.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Corpo de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recolhe-se por uns instantes.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde discooperit Calicem, genuflectit, colligit fragmenta, si quæ sint, extergit Patenam super Calicem, interim dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uid retríbuam Dómino pro ómnibus, quæ retríbuit mihi? Cálicem salutáris accípiam, et nomen Dómini invocábo. Laudans invocábo Dóminum, et ab inimícis meis salvus ero.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Accipit Calicem manu dextera, et eo se signans, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anguis Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et sinistra supponens Patenam Calici, reverenter sumit totum Sanguinem cum particula. Quo sumpto, si qui sunt communicandi, eos communicet, antequam se purificet\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>De seguida descobre o Cálice, genuflecte, recolhe quaisquer fragmentos que estiverem no corporal e purifica a patena sobre o Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo retribuirei ao Senhor os bens que Ele se dignou dispensar-me?  \u003cbr/>\nTomarei o Cálice da salvação e invocarei o nome do Senhor, louvando-O, e ficarei livre dos meus inimigos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Toma o preciosíssimo Sangue, fazendo antes sobre si o sinal da cruz\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Sangue de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recebe depois todo o Precioso Sangue, junto com a Partícula.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n","pt":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uod ore súmpsimus, Dómine, pura mente capiámus: et de múnere temporáli fiat nobis remédium sempitérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Interim porrigit Calicem ministro, qui infundit in eo parum vini, quo se purificat: deinde prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus tuum, Dómine, quod sumpsi, et Sanguis, quem potávi, adhǽreat viscéribus meis: et præsta; ut in me non remáneat scélerum mácula, quem pura et sancta refecérunt sacraménta: Qui vivis et regnas in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Abluit et extergit digitos, ac sumit ablutionem: extergit os et Calicem, quem, plicato Corporali, operit et collocat in Altari ut prius: deinde prosequitur Missam.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Entretanto, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue conservemos com pureza de coração, Senhor, o que a boca acaba de receber;  \u003cbr/>\ne que esta dádiva temporal se torne para nós remédio sempiterno.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O Sacerdote purifica primeiro o cálice e depois os dedos, e toma as abluções.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, que o vosso Corpo, que recebi, e o vosso sangue, que bebi, se unam intimamente às minhas entranhas;  \u003cbr/>\ndignai-Vos permitir, Senhor, que não fique em mim mancha alguma de pecado,  \u003cbr/>\nagora que estou confortado com sacramentos tão puros e santos: Vós, que viveis e reinais em todos os séculos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Purifica o cálice e deixa-o, coberto, no meio do altar. Nas Missas solenes, é o subdiácono quem purifica o cálice e o leva para a credência. O Sacerdote passa para o lado direito do altar, e recita a antífona da Comunhão.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"},{"label":"Postcommunio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicta antiphona ad Communionem, osculatur altare, et versus ad populum dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, reversus ad altare, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, Dómine: ut ánimæ famulórum famularúmque tuárum, his purgátæ sacrifíciis, indulgéntiam páriter et réquiem cápiant sempitérnam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote volta ao meio do altar, beija-o, e, voltando-se para os fiéis saúda-os:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, Vos rogamos, permiti que a alma dos vossos servos, havendo sido purificada pela virtude destes sacrifícios, receba ao mesmo tempo a indulgência e o sempiterno perdão.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Conclusio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicto, post ultimam Orationem,\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>dicit pro Missæ qualitate, vel Ite, Missa est, vel Benedicámus Dómino. Deo grátias.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Vira-se para as pessoas e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"itemissaest","la":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiéscant in pace.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que descansem em paz.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tunc celebrans inclinat se ante medium altaris, et manibus junctis super illud, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>láceat tibi, sancta Trínitas, obséquium servitútis meæ: et præsta; ut sacrifícium, quod óculis tuæ majestátis indígnus óbtuli, tibi sit acceptábile, mihíque et ómnibus, pro quibus illud óbtuli, sit, te miseránte, propitiábile. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>antíssima Trindade, seja-Vos agradável a homenagem da minha escravidão, a fim de que este sacrifício, que,  \u003cbr/>\nainda indignamente, ofereci à vossa divina majestade, seja aceite por Vós, e, pela vossa misericórdia,  \u003cbr/>\nse torne propiciatório para mim e para todos aqueles por quem o ofereci. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur benedíctio, sed dicto Requiéscant in pace, dicit: Pláceat tibi, sancta Trinitas; deinde osculato Altari, legit Evangelium sancti Joannis, nisi sequatur absolutio super tumulum seu catafalcum \u003cFONT SIZE='1' COLOR=\"red\">cf. Rubr. 510e\u003c/FONT>.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos a bênção é omitida.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde sacerdos in cornu Evangelii, junctis manibus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et signans signo crucis primum Altare vel librum, deinde se in fronte, ore et pectore, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Inítium \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann. 1, 1-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Junctis manibus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt.\u003cbr/>\nFuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine.\u003cbr/>\nErat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt. \u003cFONT SIZE='1' COLOR=\"red\">Genuflectit dicens:\u003c/FONT> Et Verbum caro factum est, \u003cFONT SIZE='1' COLOR=\"red\">Et surgens prosequitur:\u003c/FONT> et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finito Evangelio sancti Joannis, discedens ab Altari, pro gratiarum actione dicit Ant. Trium puerórum, cum reliquis, ut habetur in principio Missalis.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Indo depois para o lado do Evangelho, o padre diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Despois faz o sinal da Cruz na Sacra \u003cFONT SIZE='1' COLOR=\"red\">ou no Missal\u003c/FONT> e na sua testa, boca e peito, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rincípio \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Jo. 1, 1-14.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Com as mãos juntas, continua:\u003c/I>\u003c/FONT>\u003cbr/>\nNo princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.  Ele estava no princípio em Deus.  Todas as coisas foram feitas por Ele, e sem Ele nada se fez do que foi feito.  N’Ele estava a vida, e a vida era a luz dos homens.  E a luz resplandece nas trevas, e as trevas não a receberam.\u003cbr/>\nHouve um homem, enviado por Deus, cujo nome era João.  Ele veio como testemunha, para dar testemunho da Luz,  a fim de que todos cressem por meio dele.\u003cbr/>\nEle não era a Luz, mas veio para dar testemunho da Luz.\u003cbr/>\nEstava no mundo, e o mundo foi feito por Ele, e o mundo não O reconheceu.  Veio para o que era seu, e os seus não O receberam.  Mas a todos quantos O receberam, deu o poder de se tornarem filhos de Deus àqueles que crêem no seu nome;  os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas nasceram de Deus.  E o Verbo fez-se carne \u003cFONT SIZE='1' COLOR=\"red\">genuflecte-se\u003c/FONT> e habitou entre nós;  e nós vimos a sua glória, glória como a do Unigénito do Pai, cheio de graça e de verdade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Orationes Leonis XIII","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orationes Leonis XIII\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Salve Regína, Mater misericórdiæ, vita, dulcédo, et spes nostra, salve. Ad te clamámus, éxsules fílii Evæ. Ad te suspirámus geméntes et flentes in hac lacrymárum valle. Eia ergo, Advocáta nostra, illos tuos misericórdes óculos ad nos convérte. Et Jesum, benedíctum fructum ventris tui, nobis, post hoc exílium, osténde. O clemens, o pia, o dulcis Virgo Mária.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ora pro nobis, sancta Dei Génitrix.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Ut digni efficiámur promissiónibus Christi.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Orémus. Deus, refúgium nostrum et virtus, pópulum ad te clamántem propítius réspice; et intercedénte gloriósa, et immaculáta Vírgine Dei Genitríce María, cum beáto Joseph, ejus Sponso, ac beatis Apóstolis tuis Petro et Paulo, et ómnibus Sanctis, quas pro conversióne peccatórum, pro libertáte et exaltatióne sanctæ Matris Ecclésiæ, preces effúndimus, miséricors et benígnus exáudi. Per eúndem Christum Dóminum nostrum. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancte Míchaël Archángele, defénde nos in prǽlio; contra nequítiam et insídias diáboli esto præsídium. Imperet illi Deus, súpplices deprecámur: tuque, Princeps milítiæ Cæléstis, sátanam aliósque spíritus malígnos, qui ad perditiónem animárum pervagántur in mundo, divína virtúte in inférnum detrúde. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orações Leoninas\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Dizer de joelhos depois da celebração de Missa rezada:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Salve, Rainha, mãe de misericórdia, vida, doçura, esperança nossa, salve!  \u003cbr/>\nA Vós bradamos, os degredados filhos de Eva. A Vós suspiramos, gemendo e chorando neste vale de lágrimas.  \u003cbr/>\nEia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei.  \u003cbr/>\nE, depois deste desterro, nos mostrai Jesus, bendito fruto do vosso ventre.  \u003cbr/>\nÓ clemente, ó piedosa, ó doce Virgem Maria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Rogai por nós, Santa Mãe de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Para que sejamos dignos das promessas de Cristo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Oremos. Meu Deus, refúgio e fortaleza nossa, atendei propício aos clamores do vosso povo, e,  \u003cbr/>\npela intercessão da gloriosa e imaculada Virgem Maria, Mãe de Deus, do Bem-aventurado S. José, seu esposo,  \u003cbr/>\ndos bem-aventurados Apóstolos S. Pedro e S. Paulo e de todos os Santos,  \u003cbr/>\nouvi benigno e misericordioso as preces que fervorosamente Vos dirigimos  \u003cbr/>\npela conversão dos pecadores e pela exaltação da santa Madre Igreja.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> São Miguel Arcanjo, defendei-nos no combate, sede o nosso auxílio contra a maldade e as ciladas do demónio.  \u003cbr/>\nInstantemente vos pedimos que Deus sobre ele impere; e vós, Príncipe da Milícia Celeste, pelo poder divino,  \u003cbr/>\nprecipitai no inferno a Satanás e aos outros espíritos malignos que vagueiam pelo mundo para perdição das almas.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n"}]},{"number":3,"title":"In Commemoratione Omnium Fidelium Defunctorum I. classis ex Officium defunctorum [Commune/C9.txt]","winner":"Sancti/11-02m3.txt","rule":"ex C9\nno Gloria\nno Credo\nPrefatio=Defunctorum\nmultiple3\nSequentia\n\n","gloria":false,"credo":false,"omitPsalm":true,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, véniæ largítor et humánæ salútis amátor: quǽsumus cleméntiam tuam; ut nostræ congregatiónis fratres, propínquos et benefactóres, qui ex hoc sǽculo transiérunt, beáta María semper Vírgine intercedénte cum ómnibus Sanctis tuis, ad perpétuæ beatitúdinis consórtium perveníre concédas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que perdoais aos pecadores e desejais a salvação dos homens, imploramos a vossa clemência, por intercessão da bem-aventurada Maria, sempre Virgem, e de todos os Santos, em favor dos nossos irmãos, parentes e benfeitores, que saíram deste mundo, a fim de que alcancem a bem-aventurança eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Apocalýpsis beáti Joánnis Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Audívi vocem de cœlo, dicéntem mihi: Scribe: Beáti mórtui, qui in Dómino moriúntur. Amodo jam dicit Spíritus, ut requiéscant a labóribus suis: ópera enim illórum sequúntur illos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro do Apocalipse do B. Ap.º João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, ouvi uma voz do céu que me dizia: «Escreve: Bem-aventurados os mortos, que morrem no Senhor; porquanto, diz o Espírito, eles vão logo descansar no Senhor, visto que suas obras os acompanham».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 6:51-55\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Ego sum panis vivus, qui de cœlo descéndi. Si quis manducáverit ex hoc pane, vivet in ætérnum: et panis, quem ego dabo, caro mea est pro mundi vita. Litigábant ergo Judæi ad ínvicem, dicéntes: Quómodo potest hic nobis carnem suam dare ad manducándum? Dixit ergo eis Jesus: Amen, amen, dico vobis: nisi manducavéritis carnem Fílii hóminis et bibéritis ejus sánguinem, non habébitis vitam in vobis. Qui mánducat meam carnem et bibit meum sánguinem, habet vitam ætérnam: et ego resuscitábo eum in novíssimo die.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 6:51-55\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas dos judeus: «Eu sou o pão vivo, que desci do céu. Se alguém comer deste pão, viverá eternamente; pois o pão que dou é a minha carne para a vida do mundo». Porém os judeus discutiam uns com os outros, dizendo: «Como pode Ele dar-nos a comer a sua carne?». Jesus respondeu-lhes: «Em verdade, em verdade vos digo: se não comerdes a carne do Filho do homem e não beberdes o seu sangue, não tereis a vida em vós. Aquele que come a minha carne e bebe o meu sangue tem a vida eterna, e Eu o ressuscitarei no último dia».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDeus, cujus misericórdiæ non est númerus, súscipe propítius preces humilitátis nostræ: et animábus fratrum, propinquórum et benefactórum nostrórum, quibus tui nóminis dedísti confessiónem, per hæc sacraménta salútis nostræ, cunctórum remissiónem tríbue peccatórum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus, cuja misericórdia é infinita, ouvi benigno as nossas humildes preces, e concedei, pela virtude deste sacramento da nossa salvação, o perdão dos seus pecados às almas dos nossos irmãos, parentes e benfeitores, aos quais permitistes a graça de confessarem o vosso nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens et miséricors Deus: ut ánimæ fratrum, propinquórum et benefactórum nostrórum, pro quibus hoc sacrifícium laudis tuæ obtúlimus majestáti; per hujus virtútem sacraménti a peccátis ómnibus expiátæ, lucis perpétuæ, te miseránte, recípiant beatitúdinem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, Vos pedimos, concedei às almas dos nossos irmãos, parentes e benfeitores, pelos quais oferecemos à vossa majestade este sacrifício de louvor, a graça de alcançarem da vossa misericórdia, pela virtude deste sacramento, a expiação dos pecados e a felicidade da luz eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[],"full":[{"label":"Incipit","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Incipit\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos paratus cum ingreditur ad Altare, facta illi debita reverentia, signat se signo crucis a fronte ad pectus, et clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n nómine Patris, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> et Fílii, et Spíritus Sancti. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Início\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>De pé, diante dos degraus do altar, o Sacerdote começa a Missa, fazendo o sinal da cruz e com uma voz clara e audível diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m nome do Pai, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e do Filho, e do Espírito Santo. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum, et in Missis de Tempore a Dominica Passionis usque ad Sabbatum sanctum exclusive, omittitur Psalmus Júdica me, Deus, cum Glória Patri, et repetitione Antiphonæ, sed dicto In nómine Patris, Introíbo, et Adjutórium, fit conféssio, ut sequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos e do Tempo da Paixão este salmo omite-se.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus ante pectus, incipit Antiphonam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Introíbo ad altáre Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Ad Deum, qui lætíficat juventútem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Juntando as mãos no peito, começa a antífona:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu irei até ao altar de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Até Deus, que é a alegria da minha juventude.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit. psalm\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Signat se, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Adjutórium nostrum \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> in nómine Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Qui fecit cælum et terram.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde junctis manibus profunde inclinatus facit Confessionem.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onfíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et vobis, fratres: quia peccávi nimis cogitatióne, verbo et ópere: \u003cFONT SIZE='1' COLOR=\"red\">Percutit sibi pectus ter, dicens:\u003c/FONT> mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et vos, fratres, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Misereátur tui omnípotens Deus, et, dimíssis peccátis tuis, perdúcat te ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>et erigit se. Deinde Ministri repetunt Confessionem: et ubi a Sacerdote dicebatur vobis, fratres, et vos, fratres, a Ministris dicitur tibi, pater, et te, pater.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et ópere: mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, oráre pro me ad Dóminum, Deum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea Sacerdos, junctis manibus, facit absolutionem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Signat se signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Indulgéntiam, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> absolutiónem et remissiónem peccatórum nostrórum tríbuat nobis omnípotens et miséricors Dóminus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote fazendo o sinal da cruz diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O nosso auxílio está \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> no nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que criou o céu e a terra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz o Confíteor, humilhando-se publicamente:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, irmãos:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, irmãos, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Compadeça-se de ti o Senhor omnipotente; perdoe os teus pecados e te guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito diz o confiteor.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Eu me confesso a Deus, todo-poderoso, à bem-aventurada sempre Virgem Maria,  \u003cbr/>\nao bem-aventurado S. Miguel Arcanjo, ao bem-aventurado S. João Baptista,  \u003cbr/>\naos Santos Apóstolos S. Pedro e S. Paulo, a todos os santos, e a vós, Padre:  \u003cbr/>\nque pequei muitas vezes por pensamentos, palavras e obras: \u003cFONT SIZE='1' COLOR=\"red\">aqui baterá no peito três vezes, dizendo:\u003c/FONT>\u003cbr/>\nPor minha culpa, por minha culpa, por minha tão grande culpa.\u003cbr/>\nPortanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado S. Miguel Arcanjo,  \u003cbr/>\nao bem-aventurado S. João Baptista, aos Santos Apóstolos S. Pedro e S. Paulo,  \u003cbr/>\na todos os Santos e a vós, Padre, que rogueis por mim a Deus, Nosso Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote, juntando as mãos, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Compadeça-se de vós o Senhor omnipotente; perdoe os vossos pecados e vos guie até à vida eterna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Fazendo o sinal da cruz, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que o Senhor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipotente e misericordioso nos conceda o perdão, a absolvição e a remissão dos nossos pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Et inclinatus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Deus, tu convérsus vivificábis nos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et plebs tua lætábitur in te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Osténde nobis, Dómine, misericórdiam tuam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et salutáre tuum da nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, exáudi oratiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et clamor meus ad te véniat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et extendens ac jungens manus, clara voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus, \u003cFONT SIZE='1' COLOR=\"red\">ei ascendens ad Altare, dicit secreto: \u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ufer a nobis, quǽsumus, Dómine, iniquitátes nostras: ut ad Sancta sanctórum puris mereámur méntibus introíre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus junctis super Altare, inclinatus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rámus te, Dómine, per mérita Sanctórum tuórum, \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare in medio\u003c/FONT> quorum relíquiæ hic sunt, et ómnium Sanctórum: ut indulgére dignéris ómnia peccáta mea. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, prossegue:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ó Deus, volvei-Vos para nós, e alcançaremos a vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E o vosso povo alegrar-se-á em Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Mostrai-nos, Senhor, a vossa misericórdia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E concedei-nos a vossa salvação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ouvi, Senhor, a minha oração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E que o meu clamor chegue até Vós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote sobe ao altar dizendo, entretanto:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>fastai de nós, Senhor, Vos imploramos, as nossas iniquidades,  \u003cbr/>\npara que mereçamos entrar no santuário com as almas purificadas.  \u003cbr/>\nPor Cristo, Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com as mãos juntas, inclinado sobre o altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os pedimos, Senhor, pelos méritos dos vossos Santos, cujas relíquias estão aqui \u003cFONT SIZE='1' COLOR=\"red\">beija o altar\u003c/FONT>,  \u003cbr/>\ne de todos os Santos, que Vos digneis perdoar os nossos pecados. Amém.\u003cbr/>\n"},{"label":"Introitus","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nTe decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>équiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezd 2:34; 2:35\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 64:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n"},{"label":"Kyrie","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Qua finita, junctis manibus, et alternatim cum Ministris, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Christe, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Kýrie, eléison.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Kyrie\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O celebrante, no meio do altar, diz, alternadamente com os assistentes:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cristo, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Senhor, tende piedade de nós.\u003cbr/>\n"},{"label":"Gloria","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Gloria\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Glória\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Oratio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare in medio, et versus ad populum dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Orationes, unam aut plures, ut ordo Officii postulat. Sequitur Epistola, Graduale, Tractus, vel Allelúja cum Versu, aut Sequentia, prout Tempus aut qualitas Missæ postulat.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, véniæ largítor et humánæ salútis amátor: quǽsumus cleméntiam tuam; ut nostræ congregatiónis fratres, propínquos et benefactóres, qui ex hoc sǽculo transiérunt, beáta María semper Vírgine intercedénte cum ómnibus Sanctis tuis, ad perpétuæ beatitúdinis consórtium perveníre concédas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote benze-se, beija o altar, volta-se para os fiéis e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Breve oração que resume e apresenta a Deus os votos de todos os fiéis, votos estes sugeridos pelo mistério ou solenidade do dia.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que perdoais aos pecadores e desejais a salvação dos homens, imploramos a vossa clemência, por intercessão da bem-aventurada Maria, sempre Virgem, e de todos os Santos, em favor dos nossos irmãos, parentes e benfeitores, que saíram deste mundo, a fim de que alcancem a bem-aventurança eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Lectio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Apocalýpsis beáti Joánnis Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Audívi vocem de cœlo, dicéntem mihi: Scribe: Beáti mórtui, qui in Dómino moriúntur. Amodo jam dicit Spíritus, ut requiéscant a labóribus suis: ópera enim illórum sequúntur illos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro do Apocalipse do B. Ap.º João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 14:13\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, ouvi uma voz do céu que me dizia: «Escreve: Bem-aventurados os mortos, que morrem no Senhor; porquanto, diz o Espírito, eles vão logo descansar no Senhor, visto que suas obras os acompanham».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Graduale","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nRéquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:7.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In memória ætérna erit justus: ab auditióne mala non timébit.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nAbsólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Et lucis ætérnæ beatitúdine pérfrui.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDies iræ, dies illa\u003cbr/>\nSolvet sæclum in favílla:\u003cbr/>\nTeste David cum Sibýlla.\u003cbr/>\n_\u003cbr/>\nQuantus tremor est futúrus,\u003cbr/>\nQuando judex est ventúrus,\u003cbr/>\nCuncta stricte discussúrus!\u003cbr/>\n_\u003cbr/>\nTuba mirum spargens sonum\u003cbr/>\nPer sepúlcra regiónum,\u003cbr/>\nCoget omnes ante thronum.\u003cbr/>\n_\u003cbr/>\nMors stupébit et natúra,\u003cbr/>\nCum resúrget creatúra,\u003cbr/>\nJudicánti responsúra.\u003cbr/>\n_\u003cbr/>\nLiber scriptus proferétur,\u003cbr/>\nIn quo totum continétur,\u003cbr/>\nUnde mundus judicétur.\u003cbr/>\n_\u003cbr/>\nJudex ergo cum sedébit,\u003cbr/>\nQuidquid latet, apparébit:\u003cbr/>\nNil inúltum remanébit.\u003cbr/>\n_\u003cbr/>\nQuid sum miser tunc dictúrus?\u003cbr/>\nQuem patrónum rogatúrus,\u003cbr/>\nCum vix justus sit secúrus?\u003cbr/>\n_\u003cbr/>\nRex treméndæ majestátis,\u003cbr/>\nQui salvándos salvas gratis,\u003cbr/>\nSalva me, fons pietátis.\u003cbr/>\n_\u003cbr/>\nRecordáre, Jesu pie,\u003cbr/>\nQuod sum causa tuæ viæ:\u003cbr/>\nNe me perdas illa die.\u003cbr/>\n_\u003cbr/>\nQuærens me, sedísti lassus:\u003cbr/>\nRedemísti Crucem passus:\u003cbr/>\nTantus labor non sit cassus.\u003cbr/>\n_\u003cbr/>\nJuste judex ultiónis,\u003cbr/>\nDonum fac remissiónis\u003cbr/>\nAnte diem ratiónis.\u003cbr/>\n_\u003cbr/>\nIngemísco, tamquam reus:\u003cbr/>\nCulpa rubet vultus meus:\u003cbr/>\nSupplicánti parce, Deus.\u003cbr/>\n_\u003cbr/>\nQui Maríam absolvísti,\u003cbr/>\nEt latrónem exaudísti,\u003cbr/>\nMihi quoque spem dedísti.\u003cbr/>\n_\u003cbr/>\nPreces meæ non sunt dignæ:\u003cbr/>\nSed tu bonus fac benígne,\u003cbr/>\nNe perénni cremer igne.\u003cbr/>\n_\u003cbr/>\nInter oves locum præsta,\u003cbr/>\nEt ab hœdis me sequéstra,\u003cbr/>\nStátuens in parte dextra.\u003cbr/>\n_\u003cbr/>\nConfutátis maledíctis,\u003cbr/>\nFlammis ácribus addíctis:\u003cbr/>\nVoca me cum benedíctis.\u003cbr/>\n_\u003cbr/>\nOro supplex et acclínis,\u003cbr/>\nCor contrítum quasi cinis:\u003cbr/>\nGere curam mei finis.\u003cbr/>\n_\u003cbr/>\nLacrimósa dies illa,\u003cbr/>\nQua resúrget ex favílla\u003cbr/>\nJudicándus homo reus.\u003cbr/>\n_\u003cbr/>\nHuic ergo parce, Deus:\u003cbr/>\nPie Jesu Dómine,\u003cbr/>\nDona eis réquiem.\u003cbr/>\nAmen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:34-35\u003c/I>\u003c/FONT>\u003cbr/>\nDai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tractus\u003c/I>\u003c/FONT>\u003cbr/>\nLivrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E que com o socorro da vossa graça consigam evitar o juízo da vingança:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> E gozem a bem-aventurança da luz eterna.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Sequentia\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nDia da ira aquele dia\u003cbr/>\nem que o universo será reduzido a cinzas,\u003cbr/>\nsegundo as profecias de David e Sibila.\u003cbr/>\n_\u003cbr/>\nQual não será o terror dos homens\u003cbr/>\nquando o soberano Juiz vier examinar\u003cbr/>\ntodas as acções com rigor!\u003cbr/>\n_\u003cbr/>\nO som estridente da trombeta acordará os mortos,\u003cbr/>\nnas profundezas das sepulturas,\u003cbr/>\nreunindo-os todos diante do trono do Senhor.\u003cbr/>\n_\u003cbr/>\nA morte e a natureza ficarão estupefactas\u003cbr/>\nquando a criatura comparecer\u003cbr/>\npara ser julgada pelo Juiz.\u003cbr/>\n_\u003cbr/>\nUm livro aparecerá,\u003cbr/>\nonde está escrito tudo sobre o que há-de consistir\u003cbr/>\no julgamento do mundo.\u003cbr/>\n_\u003cbr/>\nQuando o Juiz se assentar no tribunal,\u003cbr/>\ntudo o que estiver oculto ficará descoberto,\u003cbr/>\ne nenhum crime ficará impune.\u003cbr/>\n_\u003cbr/>\nInfeliz de mim! Que poderei dizer então?\u003cbr/>\nQue protector procurarei,\u003cbr/>\nquando somente o justo está tranquilo?!\u003cbr/>\n_\u003cbr/>\nÓ Rei, cuja majestade é tremenda,\u003cbr/>\nmas que salvais, gratuitamente, os escolhidos,\u003cbr/>\nsalvai-me, ó fonte de piedade!\u003cbr/>\n_\u003cbr/>\nRecordai-Vos, ó piíssimo Jesus,\u003cbr/>\nde que vieste ao mundo por minha causa:\u003cbr/>\nnão me condeneis nesse dia.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que Vos fatigastes em minha procura\u003cbr/>\ne que para me resgatardes morrestes na Cruz:\u003cbr/>\nnão queirais que fiquem infrutíferos tantos esforços.\u003cbr/>\n_\u003cbr/>\nÓ justo Juiz, que castigais com justiça,\u003cbr/>\nconcedei-me o perdão das minhas faltas\u003cbr/>\nantes do dia do julgamento.\u003cbr/>\n_\u003cbr/>\nEu choro, como réu;\u003cbr/>\nas minhas culpas envergonham-me.\u003cbr/>\nÓ Deus, que minhas súplicas me alcancem perdão.\u003cbr/>\n_\u003cbr/>\nÓ Vós, que absolvestes Maria\u003cbr/>\ne ouvistes o ladrão,\u003cbr/>\ne me concedestes também a esperança!\u003cbr/>\n_\u003cbr/>\nBem sei que minhas preces não são dignas;\u003cbr/>\nmas Vós, que sois bom,\u003cbr/>\nnão consintais que eu arda no fogo eterno.\u003cbr/>\n_\u003cbr/>\nColocai-me entre os cordeiros,\u003cbr/>\nà vossa direita,\u003cbr/>\ne separai-me dos pecadores.\u003cbr/>\n_\u003cbr/>\nLivrai-me da confusão\u003cbr/>\ne do suplicio dos malditos condenados\u003cbr/>\ne introduzi-me junto dos benditos de vosso Pai.\u003cbr/>\n_\u003cbr/>\nProstrado ante Vós, suplicante,\u003cbr/>\ncom o coração esmagado, como reduzido a cinzas,\u003cbr/>\nVos imploro, ó da morte.\u003cbr/>\n_\u003cbr/>\nDia de lágrimas aquele em\u003cbr/>\nque o homem renasça da sua cinza\u003cbr/>\npara ser julgado!\u003cbr/>\n_\u003cbr/>\nTende, pois, piedade dele, ó meu Deus!\u003cbr/>\nÓ piíssimo Jesus, ó Senhor,\u003cbr/>\nconcedei-lhe o repouso eterno.\u003cbr/>\nAmen.\u003cbr/>\n"},{"label":"Evangelium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur Munda cor meum, sed non petitur benedictio, non deferuntur luminaria, nec Celebrans osculatur librum.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>unda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, conversus ad librum, junctis manibus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et pronuntians: Inítium, sive Sequéntia sancti Evangélii, signat librum, et se in fronte, ore et pectore, et legit Evangelium, ut dictum est. Quo finito, respondet Minister: Laus tibi, Christe.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 6:51-55\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis Judæórum: Ego sum panis vivus, qui de cœlo descéndi. Si quis manducáverit ex hoc pane, vivet in ætérnum: et panis, quem ego dabo, caro mea est pro mundi vita. Litigábant ergo Judæi ad ínvicem, dicéntes: Quómodo potest hic nobis carnem suam dare ad manducándum? Dixit ergo eis Jesus: Amen, amen, dico vobis: nisi manducavéritis carnem Fílii hóminis et bibéritis ejus sánguinem, non habébitis vitam in vobis. Qui mánducat meam carnem et bibit meum sánguinem, habet vitam ætérnam: et ego resuscitábo eum in novíssimo die.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos, o Munda cor é dito, mas a bênção não é pedida, e o padre não beija o Evangelho.\u003c/I>\u003c/FONT>\u003cbr/>\nÓ omnipotente Deus, assim como purificastes os lábios do Profeta Isaías com uma brasa de fogo,  \u003cbr/>\nassim também purificais agora o meu coração e os meus lábios.  \u003cbr/>\nDignai-Vos, pela vossa benigna misericórdia, purificar-me inteiramente,  \u003cbr/>\npara que possa anunciar dignamente o vosso Evangelho. Por Cristo Nosso Senhor. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Virando-se para o livro, com as mãos juntas diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 6:51-55\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas dos judeus: «Eu sou o pão vivo, que desci do céu. Se alguém comer deste pão, viverá eternamente; pois o pão que dou é a minha carne para a vida do mundo». Porém os judeus discutiam uns com os outros, dizendo: «Como pode Ele dar-nos a comer a sua carne?». Jesus respondeu-lhes: «Em verdade, em verdade vos digo: se não comerdes a carne do Filho do homem e não beberdes o seu sangue, não tereis a vida em vós. Aquele que come a minha carne e bebe o meu sangue tem a vida eterna, e Eu o ressuscitarei no último dia».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"},{"label":"Credo","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Credo&nbsp;\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>omit.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Offertorium","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde osculatur Altare, et versus ad populum, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Postea dicit: Orémus, et Offertorium.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.\u003cbr/>\n* Quam olim Abrahæ promisísti et sémini ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O padre beija o altar, e virando-se para o povo diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois o padre entra no Sacrifício da Missa e exalta os fiéis para rezarem com ele.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos.\u003cbr/>\nSenhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Quo dicto, si est Missa sollemnis, Diaconus porrigit Celebranti Patenam cum Hostia: si privata, Sacerdos ipse accipit Patenam cum Hostia, quam offerens, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancte Pater, omnípotens ætérne Deus, hanc immaculátam hóstiam, quam ego indígnus fámulus tuus óffero tibi Deo meo vivo et vero, pro innumerabílibus peccátis, et offensiónibus, et neglegéntiis meis, et pro ómnibus circumstántibus, sed et pro ómnibus fidélibus christiánis vivis atque defúnctis: ut mihi, et illis profíciat ad salútem in vitam ætérnam. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Terminada esta leitura, o Sacerdote descobre o Cálice e toma nas mãos a patena com o pão, que vai ser consagrado. O Sacerdote oferece-os a Deus, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Pai santo, Deus omnipotente e eterno, esta hóstia imaculada, que eu, vosso indigno servo, Vos ofereço,  \u003cbr/>\nó meu Deus vivo e verdadeiro, pelos meus inumeráveis pecados, ofensas e negligências, por todos os assistentes  \u003cbr/>\ne por todos os cristãos vivos e mortos, a fim de que sirva de proveito para a minha salvação,  \u003cbr/>\npara a deles e para a vida eterna. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde faciens crucem cum eadem Patena, deponit Hostiam super Corporale. Diaconus ministrat vinum, Subdiaconus aquam in Calice: vel si privata est Missa, utrumque infundit Sacerdos, et aquam miscendam in Calice benedicit signo crucis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> qui humánæ substántiæ dignitátem mirabíliter condidísti, et mirabílius reformásti: da nobis per hujus aquæ et vini mystérium, ejus divinitátis esse consórtes, qui humanitátis nostræ fíeri dignátus est párticeps, Jesus Christus, Fílius tuus, Dóminus noster: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Ao lado direito do altar, o celebrante coloca vinho no cálice, ao qual mistura umas gotas de água, dizendo a seguinte oração:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> que maravilhosamente criastes a dignidade da natureza humana e que mais prodigiosamente ainda a reformastes,  \u003cbr/>\npermiti que pela mistura simbólica desta água e deste vinho sejamos participantes da divindade  \u003cbr/>\ndaquele que quis assumir a nossa humanidade, Jesus Cristo, vosso Filho, Nosso Senhor, que, sendo Deus,  \u003cbr/>\nvive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum dicitur prædicta Oratio: sed aqua non benedicitur.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Em Missas para Defuntos, a seguinte oração é dita, mas a água não é abençoada.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea accipit Calicem, et offert dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>fférimus tibi, Dómine, cálicem salutáris, tuam deprecántes cleméntiam: ut in conspéctu divínæ majestátis tuæ, pro nostra et totíus mundi salúte, cum odóre suavitátis ascéndat. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde facit signum crucis cum Calice, et illum ponit super Corporale, et Palla cooperit: tum, junctis manibus super Altare, aliquantulum inclinatus, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n spíritu humilitátis et in ánimo contríto suscipiámur a te, Dómine: et sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi, Dómine Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Erectus expandit manus, easque in altum porrectas jungens, elevátis ad cælum oculis et statim demissis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>eni, sanctificátor omnípotens ætérne Deus: \u003cFONT SIZE='1' COLOR=\"red\">Benedicit Oblata, prosequendo:\u003c/FONT> et béne \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dic hoc sacrifícium, tuo sancto nómini præparátum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>No meio do altar, o celebrante faz o oferecimento do cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>ós Vos oferecemos, Senhor, o Cálice da salvação; e Vos suplicamos que misericordiosamente o façais subir,  \u003cbr/>\ncomo suave perfume, diante da vossa divina majestade, para a nossa salvação e de todo o mundo. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, inclinando-se diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>m humildade e contrição, sejamos recebidos por Vós, Senhor;  \u003cbr/>\ne assim este sacrifício, ó Deus, se torne agradável aos vossos olhos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Invocação do Espírito Santo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>inde, ó Santificador omnipotente, Deus eterno, e abençoai \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> este sacrifício, preparado para a glória do vosso Santo Nome.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Sacerdos lavat manus, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps. 25, 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avábo inter innocéntes manus meas: et circúmdabo altáre tuum, Dómine: Ut áudiam vocem laudis, et enárrem univérsa mirabília tua. Dómine, diléxi decórem domus tuæ et locum habitatiónis glóriæ tuæ. Ne perdas cum ímpiis, Deus, ánimam meam, et cum viris sánguinum vitam meam: In quorum mánibus iniquitátes sunt: déxtera eórum repléta est munéribus. Ego autem in innocéntia mea ingréssus sum: rédime me et miserére mei. Pes meus stetit in dirécto: in ecclésiis benedícam te, Dómine.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O lavar das mãos simboliza a pureza da alma, necessária para oferecer o santo Sacrifício. O Sacerdote vai à direita do altar e lava as mãos, dizendo, entretanto, os seguintes versículos do salmo 25:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Psalm 25. 6-12\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>avarei as minhas mãos, como os inocentes, e rodearei, Senhor o vosso altar:  \u003cbr/>\nPara ouvir a voz dos vossos louvores e publicar todas as vossas maravilhas.  \u003cbr/>\nAmei, Senhor, o decoro da vossa casa e o lugar onde reside a vossa glória.  \u003cbr/>\nNão deixeis, ó meu Deus, que a minha alma se perca com os ímpios, nem a minha vida com os homens sanguinários,  \u003cbr/>\nque têm as mãos manchadas de iniquidades e a mão direita cheia de dádivas.  \u003cbr/>\nPois que tenho vivido na inocência, salvai-me e tende misericórdia de mim.  \u003cbr/>\nOs meus pés continuam firmes no caminho direito: e hei-de bendizer-Vos, Senhor, em todas as assembleias.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, aliquantulum inclinatus in medio Altaris, junctis manibus super eo, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, sancta Trínitas, hanc oblatiónem, quam tibi offérimus ob memóriam passiónis, resurrectiónis, et ascensiónis Jesu Christi, Dómini nostri: et in honórem beátæ Maríæ semper Vírginis, et beáti Joannis Baptistæ, et sanctórum Apostolórum Petri et Pauli, et istórum et ómnium Sanctórum: ut illis profíciat ad honórem, nobis autem ad salútem: et illi pro nobis intercédere dignéntur in cælis, quorum memóriam ágimus in terris. Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, ao meio do altar, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, ó Santíssima Trindade, esta oblação, que Vos oferecemos em memória da Paixão, da Ressurreição  \u003cbr/>\ne da Ascensão de Nosso Senhor Jesus Cristo: e em honra da bem-aventurada sempre Virgem Maria, do bem-aventurado João Baptista  \u003cbr/>\ne dos Santos Apóstolos Pedro e Paulo, e destes, que estão aqui, e de todos os Santos: para que esta oblação  \u003cbr/>\nlhes sirva de glória e a nós de salvação: e aqueles, cuja memória honramos na terra, se dignem interceder por nós no céu.  \u003cbr/>\nPelo mesmo Jesus Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea osculatur Altare, et versus ad populum extendens, et jungens manus, voce paululum elevata, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Oráte, fratres: ut meum ac vestrum sacrifícium acceptábile fiat apud Deum Patrem omnipoténtem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Minister, seu circumstantes respondent: alioquin ipsemet Sacerdos:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Suscípiat Dóminus sacrifícium de mánibus tuis \u003cFONT SIZE='1' COLOR=\"red\">vel meis\u003c/FONT> ad laudem et glóriam nominis sui, ad utilitátem quoque nostram, totiúsque Ecclésiæ suæ sanctæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sacerdos submissa voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, manibus extensis, absolute sine Orémus subjungit Orationes secretas.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDeus, cujus misericórdiæ non est númerus, súscipe propítius preces humilitátis nostræ: et animábus fratrum, propinquórum et benefactórum nostrórum, quibus tui nóminis dedísti confessiónem, per hæc sacraménta salútis nostræ, cunctórum remissiónem tríbue peccatórum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Beija o Altar e voltando-se para os fiéis, o Sacerdote convida-os a orar com ele:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Orai, meus irmãos, a fim de que o meu sacrifício, que é também vosso, seja recebido por Deus Pai omnipotente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O acólito responde:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que o Senhor receba pelas tuas mãos este sacrifício para a honra e glória do seu Nome,  \u003cbr/>\ne também para a nossa utilidade e de toda sua santa Igreja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote responde, em voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Em seguida lê a Secreta. À Secreta principal, podem, em certas Missas, juntar-se outras, em número igual \u003c/I>\u003c/FONT> \u003cbr/>\ne segundo as mesmas regras da Colecta.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI> Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus, cuja misericórdia é infinita, ouvi benigno as nossas humildes preces, e concedei, pela virtude deste sacramento da nossa salvação, o perdão dos seus pecados às almas dos nossos irmãos, parentes e benfeitores, aos quais permitistes a graça de confessarem o vosso nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Præfatio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Præfatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus finitis, cum pervenerit ad conclusionem, clara voce dicit: Per ómnia sǽcula sæculórum, cum Præfatione, ut in sequentibus. Præfationem incipit ambabus manibus positis hinc inde super Altare: quas aliquantulum elevat, cum dicit: Sursum corda. Jungit eas ante pectus, et caput inclinat, cum dicit: Grátias agamus Dómino, Deo nostro. Deinde disjungit manus, et disjunctas tenet usque ad finem Præfationis: qua finita, iterum jungit eas, et inclinatus dicit: Sanctus. Et cum dicit: Benedíctus, qui venit, signum crucis sibi producit a fronte ad pectus.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Sursum corda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Habémus ad Dóminum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Grátias agámus Dómino, Deo nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Dignum et justum est.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Defunctorum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctus, Sanctus, Sanctus Dóminus, Deus Sábaoth. Pleni sunt cæli et terra glória tua. Hosánna in excélsis. Benedíctus, qui venit in nómine Dómini. Hosánna in excélsis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Com o Prefácio, começa a grande, a solene oração sacerdotal da Igreja e a oblação propriamente dita do Sacrifício. Curto diálogo introdutório entre o Sacerdote e os fiéis desperta nas almas os sentimentos de acção de graças que convêm à celebração dos santos mistérios.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Corações ao alto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim os temos para o Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Demos graças ao Senhor, Nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Assim é digno e justo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai omnipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\u003cbr/>\n\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anto, Santo, Santo, Senhor Deus do Universo. O céu e a terra proclamam a vossa glória. Hossana nas alturas.  \u003cbr/>\nBendito o que vem em nome do Senhor. Hosana nas alturas.\u003cbr/>\n"},{"label":"Canon","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Canon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finita præfatione, sacerdos extendens, elevans aliquantulum et iungens manus, elevansque ad cælum oculos, et statim demittens, profunde inclinatus ante Altare, manibus super eo positis, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>e ígitur, clementíssime Pater, per Jesum Christum, Fílium tuum, Dóminum nostrum, súpplices rogámus, ac pétimus, \u003cFONT SIZE='1' COLOR=\"red\">osculatur Altare et, junctis manibus ante pectus, dicit:\u003c/FONT> uti accépta hábeas et benedícas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam et Calicem simul, dicens:\u003c/FONT> hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dona, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> múnera, hæc \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sancta sacrifícia illibáta, \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT> in primis, quæ tibi offérimus pro Ecclésia tua sancta cathólica: quam pacificáre, custodíre, adunáre et régere dignéris toto orbe terrárum: una cum fámulo tuo Papa nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et Antístite nostro \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  et ómnibus orthodóxis, atque cathólicæ et apostólicæ fídei cultóribus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Cânon\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós, pois, rogamos e pedimos, ó clementíssimo Pai, por Jesus Cristo, vosso Filho e Nosso Senhor,  \u003cbr/>\nque estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dons, estas \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ofertas, estes \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sacrifícios santos e imaculados Vos sejam agradáveis e os abençoeis,  \u003cbr/>\nos quais, antes de tudo, Vos oferecemos pela nossa santa Igreja Católica: dignai-Vos conceder-lhe a paz, guardá-la,  \u003cbr/>\nuni-la e governá-la por toda a terra, em comunhão com vosso servo, o nosso Papa \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, com o nosso Bispo \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>  \u003cbr/>\ne com todos os \u003cFONT SIZE='1' COLOR=\"red\">bispos\u003c/FONT> ortodoxos e os que professam a fé católica e apostólica.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro vivis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto, Dómine, famulórum famularúmque tuarum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquantulum pro quibus orare intendit: deinde manibus extensis prosequitur:\u003c/FONT> et ómnium circumstántium, quorum tibi fides cógnita est et nota devótio, pro quibus tibi offérimus: vel qui tibi ófferunt hoc sacrifícium laudis, pro se suísque ómnibus: pro redemptióne animárum suárum, pro spe salútis et incolumitátis suæ: tibíque reddunt vota sua ætérno Deo, vivo et vero.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Memento dos vivos\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-Vos, Senhor, dos vossos servos \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e de todos os que aqui estão presentes, cuja fé Vos é conhecida  \u003cbr/>\ne a piedade é notória: pelos quais Vos oferecemos, ou eles Vos oferecem, este sacrifício de louvor por si próprios  \u003cbr/>\ne por todos os seus, pela redenção das suas almas, pela esperança da sua salvação: é a Vós que oferecem as homenagens,  \u003cbr/>\ncomo Deus eterno, vivo e verdadeiro, que sois.\u003cbr/>\n"},{"label":"communicantes","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n \u003cbr/>\net beatórum Apostolórum ac Mártyrum tuórum, Petri et Pauli, Andréæ, Jacóbi, Joánnis, Thomæ, Jacóbi, Philíppi, Bartholomǽi, Matthǽi, Simónis et Thaddǽi: Lini, Cleti, Cleméntis, Xysti, Cornélii, Cypriáni, Lauréntii, Chrysógoni, Joánnis et Pauli, Cosmæ et Damiáni: et ómnium Sanctórum tuórum; quorum méritis precibúsque concédas, ut in ómnibus protectiónis tuæ muniámur auxílio. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n \u003cbr/>\ne depois também a dos vossos bem-aventurados Apóstolos e Mártires: Pedro e Paulo, André, Tiago, João, Tomé, Tiago,  \u003cbr/>\nFilipe, Bartolomeu, Mateus, Simão e Tadeu: Lino, Cleto, Clemente, Xisto, Cornélio, Cipriano, Lourenço, Crisógono,  \u003cbr/>\nJoão e Paulo, Cosme e Damião: e de todos vossos Santos.  \u003cbr/>\nDignai-Vos permitir que pelos seus méritos e preces gozemos do poderoso auxílio da vossa protecção.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tenens manus expansas super Oblata, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>anc ígitur oblatiónem servitútis nostræ, sed et cunctæ famíliæ tuæ,\u003cbr/>\n\u003cbr/>\nquǽsumus, Dómine, ut placátus accípias: diésque nostros in tua pace dispónas, atque ab ætérna damnatióne nos éripi, et in electórum tuórum júbeas grege numerári. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus\u003c/FONT> Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Estendendo as mãos sobre as oblatas, o celebrante diz::\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, Vos rogamos que Vos digneis receber favoravelmente esta oferta que eu,  \u003cbr/>\nvosso indigno servo, e toda a vossa família Vos fazemos;\u003cbr/>\n\u003cbr/>\nconcedei-nos o gozo da vossa paz nos nossos dias, livrai-nos da condenação eterna  \u003cbr/>\ne admiti-nos ao número dos vossos escolhidos. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uam oblatiónem tu, Deus, in ómnibus, quǽsumus, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Oblata,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díctam, adscríp \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, ra \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> tam, rationábilem, acceptabilémque fácere dignéris: \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam,\u003c/FONT> ut nobis Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem,\u003c/FONT> et San \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guis fiat dilectíssimi Fílii tui, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus,\u003c/FONT> Dómini nostri Jesu Christi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta oblação, ó Deus, Vos imploramos, seja abençoada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> aprovada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> confirmada, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> digna e aceitável,  \u003cbr/>\na fim de que se converta para nós no Corpo e no Sangue do vosso amado Filho, Nosso Senhor Jesus Cristo.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui prídie quam paterétur, \u003cFONT SIZE='1' COLOR=\"red\">Accipit Hostiam,\u003c/FONT> accépit panem in sanctas ac venerábiles manus suas, \u003cFONT SIZE='1' COLOR=\"red\">Elevat oculos ad cælum,\u003c/FONT> et elevátis óculis in cælum ad te Deum, Patrem suum omnipoténtem, \u003cFONT SIZE='1' COLOR=\"red\">Caput inclinat,\u003c/FONT> tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Signat super Hostiam,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, fregit, dedítque discípulis suis, dicens: Accípite, et manducáte ex hoc omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> qual, na véspera da sua paixão tomou o pão nas suas santas e veneráveis mãos: e, erguendo os olhos ao céu,  \u003cbr/>\na Vós, Deus seu Pai omnipotente, e dando-Vos graças, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoou-o, partiu-o e deu-o aos seus discípulos, dizendo:  \u003cbr/>\nTomai todos e comei:\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tenens ambabus manibus Hostiam inter indices et pollices, profert verba consecrationis secrete, distincte et attente super Hostiam, et simul super omnes, si plures sint consecrandæ.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHOC EST ENIM CORPUS MEUM.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, statim Hostiam consecratam genuflexus adorat: surgit, ostendit populo, reponit super Corporale, et genuflexus iterum adorat: nec amplius pollices et indices disjungit, nisi quando Hostia tractanda est, usque ad ablutionem digitorum.\u003c/I>\u003c/FONT>\u003cbr/>\nwait5\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras de Consagração do Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O MEU CORPO.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois de pronunciar as palavras de consagração, o padre, ajoelhado, adora a Sagrada Hóstia; levanta-se, elevando-a. -- Olha-a com fé, piedade e amor, dizendo: \"Meu Senhor e meu Deus.\" -- e colocando-a de volta no corporal, novamente a adora. Depois, nunca mais separa os dedos e polegar, excepto quando toma a Hóstia, até à lavagem dos dedos.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Tunc, detecto Calice, dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>ímili modo postquam cenátum est, \u003cFONT SIZE='1' COLOR=\"red\">Ambabus manibus accipit Calicem,\u003c/FONT> accípiens et hunc præclárum Cálicem in sanctas ac venerábiles manus suas: \u003cFONT SIZE='1' COLOR=\"red\">item Caput inclinat,\u003c/FONT> item tibi grátias agens, \u003cFONT SIZE='1' COLOR=\"red\">Sinistra tenens Calicem, dextera signat super eum,\u003c/FONT> bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> díxit, dedítque discípulis suis, dicens: Accípite, et bíbite ex eo omnes.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Consagração e Elevação do Cálice:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>o mesmo modo, Jesus, após a Ceia, tomou nas suas santas e veneráveis mãos este precioso Cálice,  \u003cbr/>\ne, novamente, dando-Vos graças, abençoou-o \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e deu-o aos seus discípulos dizendo: Tomai e bebei dele todos,\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profert verba consecrationis super Calicem, attente, continuate, et secrete, tenens illum parum elevatum.\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\nHIC EST ENIM CALIX SANGUINIS MEI, NOVI ET ÆTERNI TESTAMENTI: MYSTERIUM FIDEI: QUI PRO VOBIS ET PRO MULTIS EFFUNDETUR IN REMISSIONEM PECCATORUM.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Quibus verbis prolatis, deponit Calicem super Corporale, et dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc quotiescúmque fecéritis, in mei memóriam faciétis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Genuflexus adorat: surgit, ostendit populo, deponit, cooperit, et genuflexus iterum adorat.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Palavras da Consagração do Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n_\u003cbr/>\n POIS ISTO É O CÁLICE DO MEU SANGUE DO NOVO E ETERNO TESTAMENTO, MISTÉRIO DA FÉ, QUE SERÁ DERRAMADO POR VÓS E POR MUITOS, PARA REMISSÃO DOS PECADOS.\u003cbr/>\nwait5\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois da consagração do Cálice, o Sacerdote diz com uma voz baixa:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>odas as vezes que fizerdes isto, fazei-o em memória de mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O padre ajoelha-se e adora o Precioso Sangue; levanta-se, elevando o Cálice, e quando o baixa e o cobre, novamente o adora.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Deinde disjunctis manibus dicit:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nde et mémores, Dómine, nos servi tui, sed et plebs tua sancta, ejúsdem Christi Fílii tui, Dómini nostri, tam beátæ passiónis, nec non et ab ínferis resurrectiónis, sed et in cælos gloriósæ ascensiónis: offérimus præcláræ majestáti tuæ de tuis donis ac datis, \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> puram, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctam, Hóstiam \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> immaculátam, \u003cFONT SIZE='1' COLOR=\"red\">Signat semel super Hostiam, dicens:\u003c/FONT> Panem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sanctum vitæ ætérnæ, \u003cFONT SIZE='1' COLOR=\"red\">et semel super Calicem, dicens:\u003c/FONT> et Cálicem \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> salútis perpétuæ.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">O Sacerdote continua depois as orações do Cânon:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or este motivo, Senhor, nós, vossos servos, e o vosso povo santo,  \u003cbr/>\nlembrando-nos da bem-aventurada Paixão do mesmo Cristo, vosso Filho e Senhor nosso,  \u003cbr/>\nassim como também da sua Ressurreição dos mortos e da sua gloriosa Ascensão aos céus,  \u003cbr/>\noferecemos à vossa divina majestade os mesmos dons que nos foram dados:  \u003cbr/>\na Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pura, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santa, a Hóstia \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> imaculada, o Pão \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santo da vida eterna e o Cálice \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> da salvação perpétua.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus prosequitur:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>upra quæ propítio ac seréno vultu respícere dignéris: et accépta habére, sicúti accépta habére dignátus es múnera púeri tui justi Abel, et sacrifícium Patriárchæ nostri Abrahæ: et quod tibi óbtulit summus sacérdos tuus Melchísedech, sanctum sacrifícium, immaculátam hóstiam.\u003cbr/>\n","pt":"\u003cFONT SIZE='1' COLOR=\"red\">Com as mãos afastadas, contínua:\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>obre estas ofertas dignai-Vos lançar um olhar propício e benévolo e aceitá-las,  \u003cbr/>\ncomo Vos dignastes receber os dons do justo Abel, vosso servo, o sacrifício do nosso Patriarca Abraão  \u003cbr/>\ne o que Vos ofereceu o Sumo sacerdote Melquisedeque, pois este é um sacrifício santo, uma hóstia imaculada.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Profunde inclinatus, junctis manibus et super Altare positis, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úpplices te rogámus, omnípotens Deus: jube hæc perférri per manus sancti Angeli tui in sublíme altáre tuum, in conspéctu divínæ majestátis tuæ: ut, quotquot \u003cFONT SIZE='1' COLOR=\"red\">Osculatur Altare,\u003c/FONT> ex hac altáris participatióne sacrosánctum Fílii tui \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et signat semel super Hostiam, et semel super Calicem,\u003c/FONT> Cor \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> pus, et Sán \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> guinem sumpsérimus, \u003cFONT SIZE='1' COLOR=\"red\">Seipsum signat, dicens:\u003c/FONT> omni benedictióne cælésti et grátia repleámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Profundamente inclinado, o Sacerdote diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>umildemente Vos rogamos, ó Deus omnipotente, ordeneis que estas ofertas sejam apresentadas  \u003cbr/>\nno altar sublime pelas mãos do vosso Santo Anjo, na presença da vossa divina majestade,  \u003cbr/>\na fim de que todos aqueles que participam deste Altar pela recepção do Santíssimo Corpo \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e Sangue \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do vosso Filho  \u003cbr/>\nsejam repletos de todas as bênçãos do céu e de todas as graças. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Commemoratio pro defunctis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>eménto étiam, Dómine, famulórum famularúmque tuárum \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> et \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, qui nos præcessérunt cum signo fídei, et dórmiunt in somno pacis.wait10 \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, orat aliquántulum pro iis defunctis, pro quibus orare intendit, deinde extensis manibus prosequitur:\u003c/FONT> Ipsis, Dómine, et ómnibus in Christo quiescéntibus locum refrigérii, lucis, et pacis, ut indúlgeas, deprecámur. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus, et caput inclinat, dicens:\u003c/FONT> Per eúndem Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Memento dos Defuntos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>embrai-Vos também Senhor, dos vossos servos e servas \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT> e \u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>N.\u003c/I>\u003c/B>\u003c/FONT>, que partiram antes de nós,  \u003cbr/>\nmarcados com o sinal da fé, e agora dormem o sono da paz.wait10  \u003cbr/>\n\u003cFONT SIZE='1' COLOR=\"red\">Junta as mãos e ora por estes defuntos, depois, estendendo as mãos, continua:\u003c/FONT>  \u003cbr/>\nNós Vos suplicamos, Senhor, dignai-Vos conceder a estes, assim como a todos os que descansam em Cristo,  \u003cbr/>\num lugar de consolação, de luz e de paz. Pelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Manu dextera percutit sibi pectus, elata aliquantulum voce dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>N\u003c/I>\u003c/B>\u003c/FONT>obis quoque peccatóribus \u003cFONT SIZE='1' COLOR=\"red\">Extensis manibus ut prius, secrete prosequitur:\u003c/FONT> fámulis tuis, de multitúdine miseratiónum tuárum sperántibus, partem áliquam et societátem donáre dignéris, cum tuis sanctis Apóstolis et Martýribus: cum Joánne, Stéphano, Matthía, Bárnaba, Ignátio, Alexándro, Marcellíno, Petro, Felicitáte, Perpétua, Agatha, Lúcia, Agnéte, Cæcília, Anastásia, et ómnibus Sanctis tuis: intra quorum nos consórtium, non æstimátor mériti, sed véniæ, quǽsumus, largítor admítte. \u003cFONT SIZE='1' COLOR=\"red\">Jungit manus.\u003c/FONT> Per Christum, Dóminum nostrum.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>o Sacerdote bate no peito, dizendo.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT> também a nós, pecadores, vossos servos, que esperamos na grandeza das vossas misericórdias,  \u003cbr/>\ndignai-Vos conceder-nos alguma parte na vossa herança e sociedade com vossos Santos Apóstolos e Mártires:  \u003cbr/>\nJoão, Estêvão, Matias, Barnabé, Inácio, Alexandre, Marcelino, Pedro, Felicidade, Perpétua, Águeda, Luzia, Inês,  \u003cbr/>\nCecília, Anastácia e com todos os Santos, em cuja companhia, Vos pedimos, nos recebais,  \u003cbr/>\nnão em consideração dos nossos merecimentos, mas segundo a liberalidade da vossa misericórdia. Por Cristo, Nosso Senhor.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er quem hæc ómnia, Dómine, semper bona creas, \u003cFONT SIZE='1' COLOR=\"red\">Signat ter super Hostiam, et Calicem simul, dicens:\u003c/FONT> sanctí \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, viví \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> ficas, bene \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> dícis et præstas nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Discooperit Calicem, genuflectit, accipit Hostiam inter pollicem et indicem manus dexteræ: et tenens sinistra Calicem, cum Hostia signat ter a labio ad labium Calicis, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sum, et cum Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, et in Ip \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> so, \u003cFONT SIZE='1' COLOR=\"red\">Cum ipsa Hostia signat bis inter se et Calicem, dicens:\u003c/FONT> est tibi Deo Patri \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> omnipoténti, in unitáte Spíritus \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Sancti, \u003cFONT SIZE='1' COLOR=\"red\">Elevans parum Calicem cum Hostia, dicit:\u003c/FONT> omnis honor, et glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>ponit Hostiam, Calicem Palla cooperit, genuflectit, surgit, et dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or quem, Senhor, sempre criais estes bens e os \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> santificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> vivificais, \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> abençoais e no-los concedeis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Descobre o Cálice, e genuflecte: depois tomando a Hóstia na sua mão direita, e segurando o Cálice na esquerda, assinala com o Sinal da Cruz três vezes pelo Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Ele +, com Ele \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> e n’Ele +, a Vós, ó Deus Pai todo-poderoso +, na unidade do Espírito \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> Santo\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eleva um pouco o Cálice com a Hóstia.\u003c/I>\u003c/FONT>\u003cbr/>\npertence, e Vos é dada, toda a honra e glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ajoelha-se e levantando-se, diz \u003cFONT SIZE='1' COLOR=\"red\">ou canta\u003c/FONT>:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"Preparatio Communionis","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparatio Communionis\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>\u003cFONT SIZE='1' COLOR=\"red\">Iungit manus.\u003c/FONT>\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus: Præcéptis salutáribus móniti, et divína institutióne formáti audémus dícere:\u003cFONT SIZE='1' COLOR=\"red\">Extendit manus.\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ater noster, qui es in cælis. Sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cælo et in terra. Panem nostrum quotidiánum da nobis hódie. Et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sed líbera nos a malo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> \u003cFONT SIZE='1' COLOR=\"red\">Sacerdos secrete dicit :\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Preparação para Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos. Instruídos com os salutares preceitos do Salvador e dirigidos pelos seus divinos ensinamentos, ousamos dizer:\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ai nosso que estais nos céus;  \u003cbr/>\nsantificado seja o vosso nome;  \u003cbr/>\nvenha a nós o vosso reino;  \u003cbr/>\nseja feita a vossa vontade,  \u003cbr/>\nassim na terra como no céu.  \u003cbr/>\nO pão nosso de cada dia nos dai hoje;  \u003cbr/>\nperdoai-nos as nossas dívidas,  \u003cbr/>\nassim como nós perdoamos aos nossos devedores  \u003cbr/>\ne não nos deixeis cair em tentação:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Mas livrai-nos do mal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde manu dextera accipit inter indicem et medium digitos Patenam, quam tenens super Altare erectam, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>íbera nos, quǽsumus, Dómine, ab ómnibus malis, prætéritis, præséntibus et futúris: et intercedénte beáta et gloriósa semper Vírgine Dei Genetríce María, cum beátis Apóstolis tuis Petro et Paulo, atque Andréa, et ómnibus Sanctis, \u003cFONT SIZE='1' COLOR=\"red\">Signat se cum Patena a fronte ad pectus,\u003c/FONT> da propítius pacem in diébus nostris: \u003cFONT SIZE='1' COLOR=\"red\">Patenam osculatur,\u003c/FONT> ut, ope misericórdiæ tuæ adjúti, et a peccáto simus semper líberi et ab omni perturbatióne secúri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Submittit Patenam Hostiæ, discooperit Calicem, genuflectit, surgit, accipit Hostiam, et eam super Calicem tenens utraque manu, frangit per medium, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum, Fílium tuum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et mediam partem, quam in dextera manu tenet, ponit super Patenam. Deinde ex parte, quæ in sinistra remanserat, frangit particulam, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\nQui tecum vivit et regnat in unitáte Spíritus Sancti Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Aliam mediam partem, quam in sinistra manu habet, adjungit mediæ super Patenam positæ, et particulam parvam dextera retinens super Calicem, quem sinistra per nodum infra cuppam tenet, dicit intellegibili voce vel cantat:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cum ipsa particula signat ter super Calicem, dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ax Dómini sit semper vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte e segura com os dedos polegar e indicador da mão direita a Hóstia e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>ivrai-nos, Senhor, Vos suplicamos, de todos os males passados, presentes e futuros;  \u003cbr/>\ne, pela intercessão da bem-aventurada e gloriosa sempre Virgem Maria, Mãe de Deus,  \u003cbr/>\ne dos bem-aventurados Apóstolos Pedro e Paulo e André, e de todos os Santos,  \u003cbr/>\ndai-nos, benignamente, a paz nos nossos dias, a fim de que auxiliados pela vossa misericórdia,  \u003cbr/>\nsejamos sempre livres do pecado e seguros de toda a perturbação.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote descobre o Cálice, genuflecte, que ergue até ao cimo do cálice.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Nosso Senhor Jesus Cristo, vosso Filho, que é Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote parte a Hóstia ao meio, de uma das partes tira um pequeno fragmento que deita no preciosíssimo Sangue, \u003c/I>\u003c/FONT> \u003cbr/>\ntraçando antes, com ele, sobre o Cálice, três vezes, o sinal da cruz, e dizendo:\u003cbr/>\nQue convosco vive e reina na unidade do Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Depois, o Sacerdote, tendo entre os dedos da mão direita a Partícula, que fraccionou, coloca-a sobre o Cálice, que segura pelos nós, e acrescenta em voz alta:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote faz três vezes o sinal da Cruz com a Divina Partícula sobre o Cálice:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Que a paz \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> do Senhor esteja \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> sempre \u003cspan style='color:red; font-size:1.25em'>✠\u003c/span> convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Particulam ipsam immittit in Calicem, dicens secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc commíxtio, et consecrátio Córporis et Sánguinis Dómini nostri Jesu Christi, fiat accipiéntibus nobis in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cooperit Calicem, genuflectit, surgit, et inclinatus Sacramento, junctis manibus, et ter pectus percutiens, intellegibili voce dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Coloca a partícula no Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta mistura e esta consagração do Corpo e do Sangue de Nosso Senhor Jesus Cristo  \u003cbr/>\nsejam penhor de vida eterna para nós que a receberemos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Cobre o Cálice, genuflecte e levanta-se; depois inclinando-se e batendo três vezes no peito, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non dicitur miserére nobis, sed ejus loco dona eis requiem, et in tertio additur sempitérnam.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>gnus Dei, qui tollis peccáta mundi: dona eis réquiem sempitérnam.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote bate três vezes no peito, e diz a oração seguinte. Nas Missas de Defuntos, não se bate no peito e em vez de miserére nobis, diz-se: Dona eis requiem; na terceira parte: dona eis requiem sempiternam:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ordeiro de Deus, que tirais o pecado do mundo, dai-lhes o descanso eterno.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde, junctis manibus super Altare, inclinatus dicit secrete sequentes Orationes:\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Inclinado, recita as três orações seguintes, pela paz, santificação e graça da Igreja:\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur pax, neque dicitur oratio Domine Jesu Christe, qui dixisti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas dos Defuntos, o beijo da paz não é dado.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ómine Jesu Christe, Fili Dei vivi, qui ex voluntáte Patris, cooperánte Spíritu Sancto, per mortem tuam mundum vivificásti: líbera me per hoc sacrosánctum Corpus et Sánguinem tuum ab ómnibus iniquitátibus meis, et univérsis malis: et fac me tuis semper inhærére mandátis, et a te numquam separári permíttas: Qui cum eódem Deo Patre et Spíritu Sancto vivis et regnas Deus in sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, Filho do Deus vivo, que, por vontade do Pai, cooperando o Espírito Santo,  \u003cbr/>\npela vossa morte destes a vida ao mundo: livrai-nos de todos os males por este vosso sacrossanto Corpo e Sangue.  \u003cbr/>\nPermiti que cumpra sempre os vossos preceitos e nunca me afaste de Vós,  \u003cbr/>\nque sendo Deus, viveis e reinais com o mesmo Deus Pai e Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ercéptio Córporis tui, Dómine Jesu Christe, quod ego indígnus súmere præsúmo, non mihi provéniat in judícium et condemnatiónem: sed pro tua pietáte prosit mihi ad tutaméntum mentis et córporis, et ad medélam percipiéndam: Qui vivis et regnas cum Deo Patre in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Jesus Cristo, que este vosso Corpo, que eu, ainda que indigno, vou receber,  \u003cbr/>\nnão seja para o meu juízo e condenação, mas que, pela vossa misericórdia, sirva à minha alma e ao meu corpo  \u003cbr/>\nde defesa e de remédio salutar:  \u003cbr/>\nVós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo por todos os séculos dos séculos. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Genuflectit, surgit, et dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>anem cæléstem accípiam, et nomen Dómini invocábo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde parum inclinatus, accipit ambas partes Hostiæ inter pollicem et indicem sinistræ manus, et Patenam inter eundem indicem et medium supponit, et dextera tribus vicibus percutiens pectus, elata aliquantulum voce, ter dicit devote et humiliter:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dómine, non sum dignus, \u003cFONT SIZE='1' COLOR=\"red\">Et secrete prosequitur:\u003c/FONT> ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote genuflecte e pegando depois na sagrada Hóstia:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>omarei o Pão do céu e invocarei o nome do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Inclinado, toma as duas metades da Hóstia entre o polegar e o indicador da mão esquerda, e a patena entre o mesmo indicador e o dedo do meio; Em seguida bate três vezes no peito, dizendo devotamente e humilhado:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Senhor, eu não sou digno que entreis na minha morada, mas dizei uma só palavra e a minha alma será salva.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dextera se signans cum Hostia super Patenam, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et se inclinans, reverenter sumit ambas partes Hostiæ: quibus sumptis, deponit Patenam super Corporale, et erigens se jungit manus, et quiescit aliquantulum in meditatione Sanctissimi Sacramenti.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Faz sobre si o sinal da cruz com a sagrada Hóstia, antes de a comungar.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Corpo de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recolhe-se por uns instantes.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde discooperit Calicem, genuflectit, colligit fragmenta, si quæ sint, extergit Patenam super Calicem, interim dicens:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uid retríbuam Dómino pro ómnibus, quæ retríbuit mihi? Cálicem salutáris accípiam, et nomen Dómini invocábo. Laudans invocábo Dóminum, et ab inimícis meis salvus ero.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Accipit Calicem manu dextera, et eo se signans, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anguis Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et sinistra supponens Patenam Calici, reverenter sumit totum Sanguinem cum particula. Quo sumpto, si qui sunt communicandi, eos communicet, antequam se purificet\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>De seguida descobre o Cálice, genuflecte, recolhe quaisquer fragmentos que estiverem no corporal e purifica a patena sobre o Cálice, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>omo retribuirei ao Senhor os bens que Ele se dignou dispensar-me?  \u003cbr/>\nTomarei o Cálice da salvação e invocarei o nome do Senhor, louvando-O, e ficarei livre dos meus inimigos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Toma o preciosíssimo Sangue, fazendo antes sobre si o sinal da cruz\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue o Sangue de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Recebe depois todo o Precioso Sangue, junto com a Partícula.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n","pt":"\u003cA HREF=\"mpopup.pl?popup=Communio&rubrics=1&lang1=Latin&lang2=Portugues\" TARGET=\"_NEW\">Communio\u003c/A>\u003cbr/>\n\u003cbr/>\nwait16\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Postea dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>uod ore súmpsimus, Dómine, pura mente capiámus: et de múnere temporáli fiat nobis remédium sempitérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Interim porrigit Calicem ministro, qui infundit in eo parum vini, quo se purificat: deinde prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>orpus tuum, Dómine, quod sumpsi, et Sanguis, quem potávi, adhǽreat viscéribus meis: et præsta; ut in me non remáneat scélerum mácula, quem pura et sancta refecérunt sacraménta: Qui vivis et regnas in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Abluit et extergit digitos, ac sumit ablutionem: extergit os et Calicem, quem, plicato Corporali, operit et collocat in Altari ut prius: deinde prosequitur Missam.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI> Entretanto, diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue conservemos com pureza de coração, Senhor, o que a boca acaba de receber;  \u003cbr/>\ne que esta dádiva temporal se torne para nós remédio sempiterno.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> O Sacerdote purifica primeiro o cálice e depois os dedos, e toma as abluções.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, que o vosso Corpo, que recebi, e o vosso sangue, que bebi, se unam intimamente às minhas entranhas;  \u003cbr/>\ndignai-Vos permitir, Senhor, que não fique em mim mancha alguma de pecado,  \u003cbr/>\nagora que estou confortado com sacramentos tão puros e santos: Vós, que viveis e reinais em todos os séculos. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Purifica o cálice e deixa-o, coberto, no meio do altar. Nas Missas solenes, é o subdiácono quem purifica o cálice e o leva para a credência. O Sacerdote passa para o lado direito do altar, e recita a antífona da Comunhão.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"Communio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Esdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nLux ætérna lúceat eis, Dómine:\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.\u003cbr/>\n* Cum Sanctis tuis in ætérnum: quia pius es.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>4 Ezdr 2:35; 2:34\u003c/I>\u003c/FONT>\u003cbr/>\nQue a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso.\u003cbr/>\n"},{"label":"Postcommunio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicta antiphona ad Communionem, osculatur altare, et versus ad populum dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Deinde, reversus ad altare, dicit :\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens et miséricors Deus: ut ánimæ fratrum, propinquórum et benefactórum nostrórum, pro quibus hoc sacrifícium laudis tuæ obtúlimus majestáti; per hujus virtútem sacraménti a peccátis ómnibus expiátæ, lucis perpétuæ, te miseránte, recípiant beatitúdinem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O Sacerdote volta ao meio do altar, beija-o, e, voltando-se para os fiéis saúda-os:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e misericordioso, Vos pedimos, concedei às almas dos nossos irmãos, parentes e benfeitores, pelos quais oferecemos à vossa majestade este sacrifício de louvor, a graça de alcançarem da vossa misericórdia, pela virtude deste sacramento, a expiação dos pecados e a felicidade da luz eterna.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"Conclusio","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dicto, post ultimam Orationem,\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>M.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>dicit pro Missæ qualitate, vel Ite, Missa est, vel Benedicámus Dómino. Deo grátias.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Conclusão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Vira-se para as pessoas e diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n"},{"label":"itemissaest","la":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Requiéscant in pace.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Que descansem em paz.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Tunc celebrans inclinat se ante medium altaris, et manibus junctis super illud, dicit secrete:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>láceat tibi, sancta Trínitas, obséquium servitútis meæ: et præsta; ut sacrifícium, quod óculis tuæ majestátis indígnus óbtuli, tibi sit acceptábile, mihíque et ómnibus, pro quibus illud óbtuli, sit, te miseránte, propitiábile. Per Christum, Dóminum nostrum. Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>antíssima Trindade, seja-Vos agradável a homenagem da minha escravidão, a fim de que este sacrifício, que,  \u003cbr/>\nainda indignamente, ofereci à vossa divina majestade, seja aceite por Vós, e, pela vossa misericórdia,  \u003cbr/>\nse torne propiciatório para mim e para todos aqueles por quem o ofereci. Por Cristo, Nosso Senhor. Amém.\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>In Missis Defunctorum non datur benedíctio, sed dicto Requiéscant in pace, dicit: Pláceat tibi, sancta Trinitas; deinde osculato Altari, legit Evangelium sancti Joannis, nisi sequatur absolutio super tumulum seu catafalcum \u003cFONT SIZE='1' COLOR=\"red\">cf. Rubr. 510e\u003c/FONT>.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Nas Missas de Defuntos a bênção é omitida.\u003c/I>\u003c/FONT>\u003cbr/>\n"},{"label":"","la":"\u003cFONT COLOR=\"red\">\u003cI>Deinde sacerdos in cornu Evangelii, junctis manibus dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Dóminus vobíscum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Et cum spíritu tuo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Et signans signo crucis primum Altare vel librum, deinde se in fronte, ore et pectore, dicit:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Inítium \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Joánnem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann. 1, 1-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Junctis manibus prosequitur:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt.\u003cbr/>\nFuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine.\u003cbr/>\nErat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt. \u003cFONT SIZE='1' COLOR=\"red\">Genuflectit dicens:\u003c/FONT> Et Verbum caro factum est, \u003cFONT SIZE='1' COLOR=\"red\">Et surgens prosequitur:\u003c/FONT> et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Finito Evangelio sancti Joannis, discedens ab Altari, pro gratiarum actione dicit Ant. Trium puerórum, cum reliquis, ut habetur in principio Missalis.\u003c/I>\u003c/FONT>\u003cbr/>\n","pt":"\u003cFONT COLOR=\"red\">\u003cI>Indo depois para o lado do Evangelho, o padre diz:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> O Senhor esteja convosco.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> E com o teu espírito\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Despois faz o sinal da Cruz na Sacra \u003cFONT SIZE='1' COLOR=\"red\">ou no Missal\u003c/FONT> e na sua testa, boca e peito, dizendo:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>rincípio \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Jo. 1, 1-14.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Com as mãos juntas, continua:\u003c/I>\u003c/FONT>\u003cbr/>\nNo princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.  Ele estava no princípio em Deus.  Todas as coisas foram feitas por Ele, e sem Ele nada se fez do que foi feito.  N’Ele estava a vida, e a vida era a luz dos homens.  E a luz resplandece nas trevas, e as trevas não a receberam.\u003cbr/>\nHouve um homem, enviado por Deus, cujo nome era João.  Ele veio como testemunha, para dar testemunho da Luz,  a fim de que todos cressem por meio dele.\u003cbr/>\nEle não era a Luz, mas veio para dar testemunho da Luz.\u003cbr/>\nEstava no mundo, e o mundo foi feito por Ele, e o mundo não O reconheceu.  Veio para o que era seu, e os seus não O receberam.  Mas a todos quantos O receberam, deu o poder de se tornarem filhos de Deus àqueles que crêem no seu nome;  os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas nasceram de Deus.  E o Verbo fez-se carne \u003cFONT SIZE='1' COLOR=\"red\">genuflecte-se\u003c/FONT> e habitou entre nós;  e nós vimos a sua glória, glória como a do Unigénito do Pai, cheio de graça e de verdade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"},{"label":"Orationes Leonis XIII","la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orationes Leonis XIII\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus et benedíctus fructus ventris tui, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Salve Regína, Mater misericórdiæ, vita, dulcédo, et spes nostra, salve. Ad te clamámus, éxsules fílii Evæ. Ad te suspirámus geméntes et flentes in hac lacrymárum valle. Eia ergo, Advocáta nostra, illos tuos misericórdes óculos ad nos convérte. Et Jesum, benedíctum fructum ventris tui, nobis, post hoc exílium, osténde. O clemens, o pia, o dulcis Virgo Mária.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Ora pro nobis, sancta Dei Génitrix.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Ut digni efficiámur promissiónibus Christi.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Orémus. Deus, refúgium nostrum et virtus, pópulum ad te clamántem propítius réspice; et intercedénte gloriósa, et immaculáta Vírgine Dei Genitríce María, cum beáto Joseph, ejus Sponso, ac beatis Apóstolis tuis Petro et Paulo, et ómnibus Sanctis, quas pro conversióne peccatórum, pro libertáte et exaltatióne sanctæ Matris Ecclésiæ, preces effúndimus, miséricors et benígnus exáudi. Per eúndem Christum Dóminum nostrum. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Sancte Míchaël Archángele, defénde nos in prǽlio; contra nequítiam et insídias diáboli esto præsídium. Imperet illi Deus, súpplices deprecámur: tuque, Princeps milítiæ Cæléstis, sátanam aliósque spíritus malígnos, qui ad perditiónem animárum pervagántur in mundo, divína virtúte in inférnum detrúde. Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Cor Jesu sacratíssimum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Miserére nobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Orações Leoninas\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Dizer de joelhos depois da celebração de Missa rezada:\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Ave, Maria, cheia de graça, o Senhor é convosco; bendita sois Vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Salve, Rainha, mãe de misericórdia, vida, doçura, esperança nossa, salve!  \u003cbr/>\nA Vós bradamos, os degredados filhos de Eva. A Vós suspiramos, gemendo e chorando neste vale de lágrimas.  \u003cbr/>\nEia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei.  \u003cbr/>\nE, depois deste desterro, nos mostrai Jesus, bendito fruto do vosso ventre.  \u003cbr/>\nÓ clemente, ó piedosa, ó doce Virgem Maria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Rogai por nós, Santa Mãe de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>O.\u003c/I>\u003c/FONT> Para que sejamos dignos das promessas de Cristo.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Oremos. Meu Deus, refúgio e fortaleza nossa, atendei propício aos clamores do vosso povo, e,  \u003cbr/>\npela intercessão da gloriosa e imaculada Virgem Maria, Mãe de Deus, do Bem-aventurado S. José, seu esposo,  \u003cbr/>\ndos bem-aventurados Apóstolos S. Pedro e S. Paulo e de todos os Santos,  \u003cbr/>\nouvi benigno e misericordioso as preces que fervorosamente Vos dirigimos  \u003cbr/>\npela conversão dos pecadores e pela exaltação da santa Madre Igreja.  \u003cbr/>\nPelo mesmo Cristo, Nosso Senhor. Amém.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> São Miguel Arcanjo, defendei-nos no combate, sede o nosso auxílio contra a maldade e as ciladas do demónio.  \u003cbr/>\nInstantemente vos pedimos que Deus sobre ele impere; e vós, Príncipe da Milícia Celeste, pelo poder divino,  \u003cbr/>\nprecipitai no inferno a Satanás e aos outros espíritos malignos que vagueiam pelo mundo para perdição das almas.\u003cbr/>\n_\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>P.\u003c/I>\u003c/FONT> Coração sacratíssimo de Jesus:\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>A.\u003c/I>\u003c/FONT> Tende misericórdia de nós.\u003cbr/>\n"}]}]},"2027-11-03":{"date":"2027-11-03","title":"Féria da 24ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria IV infra Hebdomadam IV quæ superfuit post Epiphaniam V. Octobris\tFeria","winner":"Tempora/PentEpi4-3.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos, in tantis perículis constitútos, pro humána scis fragilitáte non posse subsístere: da nobis salútem mentis et córporis; ut ea, quæ pro peccátis nostris pátimur, te adjuvánte vincámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que conheceis não poder a fraqueza humana subsistir no meio de tantos perigos que nos cercam, concedei-nos a saúde da alma e do corpo, a fim de que com vosso auxílio possamos vencer os males que devemos sofrer em castigo dos pecados.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Romános.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Némini quidquam debeátis, nisi ut ínvicem diligátis: qui enim díligit próximum, legem implévit. Nam: Non adulterábis, Non occídes, Non furáberis, Non falsum testimónium dices, Non concupísces: et si quod est áliud mandátum, in hoc verbo instaurátur: Díliges próximum tuum sicut teípsum. Diléctio próximi malum non operátur. Plenitúdo ergo legis est diléctio.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Romanos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Não sejais devedores a ninguém de coisa alguma, senão do amor que deveis uns aos outros; pois aquele que ama o seu próximo cumpre a lei. Com efeito, estes mandamentos de Deus: não cometerás adultério; não matarás; não roubarás; não levantarás falso testemunho; não cobiçarás as coisas alheias, e todos os outros mandamentos que há, resumem-se nestas palavras: amarás ao teu próximo como a ti próprio. O amor ao próximo não permite que se lhe faça mal. O amor é, portanto, a plenitude da lei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 8:23-27\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ascendénte Jesu in navículam, secúti sunt eum discípuli ejus: et ecce, motus magnus factus est in mari, ita ut navícula operirétur flúctibus, ipse vero dormiébat. Et accessérunt ad eum discípuli ejus, et suscitavérunt eum, dicéntes: Dómine, salva nos, perímus. Et dicit eis Jesus: Quid tímidi estis, módicæ fídei? Tunc surgens, imperávit ventis et mari, et facta est tranquíllitas magna. Porro hómines miráti sunt, dicéntes: Qualis est hic, quia venti et mare obœ́diunt ei?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 8:23-27\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus entrou em uma barca, sendo acompanhado pelos seus discípulos. E eis que uma grande tempestade surgiu do mar, de modo que as ondas cobriam a barca. Jesus dormia. Os discípulos aproximaram-se, então, de Jesus, dizendo: «Senhor, salvai-nos, pois perecemos!». Jesus disse-lhes: «Porque receais, homens de pouca fé?». E, erguendo-se, impôs a sua vontade aos ventos e ao mar; e fez-se uma grande bonança. E aqueles homens admiraram-se, dizendo: «Quem é Este, que até os ventos e o mar Lhe obedecem?!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nConcéde, quǽsumus, omnípotens Deus: ut hujus sacrifícii munus oblátum fragilitátem nostram ab omni malo purget semper et múniat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos suplicamos, fazei que a hóstia oferecida neste sacrifício livre a nossa fraqueza de todo o mal e a fortifique para o futuro.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nMúnera tua nos, Deus, a delectatiónibus terrenis expédiant: et cœléstibus semper instáurent aliméntis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que estes vossos dons nos afastem dos gozos terrenos, e nos restaurem com seu alimento celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-04":{"date":"2027-11-04","title":"São Carlos Borromeu, bispo e confessor","forms":[{"number":1,"title":"S. Caroli Episcopi et Confessoris Duplex vide Commune Confessoris Pontificis (Missa Statuit) [Commune/C4.txt]","winner":"Sancti/11-04.txt","rule":"vide C4;\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:1.\u003c/I>\u003c/FONT>\u003cbr/>\nMeménto, Dómine, David: et omnis mansuetúdinis ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:1\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-vos de David, ó Senhor, e da sua grande mansidão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nEcclésiam tuam, Dómine, sancti Caróli Confessóris tui atque Pontíficis contínua protectióne custódi: ut, sicut illum pastorális sollicitúdo gloriósum réddidit; ita nos ejus intercéssio in tuo semper fáciat amóre fervéntes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Mart. Vitalis et Agricolæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, qui sanctórum Mártyrum tuórum Vitális et Agrícolæ sollémnia cólimus, eórum apud te intercessiónibus adjuvémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nEcclésiam tuam, Dómine, sancti Caróli Confessóris tui atque Pontíficis contínua protectióne custódi: ut, sicut illum pastorális sollicitúdo gloriósum réddidit; ita nos ejus intercéssio in tuo semper fáciat amóre fervéntes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santos Mártires Vital e Agrícola\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus omnipotente, Vos rogamos, permiti que, celebrando a festa dos vossos Santos Mártires Vital e Agrícola, sejamos auxiliados pela sua intercessão junto de Vós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16-27; 45, 3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:16-27; 45:3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEis o grande sacerdote, que nos dias da sua vida agradou a Deus e foi julgado justo; e no tempo da ira se tornou a reconciliação dos homens. Ninguém o igualou na observância das leis do Altíssimo. Eis porque o Senhor jurou que o tornaria grande no meio do seu povo. O Senhor abençoou nele todos os povos; e com ele ratificou a sua aliança. O Senhor deu-lhe as suas bênçãos e continuou a dispensar-lhe a sua misericórdia, vendo-se bem que este homem achou graça aos olhos do Senhor, que, por isso mesmo, o engrandeceu diante dos reis e lhe deu uma coroa de glória. Estabeleceu com ele uma aliança eterna, elevou-o ao sumo sacerdócio, e tornou-o feliz na glória para exercer o sacerdócio, louvar o seu nome e oferecer-lhe dignamente incenso de odor agradável.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:20\u003c/I>\u003c/FONT>\u003cbr/>\nNon est invéntus símilis illi, qui conserváret legem Excélsi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 109:4\u003c/I>\u003c/FONT>\u003cbr/>\nTu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:20\u003c/I>\u003c/FONT>\u003cbr/>\nNon est invéntus símilis illi, qui conserváret legem Excélsi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 109:4\u003c/I>\u003c/FONT>\u003cbr/>\nTu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:14-23\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo péregre proficíscens vocávit servos suos, et trádidit illis bona sua. Et uni dedit quinque talénta, álii autem duo, álii vero unum, unicuíque secúndum própriam virtútem, et proféctus est statim. Abiit autem, qui quinque talénta accéperat, et operátus est in eis, et lucrátus est ália quinque. Simíliter et, qui duo accéperat, lucrátus est ália duo. Qui autem unum accéperat, ábiens fodit in terram, et abscóndit pecúniam dómini sui. Post multum vero témporis venit dóminus servórum illórum, et pósuit ratiónem cum eis. Et accédens qui quinque talénta accéperat, óbtulit ália quinque talénta, dicens: Dómine, quinque talénta tradidísti mihi, ecce, ália quinque superlucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui. Accéssit autem et qui duo talénta accéperat, et ait: Dómine, duo talénta tradidísti mihi, ecce, ália duo lucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:14-23\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos esta parábola: Indo um homem viajar para longe, chamou os seus servos e entregou-lhes os bens. A um deu cinco talentos, a outro dois e ao terceiro um. Deu a cada um segundo a sua capacidade; partindo imediatamente. Aquele que havia recebido cinco talentos partiu, e, negociando com este dinheiro, ganhou outros cinco talentos. Semelhantemente, o que recebera dois lucrou outros dois. Mas aquele que havia recebido só um talento foi, cavou a terra e aí ocultou o dinheiro do senhor. Passado muito tempo, veio o senhor daqueles servos e fez contas com eles. Aproximando-se, então, o que recebera cinco talentos, apresentou outros cinco, dizendo: «Senhor, entregastes-me cinco talentos, eis outros cinco, que lucrei». Disse-lhe o seu senhor: «Muito bem, servo bom e fiel: visto que foste fiel em poucas cousas, estabelecer-te-ei acima de muitas cousas: entra no gozo do teu senhor». Aproximando-se também o que recebera dois talentos, disse: «Senhor, entregastes-me dois talentos, eis outros dois que lucrei». E o senhor lhe disse: «Muito bem, servo bom e fiel: visto que foste fiel em poucas cousas, eu te estabelecerei acima de muitas cousas: entra no gozo do teu senhor».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:21-22\u003c/I>\u003c/FONT>\u003cbr/>\nInvéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:21-22\u003c/I>\u003c/FONT>\u003cbr/>\nEncontrei o meu servo David: e ungi-o com meu óleo sagrado: a minha mão o socorrerá e o meu braço o fortalecerá.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Mart. Vitalis et Agricolæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>blátis, quǽsumus, Dómine, placáre munéribus: et, intercedéntibus sanctis Martýribus tuis Vitále et Agrícola, a cunctis nos defénde perículis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue os vossos santos, Senhor, Vos suplicamos, nos alegrem em toda a parte, a fim de que, honrando os seus méritos, sintamos o efeito do seu patrocínio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santos Mártires Vital e Agrícola\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eixai-Vos aplacar com os dons que Vos oferecemos, Senhor, e, por intercessão dos vossos santos Mártires Vital e Agrícola, preservai-nos de todos os perigos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Carólo Confessóre tuo atque Pontífice, benefícia potióra sumámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Mart. Vitalis et Agricolæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc nos commúnio, Dómine, purget a crímine: et, intercedéntibus sanctis Martýribus tuis Vitále et Agrícola, coeléstis remédii fáciat esse consórtes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDignai-Vos permitir, ó Deus omnipotente, que, dando-Vos nós graças pelos benefícios recebidos, alcancemos por intercessão do B. Carlos, vosso Confessor e Pontífice, ainda outros maiores.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santos Mártires Vital e Agrícola\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue esta comunhão nos purifique dos nossos crimes, Senhor, e que por intercessão dos vossos santos Mártires Vital e Agrícola nos faça participantes do remédio celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-05":{"date":"2027-11-05","title":"Féria da 24ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria VI infra Hebdomadam IV quæ superfuit post Epiphaniam V. Octobris\tFeria","winner":"Tempora/PentEpi4-5.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos, in tantis perículis constitútos, pro humána scis fragilitáte non posse subsístere: da nobis salútem mentis et córporis; ut ea, quæ pro peccátis nostris pátimur, te adjuvánte vincámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que conheceis não poder a fraqueza humana subsistir no meio de tantos perigos que nos cercam, concedei-nos a saúde da alma e do corpo, a fim de que com vosso auxílio possamos vencer os males que devemos sofrer em castigo dos pecados.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Romános.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Némini quidquam debeátis, nisi ut ínvicem diligátis: qui enim díligit próximum, legem implévit. Nam: Non adulterábis, Non occídes, Non furáberis, Non falsum testimónium dices, Non concupísces: et si quod est áliud mandátum, in hoc verbo instaurátur: Díliges próximum tuum sicut teípsum. Diléctio próximi malum non operátur. Plenitúdo ergo legis est diléctio.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Romanos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:8-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Não sejais devedores a ninguém de coisa alguma, senão do amor que deveis uns aos outros; pois aquele que ama o seu próximo cumpre a lei. Com efeito, estes mandamentos de Deus: não cometerás adultério; não matarás; não roubarás; não levantarás falso testemunho; não cobiçarás as coisas alheias, e todos os outros mandamentos que há, resumem-se nestas palavras: amarás ao teu próximo como a ti próprio. O amor ao próximo não permite que se lhe faça mal. O amor é, portanto, a plenitude da lei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 8:23-27\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ascendénte Jesu in navículam, secúti sunt eum discípuli ejus: et ecce, motus magnus factus est in mari, ita ut navícula operirétur flúctibus, ipse vero dormiébat. Et accessérunt ad eum discípuli ejus, et suscitavérunt eum, dicéntes: Dómine, salva nos, perímus. Et dicit eis Jesus: Quid tímidi estis, módicæ fídei? Tunc surgens, imperávit ventis et mari, et facta est tranquíllitas magna. Porro hómines miráti sunt, dicéntes: Qualis est hic, quia venti et mare obœ́diunt ei?\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 8:23-27\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus entrou em uma barca, sendo acompanhado pelos seus discípulos. E eis que uma grande tempestade surgiu do mar, de modo que as ondas cobriam a barca. Jesus dormia. Os discípulos aproximaram-se, então, de Jesus, dizendo: «Senhor, salvai-nos, pois perecemos!». Jesus disse-lhes: «Porque receais, homens de pouca fé?». E, erguendo-se, impôs a sua vontade aos ventos e ao mar; e fez-se uma grande bonança. E aqueles homens admiraram-se, dizendo: «Quem é Este, que até os ventos e o mar Lhe obedecem?!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nConcéde, quǽsumus, omnípotens Deus: ut hujus sacrifícii munus oblátum fragilitátem nostram ab omni malo purget semper et múniat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos suplicamos, fazei que a hóstia oferecida neste sacrifício livre a nossa fraqueza de todo o mal e a fortifique para o futuro.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nMúnera tua nos, Deus, a delectatiónibus terrenis expédiant: et cœléstibus semper instáurent aliméntis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que estes vossos dons nos afastem dos gozos terrenos, e nos restaurem com seu alimento celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-06":{"date":"2027-11-06","title":"Ofício de Nossa Senhora no sábado","forms":[{"number":1,"title":"Sanctæ Mariæ Sabbato\tSimplex vide  [Commune/C10c.txt]","winner":"Commune/C10c.txt","rule":"vide C10\nSpecial Benedictio\nSpecial Lectio 3\nDoxology=Nat\nAntiphonas horas\nGloria\nSuffr=Spiritu;Ecclesiæ,Papa;;\nPrefatio=Maria=veneratione;\n\nex C10c","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei aos vossos servos, Senhor Deus, Vos suplicamos, o gozo da perpétua saúde da alma e do corpo, e que pela gloriosa intercessão da B. Maria, sempre Virgem, sejamos livres das tristezas dos tempos presentes e alcancemos o gozo da eterna alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nAb inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nFui criada desde o princípio, antes de todos os séculos, e não deixarei de existir até à eternidade. Exerci perante Ele o meu ministério; e deste modo tenho habitação fixa em Sião. Ele deixa-me descansar na cidade santa e tenho poder em Jerusalém. Arraiguei-me em um povo glorioso, da parte do meu Deus e da sua herança, e permaneço na companhia dos santos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Num 17:8\u003c/I>\u003c/FONT>\u003cbr/>\nVirga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois, ó Virgem Maria, que fostes Mãe do Salvador sem que a vossa pureza sofresse a mais leve ofensa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem, Mãe de Deus, Aquele que nem todo o universo é capaz de conter, esteve encerrado, quando se fez homem, no vosso seio. Alleluia, alleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Num 17:8\u003c/I>\u003c/FONT>\u003cbr/>\nA vara de Jessé floresceu: a Virgem deu à luz do mundo o Homem-Deus: restabeleceu Deus a paz, conciliando na sua pessoa a nossa baixeza com sua suprema grandeza! Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nFelix namque es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSois feliz e digna de todos os louvores, ó Santa Virgem Maria, pois de vós nasceu «o sol da justiça», Cristo, Nosso Senhor.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oblação nos assegure a prosperidade e a paz, agora e sempre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in veneratione beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da Virgem Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós, Senhor, alcançado o poderoso auxílio da nossa salvação, concedei-nos, Vos imploramos, que sejamos protegidos com o patrocínio da B. Maria, sempre Virgem, em cuja honra oferecemos à vossa majestade este sacrifício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-07":{"date":"2027-11-07","title":"V Domingo depois da Epifania retomado depois de Pentecostes","forms":[{"number":1,"title":"Dominica V quæ superfuit Post Epiphaniam III. Novembris\tSemiduplex","winner":"Tempora/PentEpi5-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFamíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut, quæ in sola spe grátiæ cœléstis innítitur, tua semper protectióne muniátur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, dignai-Vos revestir a vossa família com vossa perpétua misericórdia, e, como ela não possui outra esperança senão a da vossa celestial graça, permiti que esteja sempre munida com vossa protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Colossénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 3:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Indúite vos sicut elécti Dei, sancti et dilécti, víscera misericórdiæ, benignitátem, humilitátem, modéstiam, patiéntiam: supportántes ínvicem, et donántes vobismetípsis, si quis advérsus áliquem habet querélam: sicut et Dóminus donávit vobis, ita et vos. Super ómnia autem hæc caritátem habéte, quod est vínculum perfectiónis: et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore: et grati estóte. Verbum Christi hábitet in vobis abundánter, in omni sapiéntia, docéntes et commonéntes vosmetípsos psalmis, hymnis et cánticis spirituálibus, in grátia cantántes in córdibus vestris Deo. Omne, quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per Jesum Christum, Dóminum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Colossenses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 3:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Como escolhidos de Deus, que sois, santos e amados, revesti-vos de sentimentos íntimos de misericórdia, de bondade, de humildade, de modéstia e de paciência, suportando-vos uns aos outros e perdoando-vos reciprocamente, se porventura algum tem motivos de queixa contra o outro. Assim como o Senhor nos perdoou, assim também devemos perdoar uns aos outros. Acima de tudo, tende caridade; pois esta é o vínculo da perfeição. Que a paz de Cristo, à qual também fostes chamados para formar um só corpo, reine nos vossos corações. Sede reconhecidos! Que a palavra de Cristo permaneça profundamente em vós, ensinando-vos e admoestando-vos com toda sua sabedoria por meio dos Salmos, Hinos e Cânticos espirituais, louvando a Deus nos vossos corações com cânticos. Tudo o que fizerdes, seja em palavras, seja em obras, fazei-o em nome de Nosso Senhor Jesus Cristo, dando graças por Ele a Deus Pai.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:24-30\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis parábolam hanc: Símile factum est regnum cœlórum hómini, qui seminávit bonum semen in agro suo. Cum autem dormírent hómines, venit inimícus ejus, et superseminávit zizánia in médio trítici, et ábiit. Cum autem crevísset herba et fructum fecísset, tunc apparuérunt et zizánia. Accedéntes autem servi patrisfamílias, dixérunt ei: Dómine, nonne bonum semen seminásti in agro tuo? Unde ergo habet zizánia? Et ait illis: Inimícus homo hoc fecit. Servi autem dixérunt ei: Vis, imus, et collígimus ea? Et ait: Non: ne forte colligéntes zizánia eradicétis simul cum eis et tríticum. Sínite utráque créscere usque ad messem, et in témpore messis dicam messóribus: Collígite primum zizánia, et alligáte ea in fascículos ad comburéndum, tríticum autem congregáte in hórreum meum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:24-30\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas: O reino dos céus é semelhante a um homem que havia semeado boa semente no seu campo; mas, enquanto os homens dormiam, veio o seu inimigo; semeou joio entre o trigo e se retirou. Havendo crescido a erva, deu fruto e apareceu também o joio. Então aproximaram-se os servos do pai de família, e disseram-lhe: «Por ventura não semeastes boa semente neste vosso campo? Donde lhe veio, pois, o joio?». Ele disse: «Foi o homem inimigo quem fez isto». Os servos retorquiram-lhe: «Quereis que vamos e colhamos o joio?». Ele disse: «Não, pois receio que, arrancando o joio, arranqueis também o trigo. Deixai crescer ambos até ao tempo da ceifa; e, então, direi aos ceifeiros: colhei primeiramente o joio e atai-o em molhos para serem queimados; e arrecadai o trigo no meu celeiro».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias tibi, Dómine, placatiónis offérimus: ut et delícta nostra miserátus absólvas, et nutántia corda tu dírigas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos oferecemos, Senhor, estas hóstias de propiciação, a fim de que misericordiosamente perdoeis os nossos pecados e ampareis os nossos corações inconstantes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut illíus salutáris capiámus efféctum, cujus per hæc mystéria pignus accépimus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos suplicamos, ó Deus omnipotente, fazei que obtenhamos o efeito da salvação eterna, da qual, nestes sagrados mystérios, já recebemos o penhor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-08":{"date":"2027-11-08","title":"Féria da 25ª semana depois de Pentecostes","forms":[{"number":1,"title":"Feria II infra Hebdomadam V quæ superfuit post Epiphaniam III. Novembris\tFeria","winner":"Tempora/PentEpi5-1.txt","rule":"Oratio Dominica\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nFamíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut, quæ in sola spe grátiæ cœléstis innítitur, tua semper protectióne muniátur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Quatuor Coronatorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, qui gloriósos Mártyres fortes in sua confessióne cognóvimus, pios apud te in nostra intercessióne sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, dignai-Vos revestir a vossa família com vossa perpétua misericórdia, e, como ela não possui outra esperança senão a da vossa celestial graça, permiti que esteja sempre munida com vossa protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Os Quatro S. S. Mártires Coroados\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>econhecendo nós, ó Deus omnipotente, a fortaleza dos vossos gloriosos Mártires na confissão da fé, fazei, Vos suplicamos, que sintamos junto de Vós a sua pia intercessão em nosso favor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Colossénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 3:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Indúite vos sicut elécti Dei, sancti et dilécti, víscera misericórdiæ, benignitátem, humilitátem, modéstiam, patiéntiam: supportántes ínvicem, et donántes vobismetípsis, si quis advérsus áliquem habet querélam: sicut et Dóminus donávit vobis, ita et vos. Super ómnia autem hæc caritátem habéte, quod est vínculum perfectiónis: et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore: et grati estóte. Verbum Christi hábitet in vobis abundánter, in omni sapiéntia, docéntes et commonéntes vosmetípsos psalmis, hymnis et cánticis spirituálibus, in grátia cantántes in córdibus vestris Deo. Omne, quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per Jesum Christum, Dóminum nostrum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Colossenses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 3:12-17\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Como escolhidos de Deus, que sois, santos e amados, revesti-vos de sentimentos íntimos de misericórdia, de bondade, de humildade, de modéstia e de paciência, suportando-vos uns aos outros e perdoando-vos reciprocamente, se porventura algum tem motivos de queixa contra o outro. Assim como o Senhor nos perdoou, assim também devemos perdoar uns aos outros. Acima de tudo, tende caridade; pois esta é o vínculo da perfeição. Que a paz de Cristo, à qual também fostes chamados para formar um só corpo, reine nos vossos corações. Sede reconhecidos! Que a palavra de Cristo permaneça profundamente em vós, ensinando-vos e admoestando-vos com toda sua sabedoria por meio dos Salmos, Hinos e Cânticos espirituais, louvando a Deus nos vossos corações com cânticos. Tudo o que fizerdes, seja em palavras, seja em obras, fazei-o em nome de Nosso Senhor Jesus Cristo, dando graças por Ele a Deus Pai.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:24-30\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis parábolam hanc: Símile factum est regnum cœlórum hómini, qui seminávit bonum semen in agro suo. Cum autem dormírent hómines, venit inimícus ejus, et superseminávit zizánia in médio trítici, et ábiit. Cum autem crevísset herba et fructum fecísset, tunc apparuérunt et zizánia. Accedéntes autem servi patrisfamílias, dixérunt ei: Dómine, nonne bonum semen seminásti in agro tuo? Unde ergo habet zizánia? Et ait illis: Inimícus homo hoc fecit. Servi autem dixérunt ei: Vis, imus, et collígimus ea? Et ait: Non: ne forte colligéntes zizánia eradicétis simul cum eis et tríticum. Sínite utráque créscere usque ad messem, et in témpore messis dicam messóribus: Collígite primum zizánia, et alligáte ea in fascículos ad comburéndum, tríticum autem congregáte in hórreum meum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:24-30\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus às turbas: O reino dos céus é semelhante a um homem que havia semeado boa semente no seu campo; mas, enquanto os homens dormiam, veio o seu inimigo; semeou joio entre o trigo e se retirou. Havendo crescido a erva, deu fruto e apareceu também o joio. Então aproximaram-se os servos do pai de família, e disseram-lhe: «Por ventura não semeastes boa semente neste vosso campo? Donde lhe veio, pois, o joio?». Ele disse: «Foi o homem inimigo quem fez isto». Os servos retorquiram-lhe: «Quereis que vamos e colhamos o joio?». Ele disse: «Não, pois receio que, arrancando o joio, arranqueis também o trigo. Deixai crescer ambos até ao tempo da ceifa; e, então, direi aos ceifeiros: colhei primeiramente o joio e atai-o em molhos para serem queimados; e arrecadai o trigo no meu celeiro».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHóstias tibi, Dómine, placatiónis offérimus: ut et delícta nostra miserátus absólvas, et nutántia corda tu dírigas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Quatuor Coronatorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>B\u003c/I>\u003c/B>\u003c/FONT>enedíctio tua, Dómine, larga descéndat: quæ et múnera nostra, deprecántibus sanctis Martýribus tuis, tibi reddat accépta, et nobis sacraméntum redemptiónis effíciat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nVos oferecemos, Senhor, estas hóstias de propiciação, a fim de que misericordiosamente perdoeis os nossos pecados e ampareis os nossos corações inconstantes.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Os Quatro S. S. Mártires Coroados\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue a vossa bênção, Senhor, desça magnanimamente sobre nós; e que pelas preces dos vossos Santos Mártires Vos sejam agradáveis as nossas ofertas, mudando-as em nosso favor em sacramento de redenção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut illíus salutáris capiámus efféctum, cujus per hæc mystéria pignus accépimus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Quatuor Coronatorum Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>œléstibus refécti sacraméntis et gáudiis: súpplices te, Dómine, deprecámur; ut, quorum gloriámur triúmphis, protegámur auxíliis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos suplicamos, ó Deus omnipotente, fazei que obtenhamos o efeito da salvação eterna, da qual, nestes sagrados mystérios, já recebemos o penhor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Os Quatro S. S. Mártires Coroados\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>lentados com os sacramentos e as delícias celestiais, Vos suplicamos humildemente, Senhor, que sejamos protegidos com os auxílios daqueles de cujo triunfo nos gloriamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-09":{"date":"2027-11-09","title":"Dedicação da Basílica do Latrão","forms":[{"number":1,"title":"In Dedicatione Basilicæ Ss. Salvatoris Duplex 2nd class ex Commune Dedicationis Ecclesiae [Commune/C8.txt]","winner":"Sancti/11-09.txt","rule":"ex C8;\nFestum Domini\nGloria\nCredo\nPrefatio=Dedicatio\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gen 28:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>erríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuam dilécta tabernácula tua, Dómine virtútum! Concupíscit, et déficit ánima mea in átria Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>erríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gn 28:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue terrível é este lugar! É verdadeiramente a casa de Deus e a porta do céu: e será chamado o palácio de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuão dilectos são os vossos tabernáculos, ó Senhor dos exércitos! Minha alma suspira com ardor e em êxtase, em desejos de viver junto dos átrios do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue terrível é este lugar! É verdadeiramente a casa de Deus e a porta do céu: e será chamado o palácio de Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>In Anniversario Dedicationis Ecclesiæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nobis per síngulos annos hujus sancti templi tui consecratiónis réparas diem, et sacris semper mystériis repræséntas incólumes: exáudi preces pópuli tui, et præsta; ut quisquis hoc templum benefícia petitúrus ingréditur, cuncta se impetrásse lætétur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Theodori Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos beáti Theodóri Mártyris tui confessióne gloriósa circúmdas et prótegis: præsta nobis ex ejus imitatióne profícere, et oratióne fulcíri.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que, anualmente, renovais em nosso favor o dia da consagração deste santo Templo e nos conservais incólumes para podermos sempre celebrar estes sagrados mystérios, ouvi as orações do vosso povo e concedei a todos aqueles que entrarem neste templo, para pedir as vossas graças, a alegria de as alcançarem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Teodoro\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos guardais e protegeis pela gloriosa confissão do B. Teodoro, vosso Mártir, concedei-nos a graça de aproveitarmos com seus exemplos e de sermos auxiliados com suas orações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Apocalýpsis beáti Joánnis Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 21:2-5\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Vidi sanctam civitátem Jerúsalem novam descendéntem de cœlo a Deo, parátam sicut sponsam ornátam viro suo. Et audívi vocem magnam de throno dicéntem: Ecce tabernáculum Dei cum homínibus, et habitábit cum eis. Et ipsi pópulus ejus erunt, et ipse Deus cum eis erit eórum Deus: et abstérget Deus omnem lácrimam ab óculis eórum: et mors ultra non erit, neque luctus neque clamor neque dolor erit ultra, quia prima abiérunt. Et dixit, qui sedébat in throno: Ecce, nova fácio ómnia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro do Apocalipse do B. Ap.º S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 21:2-5\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, vi a cidade santa, a nova Jerusalém, que vinha de Deus e descia do céu, ornada como uma esposa que se prepara para receber o esposo. E ouvi uma voz forte, que falava do trono, e dizia: «Eis aqui o tabernáculo de Deus no meio dos homens. O Senhor habitará com eles, que serão o seu povo; e o próprio Deus permanecerá com eles e será o seu Deus, enxugando-lhes todas as lágrimas dos seus olhos. Então já não existirão nem a morte, nem as lágrimas, nem os clamores, nem as dores, porque o primeiro estado das cousas terá acabado». E aquele que estava sentado no trono disse: «Eu vou renovar todas as cousas!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLocus iste a Deo factus est, inæstimábile sacraméntum, irreprehensíbilis est.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Deus, cui astat Angelórum chorus, exáudi preces servórum tuórum. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 137:2\u003c/I>\u003c/FONT>\u003cbr/>\nAdorábo ad templum sanctum tuum: et confitébor nómini tuo. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nEste lugar foi feito por Deus: ele é um mystério inapreciável e isento de qualquer defeito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Deus, diante de Quem se prostram os caros dos Anjos, ouvi as preces dos vossos servos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 137:2\u003c/I>\u003c/FONT>\u003cbr/>\nAdorar-Vos-ei no vosso santo Templo e louvarei o vosso santo Nome. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 19:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ingréssus Jesus perambulábat Jéricho. Et ecce, vir nómine Zachǽus: et hic princeps erat publicanórum, et ipse dives: et quærébat vidére Jesum, quis esset: et non póterat præ turba, quia statúra pusíllus erat. Et præcúrrens ascéndit in árborem sycómorum, ut vidéret eum; quia inde erat transitúrus. Et cum venísset ad locum, suspíciens Jesus vidit illum, et dixit ad eum: Zachǽe, festínans descénde; quia hódie in domo tua opórtet me manére. Et festínans descéndit, et excépit illum gaudens. Et cum vidérent omnes, murmurábant, dicéntes, quod ad hóminem peccatórem divertísset. Stans autem Zachǽus, dixit ad Dóminum: Ecce, dimídium bonórum meórum, Dómine, do paupéribus: et si quid áliquem defraudávi, reddo quádruplum. Ait Jesus ad eum: Quia hódie salus dómui huic facta est: eo quod et ipse fílius sit Abrahæ. Venit enim Fílius hóminis quǽrere et salvum fácere, quod períerat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 19:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, havendo Jesus entrado em Jericó, atravessava a cidade. Ora, havia ali um homem, chamado Zaqueu, príncipe dos publicanos e muito rico, que procurava ver Jesus para o conhecer; mas o não conseguia por causa das turbas do povo, pois ele era de baixa estatura. Correu, pois, adiante e subiu para um sicómoro, para ver Jesus, que devia passar por aquele lugar. Chegando Jesus ali, ergueu os olhos e, vendo-o, disse-lhe: «Zaqueu, descei depressa, porque me convém hospedar-me hoje em vossa casa». Imediatamente Zaqueu desceu e recebeu Jesus com alegria. Vendo as pessoas isto, começaram a murmurar, dizendo que Jesus ia hospedar-se em casa de um pecador. Entretanto Zaqueu estava perante o Senhor e dizia-Lhe: «Senhor, eis que vou dar metade dos meus bens aos pobres; e, se defraudei alguém, restituirei o quádruplo». Jesus disse então: «Esta casa recebeu hoje a salvação, pois este também é filho de Abraão. O Filho do homem veio para procurar e salvar o que estava perdido!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Par 29:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nDómine Deus, in simplicitáte cordis mei lætus óbtuli univérsa; et pópulum tuum, qui repértus est, vidi cum ingénti gáudio: Deus Israël, custódi hanc voluntátem, allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cr 29:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, meu Deus, foi com simplicidade de coração e com alegria que Vos oferecer todas as cousas: foi com intenso júbilo que vi reunido o vosso povo. Ó Deus de Israel, conservai em minha alma estas boas disposições. Aleluia.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAnnue, quǽsumus, Dómine, précibus nostris: ut, dum hæc vota præséntia réddimus, ad ætérna præmia, te adjuvánte, perveníre mereámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Theodori Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úscipe, Dómine, fidélium preces cum oblatiónibus hostiárum: et, intercedénte beáto Theodóro Mártyre tuo, per hæc piæ devotiónis offícia ad cœléstem glóriam transeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos, Senhor, ouvir as nossas orações de modo que todos os que nos encontramos neste santo Templo, de cuja Dedicação celebramos o aniversário, Vos agradecemos com a oferta inteira e perfeita, que Vos fazemos, do nosso corpo e da nossa alma; e permiti que, oferecendo-Vos estes dons, alcancemos a felicidade eterna com vosso auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Teodoro\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei, Senhor, as preces dos fiéis juntamente com a oblata destas hóstias, a fim de que, pela intercessão do B. Teodoro, vosso Mártir, obtenhamos, em virtude destes mystérios de pia devoção, a graça de sermos conduzidos até à glória celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>in Dedicatione Ecclesiae\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Qui hanc oratiónis domum, quam ædificávimus, bonórum ómnium largítor inhábitas, et Ecclésiam, quam ipse fundásti, incessábili operatióne sanctíficas. Hæc est enim vere domus oratiónis, visibílibus ædifíciis adumbráta, templum habitatiónis glóriæ tuæ, sedes incommutábilis veritátis, sanctuárium ætérnæ caritátis. Hæc est arca, qui nos a mundi eréptos dilúvio, in portu salútis indúcit. Hæc est dilécta et única sponsa, quam acquisívit Christus sánguine suo, quam vivíficat Spíritu suo, cujus in sinu renáti per grátiam tuam, lacte verbi páscimur, pane vitæ roborámur, misericórdiæ tuæ subsídiis confovémur. Hæc fidéliter in terris, Sponso adiuvánte, mílitat, et perénniter in cælis, ipso coronánte, triúmphat. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dedicação de Igreja (Prefácio Comum)\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 21:13\u003c/I>\u003c/FONT>\u003cbr/>\nDomus mea domus oratiónis vocábitur, dicit Dóminus: in ea omnis, qui petit, áccipit; et qui quærit, invénit; et pulsánti aperiétur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 21:13\u003c/I>\u003c/FONT>\u003cbr/>\nA minha casa será chamada casa de oração, diz o Senhor: e todo aquele que aí pede, recebe: e o que procura, acha: e ao que bate, abrir-se-lhe-á.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui de vivis et electis lapídibus ætérnum majestáti tuæ prǽparas habitáculum: auxiliáre pópulo tuo supplicánti; ut, quod Ecclésiæ tuæ corporálibus próficit spátiis, spirituálibus amplificétur augméntis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Theodori Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta nobis, quǽsumus, Dómine: intercedénte beáto Theodóro Mártyre tuo; ut, quod ore contíngimus, pura mente capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>No dia da dedicação\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignai-Vos conceder-nos, ó Deus omnipotente, que neste lugar, que, ainda que indignos, dedicámos ao vosso nome, ouçais benignamente todos os que Vos implorarem.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Teodoro\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, Senhor, pela intercessão do B. Teodoro, vosso Mártir, que conservemos com o coração puro o sacramento que a nossa boca recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-10":{"date":"2027-11-10","title":"Santo André Avelino, confessor","forms":[{"number":1,"title":"S. Andreæ Avellini Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Os justi) [Commune/C5.txt]","winner":"Sancti/11-10.txt","rule":"vide C5;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui in corde beáti Andréæ Confessóris tui, per árduum cotídie in virtútibus proficiéndi votum, admirábiles ad te ascensiónes disposuísti: concéde nobis, ipsíus méritis et intercessióne, ita ejúsdem grátiæ partícipes fieri; ut, perfectióra semper exsequéntes, ad glóriæ tuæ fastígium felíciter perducámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tryphonis, Respicii, et Nymphæ Virg., Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>ac nos, quǽsumus, Dómine, sanctórum Mártyrum tuórum Tryphónis, Respícii et Nymphæ semper festa sectári: quorum suffrágiis, protectiónis tuæ dona sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que, inspirando ao B. André, vosso Confessor, o voto heróico de progredir quotidianamente na virtude, dispusestes a sua alma em admiráveis ascensões na perfeição, concedei-nos pelos seus méritos e intercessão que compartilhemos desta graça, de sorte que, aspirando sempre ao que é mais perfeito, cheguemos com alegria ao cume da vossa glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. S. Mártires Trifão, Respício e Ninfa\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, Senhor, Vos suplicamos, que celebremos sempre a solenidade dos vossos Santos Mártires Trifão, Respício e Ninfa, a fim de que, mercê dos seus auxílios, alcancemos os benefícios da vossa protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ecl 31:8-11\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o homem que foi julgado sem mácula; que não correu após o ouro; e não pôs as esperanças nem no dinheiro, nem nos tesouros! Quem é ele, para que o louvemos? Porquanto operou cousas admiráveis durante a vida. Aquele que foi provado pelo ouro e foi julgado perfeito alcançará a glória eterna; pois poderia ter violado o mandamento, e o não violou; poderia ter praticado acções más, e as não praticou. É por esta razão que seus bens lhe estarão assegurados no Senhor e que toda a assembleia dos justos proclamará as boas acções que praticou.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nAd annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ja 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 91:13; 91:14\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano, na casa do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:3\u003c/I>\u003c/FONT>\u003cbr/>\nPara publicar de manhã a vossa misericórdia; e de noite a vossa verdade. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Tg 1:12\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que sabe sofrer a tentação, porque, quando acabar a tentação, receberá a coroa da vida. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:35-40\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Estejam cingidos os vossos rins; tende nas vossas mãos lâmpadas acesas; sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para que, quando chegar e bater à porta, logo lha abram. Bem-aventurados aqueles servos que seu senhor, quando chegar, os achar vigilantes. Em verdade vos digo que se cingirá, e, mandando-os sentar à mesa, passará por entre eles e os servirá. E, se chegar na segunda ou terceira vigília e assim os achar, bem-aventurados são esses servos. Ora, sabei que, se o pai de família conhecesse a hora em que viria o ladrão, vigiava, sem dúvida, para que sua casa não fosse assaltada. Vós, pois, estai preparados, porque o Filho do homem virá à hora em que menos cuidais».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele: e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLaudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tryphonis, Respicii, et Nymphæ Virg., Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>únera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nA Vós, Senhor, imolamos esta víctimas de louvor em memória de vossos Santos, esperando ser livres por sua intercessão de todos os males presentes e futuros.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. S. Mártires Trifão, Respício e Ninfa\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>os oferecemos, Senhor, estes dons da nossa devoção; e, em atenção aos merecimentos dos vossos justos, dignai-Vos aceitá-los, e pela vossa misericórdia fazei que nos sejam salutares.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que o Senhor, quando vier, achar vigilante. Em verdade vos digo que lhe dará a administração de todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Ss. Tryphonis, Respicii, et Nymphæ Virg., Martyrum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Tryphóne, Respício et Nympha; ut, quod ore contíngimus, pura mente capiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPelos celestes alimentos recebidos, nós Vos rogamos e suplicamos, ó Senhor, nosso Deus, que nos seja concedido o auxílio das orações daquele Santo em cuja festa os recebemos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. S. Mártires Trifão, Respício e Ninfa\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, por intercessão dos vossos santos Mártires Tryphóne, Respício et Nympha, dignai-Vos conceder-nos a graça de guardarmos com o coração sempre puro o que a nossa boca agora recebeu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-11":{"date":"2027-11-11","title":"São Martinho de Tours, bispo e confessor","forms":[{"number":1,"title":"S. Martini Episcopi et Confessoris Duplex vide Commune Confessoris Pontificis (Missa Statuit) [Commune/C4.txt]","winner":"Sancti/11-11.txt","rule":"vide C4;\n9 lectiones\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:1.\u003c/I>\u003c/FONT>\u003cbr/>\nMeménto, Dómine, David: et omnis mansuetúdinis ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:1\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-vos de David, ó Senhor, e da sua grande mansidão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui cónspicis, quia ex nulla nostra virtúte subsístimus: concéde propítius; ut, intercessióne beáti Martíni Confessóris tui atque Pontíficis, contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Mennæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, qui beáti Mennæ Mártyris tui natalítia cólimus, intercessióne ejus in tui nóminis amóre roborémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que bem conheceis que não é pelo nosso poder que subsistimos, concedei-nos propício que, pela intercessão do B. Martinho, vosso Confessor e Pontífice, sejamos protegidos contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Mena\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus omnipotente, permiti que, celebrando nós o nascimento do B. Mena, vosso Mártir, e pela sua intercessão, alcancemos a graça de sermos confirmados no amor ao vosso Nome.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16-27; 45, 3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:16-27; 45:3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEis o grande sacerdote, que nos dias da sua vida agradou a Deus e foi julgado justo; e no tempo da ira se tornou a reconciliação dos homens. Ninguém o igualou na observância das leis do Altíssimo. Eis porque o Senhor jurou que o tornaria grande no meio do seu povo. O Senhor abençoou nele todos os povos; e com ele ratificou a sua aliança. O Senhor deu-lhe as suas bênçãos e continuou a dispensar-lhe a sua misericórdia, vendo-se bem que este homem achou graça aos olhos do Senhor, que, por isso mesmo, o engrandeceu diante dos reis e lhe deu uma coroa de glória. Estabeleceu com ele uma aliança eterna, elevou-o ao sumo sacerdócio, e tornou-o feliz na glória para exercer o sacerdócio, louvar o seu nome e oferecer-lhe dignamente incenso de odor agradável.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:20\u003c/I>\u003c/FONT>\u003cbr/>\nNon est invéntus símilis illi, qui conserváret legem Excélsi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Beátus vir, sanctus Martínus, urbis Turónis Epíscopus, requiévit: quem suscéperunt Angeli atque Archángeli, Throni, Dominatiónes et Virtútes. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEis o grande sacerdote que nos dias da sua vida agradou a Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:20\u003c/I>\u003c/FONT>\u003cbr/>\nNinguém o igualou na observância das leis do Altíssimo. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O bem-aventurado varão Martinho, Bispo de Tours, dormiu no Senhor: e os Anjos, os Arcanjos, os Tronos, as Dominações e as Virtudes o acolheram. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:33-36\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nemo lucérnam accéndit, et in abscóndito ponit, neque sub módio: sed supra candelábrum, ut, qui ingrediúntur, lumen vídeant. Lucérna córporis tui est óculus tuus. Si óculus tuus fúerit simplex, totum corpus tuum lúcidum erit: si autem nequam fúerit, étiam corpus tuum tenebrósum erit. Vide ergo, ne lumen, quod in te est, ténebræ sint. Si ergo corpus tuum totum lúcidum fúerit, non habens áliquam partem tenebrárum, erit lúcidum totum, et sicut lucérna fulgóris illuminábit te.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:33-36\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Ninguém acende uma lâmpada para a colocar num lugar oculto ou sob um alqueire; mas coloca-a sobre o candelabro, para que aqueles que entrarem vejam a luz. A lâmpada do teu corpo é o teu olho. Se o teu olho for simples, todo teu corpo será luminoso; mas se ele for mau, também o teu corpo será tenebroso. Tem, pois, cuidado de que a luz, que está em ti, não se torne em trevas. Se, portanto, todo teu corpo for luminoso sem parte alguma nas trevas, será ele brilhante, como quando uma lâmpada te ilumina com seu brilho».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nVéritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:25\u003c/I>\u003c/FONT>\u003cbr/>\nA minha fidelidade e a minha misericórdia estarão com ele; e o seu poder elevar-se-á pelo meu nome.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSanctífica, quǽsumus, Dómine Deus, hæc múnera, quæ in sollemnitáte sancti Antístitis tui Martíni offérimus: ut per ea vita nostra inter advérsa et próspera ubíque dirigátur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Mennæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>unéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Senhor e Deus, santificai, Vos rogamos, estes dons que Vos oferecemos na solenidade do Santo Bispo Martinho, vosso Mártir, a fim de que, graças a eles, a nossa vida se regule segundo a vossa vontade, tanto nas adversidades, como nas prosperidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Mena\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>avendo Vós, Senhor, aceitado as nossas ofertas e orações, dignai-Vos purificar-nos com vossos celestiais mystérios e ouvir-nos benignamente.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 24:46-47\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o servo que, quando o Senhor vier, encontrar vigilante. Em verdade vos digo que o encarregará de administrar todos seus bens.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, Dómine, Deus noster: ut, quorum festivitáte votíva sunt sacraménta, eórum intercessióne salutária nobis reddántur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Mennæ Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a, quǽsumus, Dómine, Deus noster: ut, sicut tuórum commemoratióne Sanctórum temporáli gratulámur offício; ita perpétuo lætémur aspéctu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nFazei, Senhor, nosso Deus, que nos sejam salutares estes sacrossantos sacramentos, pela intercessão daqueles em cuja festa Vo-los apresentamos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Mena\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, ó Senhor, nosso Deus, Vos suplicamos, que, assim como nos alegramos, comemorando nesta vida pelo nosso ministério a memória dos vossos Santos, assim também tenhamos a felicidade de os contemplar na eternidade.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-12":{"date":"2027-11-12","title":"São Martinho I, papa e mártir","forms":[{"number":1,"title":"S. Martini Papæ et Martyris Semiduplex vide Commune Unius Martyris Summi Pontificis (Missa Si diligis) [Commune/C2b-1.txt]","winner":"Sancti/11-12.txt","rule":"vide C2b-1;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Joann 21:15-17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i díligis me, Simon Petre, pasce agnos meos, pasce oves meas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 29:2\u003c/I>\u003c/FONT>\u003cbr/>\nExaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>i díligis me, Simon Petre, pasce agnos meos, pasce oves meas.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jo 21:15-17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e me amas, Simão-Pedro, apascenta os meus cordeiros, apascenta as minhas ovelhas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 29:2\u003c/I>\u003c/FONT>\u003cbr/>\nLouvar-Vos-ei, Senhor, pois me acolhestes e não permitistes que meus inimigos se rissem de mim.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>e me amas, Simão-Pedro, apascenta os meus cordeiros, apascenta as minhas ovelhas.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nGregem tuum, Pastor ætérne, placátus inténde: et, per beátum Martínum Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Martinho Vosso Mártir e Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Petri Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Pet 5:1-4; 5:10-11\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimi: Senióres, qui in vobis sunt, obsécro consénior et testis Christi passiónum, qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum, neque turpis lucri grátia, sed voluntárie; neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et, cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Pedro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 P 5:1-4; 5:10-11\u003c/I>\u003c/FONT>\u003cbr/>\nAos sacerdotes que estão entre vós rogo eu, sacerdote como eles e testemunha dos sofrimentos de Cristo e que tomarei parte com eles naquela glória que será manifestada um dia: apascentai o rebanho de Deus que vos está confiado, cuidai dele não constrangidos, mas de boa vontade, segundo Deus; não por amor de lucro vil, mas por dedicação; não como para dominar sobre a herança \u003cFONT SIZE='1' COLOR=\"red\">do Senhor\u003c/FONT>, mas fazendo-vos modelos do rebanho. E quando aparecer o príncipe dos pastores, recebereis a coroa imarcescível da glória. Foi Deus de toda a graça que nos chamou em Jesus Cristo à sua eterna glória; e, depois de terdes sofrido um pouco, vos aperfeiçoará, fortificará e consolidará. A Ele: glória e império pelos séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 106:32; 106:31.\u003c/I>\u003c/FONT>\u003cbr/>\nExáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 106:32; 106:31\u003c/I>\u003c/FONT>\u003cbr/>\nQue seja exaltado na assembleia do povo; que seja louvado no conselho dos anciãos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorifiquem o Senhor pelas suas misericórdias: e pelas suas maravilhas em favor dos filhos dos homens. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, foi Jesus para a região de Cesareia, de Filipe, e interrogou os seus discípulos, dizendo-lhes: «Quem dizem os homens que é o Filho do homem?». Eles responderam: «Uns dizem que é João Baptista, outros que é Elias e outros que é Jeremias ou algum dos Profetas». Jesus disse-lhes: «E quem dizeis vós que eu sou?». Respondendo, Simão-Pedro disse: «Tu és Cristo, Filho de Deus vivo!». E Jesus disse-lhe: «Bem-aventurado és tu, Simão Barjona, porque não foi a carne nem o sangue que te revelaram o que dizes, mas meu Pai, que está nos céus. E Eu digo-te: tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela. Eu te darei as chaves do reino dos céus; e tudo o que ligares sobre a terra será ligado também nos céus; e tudo o que desatares sobre a terra será desatado também nos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEis que pus as minhas palavras na tua boca: eis que te constituí sobre os povos e sobre os reinos para arrancares e destruíres, e para edificares e plantares.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCom as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-13":{"date":"2027-11-13","title":"São Diogo de Alcalá, confessor","forms":[{"number":1,"title":"S. Didaci Confessoris Semiduplex vide Commune Confessoris non Pontificis (Missa Justus) [Commune/C5-1.txt]","winner":"Sancti/11-13.txt","rule":"vide C5-1;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nOmnípotens sempitérne Deus, qui dispositióne mirábili infírma mundi éligis, ut fórtia quæque confúndas: concéde propítius humilitáti nostræ; ut, piis beáti Dídaci Confessóris tui précibus, ad perénnem in cœlis glóriam sublimári mereámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente e sempiterno, que com admirável providência escolheis o que há de mais fraco no mundo para confundir os fortes, concedei propício à nossa humildade que, pelas piedosas preces do B. Diogo, vosso Confessor, mereçamos ser elevados à glória eterna nos céus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 4:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Spectáculum facti sumus mundo et Angelis et homínibus. Nos stulti propter Christum, vos autem prudéntes in Christo: nos infírmi, vos autem fortes: vos nóbiles, nos autem ignóbiles. Usque in hanc horam et esurímus, et sitímus, et nudi sumus, et cólaphis cǽdimur, et instábiles sumus, et laborámus operántes mánibus nostris: maledícimur, et benedícimus: persecutiónem pátimur, et sustinémus: blasphemámur, et obsecrámus: tamquam purgaménta hujus mundi facti sumus, ómnium peripséma usque adhuc. Non ut confúndant vos, hæc scribo, sed ut fílios meos caríssimos móneo: in Christo Jesu, Dómino nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 4:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tornamo-nos espectáculo do mundo, dos Anjos e dos homens. Somos loucos por amor de Cristo; mas vós sois prudentes em Cristo. Nós somos fracos; mas vós sois fortes. Vós sois honrados; mas nós somos desprezados. Até agora padecemos a fome, a sede e a nudez; fomos maltratados; andamos errantes; trabalhamos penosamente com nossas próprias mãos. Somos amaldiçoados, mas abençoamos; somos perseguidos, e sofremos; somos blasfemados, e correspondemos com orações. Temos sido considerados até ao presente como o refugo deste mundo, como a escória de todos! Escrevo estas cousas, não para vos envergonhar, mas para vos admoestar, como meus filhos caríssimos em Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo fala com sabedoria e a sua língua proclama a justiça!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que teme o Senhor e que põe todo seu zelo em obedecer-Lhe. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Não temais, pequeno rebanho, pois agradou ao vosso Pai dar-vos o seu reino. Vendei tudo quanto possuís e dai-o em esmolas. Fazei para vós bolsas que se não estraguem com o tempo; ajuntai um tesouro no céu, onde o ladrão não pode chegar, nem a traça o pode corromper; pois, onde estiver o vosso tesouro, aí estará o vosso coração».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nIn virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nCom o vosso poder, Senhor, se alegrará o justo, o qual exultará de alegria, vendo-se salvo por Vós. Concedestes-lhe, Senhor, o desejo da sua alma.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPræsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos conceder-nos, Deus omnipotente, que esta oferta da nossa humildade, em honra dos vossos Santos, Vos seja agradável; e permiti que nos purifique ao mesmo tempo o corpo e a alma.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nEm verdade vos digo: vós, que abandonastes tudo e me seguistes, recebereis o cêntuplo e possuireis a vida eterna.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Dídaco Confessóre tuo, per hæc contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, Vos imploramos, havendo nós recebido o alimento celestial, fazei que, por intercessão do B. Confessor Diogo sejamos fortificados contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-14":{"date":"2027-11-14","title":"VI Domingo depois da Epifania retomado depois de Pentecostes","forms":[{"number":1,"title":"Dominica VI quæ superfuit Post Epiphaniam IV. Novembris\tSemiduplex","winner":"Tempora/PentEpi6-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens Deus: ut, semper rationabília meditántes, quæ tibi sunt plácita, et dictis exsequámur et factis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Vos imploramos, ó Deus omnipotente, que, meditando nós incessantemente nas coisas santas, pratiquemos sempre, tanto em palavras como em acções, o que seja do vosso agrado.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Thessalonicénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Thess 1:2-10\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Grátias ágimus Deo semper pro ómnibus vobis, memóriam vestri faciéntes in oratiónibus nostris sine intermissióne, mémores óperis fídei vestræ, et labóris, et caritátis, et sustinéntiæ spei Dómini nostri Jesu Christi, ante Deum et Patrem nostrum: sciéntes, fratres, dilécti a Deo. electiónem vestram: quia Evangélium nostrum non fuit ad vos in sermóne tantum, sed et in virtúte, et in Spíritu Sancto, et in plenitúdine multa, sicut scitis quales fuérimus in vobis propter vos. Et vos imitatóres nostri facti estis, et Dómini, excipiéntes verbum in tribulatióne multa, cum gáudio Spíritus Sancti: ita ut facti sitis forma ómnibus credéntibus in Macedónia et in Achája. A vobis enim diffamátus est sermo Dómini, non solum in Macedónia et in Achája, sed et in omni loco fides vestra, quæ est ad Deum, profécta est, ita ut non sit nobis necésse quidquam loqui. Ipsi enim de nobis annúntiant, qualem intróitum habuérimus ad vos: et quómodo convérsi estis ad Deum a simulácris, servíre Deo vivo et vero, et exspectáre Fílium ejus de cœlis quem suscitávit ex mórtuis Jesum, qui erípuit nos ab ira ventúra.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Tessalonicenses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Ts 1:2-10\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Continuamente damos graças a Deus por vós todos, lembrando-nos de vós sem cessar nas nossas orações, e recordando diante de Deus, nosso Pai, as obras da vossa fé, os trabalhos da vossa caridade e a constância da vossa esperança em Cristo. Sabemos, irmãos amados de Deus, que fostes escolhidos; pois o nosso Evangelho vos não foi pregado somente com palavras, mas também com milagres, pelo poder do Espírito Santo e com a plenitude de muitos dons. Não ignorais, também, como temos procedido no meio de vós, por causa da vossa salvação. E assim vos fizestes nossos imitadores, e do Senhor, recebendo a sua palavra no meio de muitas tribulações com a alegria do Espírito Santo, de sorte que vos tornastes modelo para todos os fiéis da Macedónia e da Acaia. Pois não só fostes a causa de que a palavra do Senhor se transmitisse na Macedónia e na Acaia, mas também a vossa fé em Deus fez-se conhecer em todo o lugar; e tanto que nem é necessário que falemos em tal. Todos esses povos apregoam o êxito que alcançámos junto de vós, e como vos convertestes, abandonando os ídolos para servir a Deus vivo e verdadeiro, e para esperar do céu o seu Filho Jesus, que ressuscitou dos mortos e nos livrou da ira futura.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:31-35\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus turbis parábolam hanc: Símile est regnum cœlórum grano sinápis, quod accípiens homo seminávit in agro suo: quod mínimum quidem est ómnibus semínibus: cum autem créverit, majus est ómnibus oléribus, et fit arbor, ita ut vólucres cœli véniant et hábitent in ramis ejus. Aliam parábolam locútus est eis: Símile est regnum cœlórum ferménto, quod accéptum múlier abscóndit in farínæ satis tribus, donec fermentátum est totum. Hæc ómnia locútus est Jesus in parábolis ad turbas: et sine parábolis non loquebátur eis: ut implerétur quod dictum erat per Prophétam dicéntem: Apériam in parábolis os meum, eructábo abscóndita a constitutióne mundi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:31-35\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo Jesus disse às turbas: «O reino dos céus é semelhante a um grão de mostarda que um homem tomou e semeou no seu campo, a qual é a mais pequena de todas as sementes, mas, quando cresce, torna-se na maior de todas as plantas, e forma-se uma árvore de tal modo grande que as aves do céu vêm pousar nos seus ramos», Depois, ainda Jesus lhes disse: «O reino dos céus é semelhante ao fermento que uma mulher toma e mistura em três medidas de farinha, até que todas estejam lêvedas». Tudo isto disse Jesus em parábolas; e sem parábolas não falava, para que se cumprisse o que fora dito pelo Profeta: «Abrirei a minha boca em parábolas e revelarei muitas coisas que estão ocultas desde a criação do mundo».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc nos oblátio, Deus, mundet, quǽsumus, et rénovet, gubérnet et prótegat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nÓ Deus, Vos imploramos, que esta oblação nos purifique, restaure, governe e guarde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nCœléstibus, Dómine, pasti delíciis: quǽsumus; ut semper éadem, per quæ veráciter vívimus, appétimus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nAlimentados com as celestiais delícias, Senhor, Vos pedimos humildemente, concedei-nos que aspiremos continuamente a este mesmo alimento, pelo qual alcançaremos a verdadeira vida.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-15":{"date":"2027-11-15","title":"Santo Alberto Magno, bispo, confessor e doutor","forms":[{"number":1,"title":"S. Alberti Magni Episcopi Confessoris et Ecclesiæ Doctoris Duplex vide Commune Doctorum Pontificium (Missa In medio) [Commune/C4a.txt]","winner":"Sancti/11-15.txt","rule":"vide C4a;\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Albértum Pontíficem tuum atque Doctórem in humána sapiéntia divínæ fídei subjiciénda magnum effecísti: da nobis, quǽsumus; ita ejus magistérii inhærére vestígiis, ut luce perfécta fruámur in cœlis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que ao B. Alberto, vosso Pontífice e Doutor, tornastes grande na arte de sujeitar a sabedoria humana à fé divina, concedei-nos, Vos suplicamos, que de tal modo sigamos as lições do seu magistério que nos céus gozemos a luz perfeita.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Timótheum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tim 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum imple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo a Timóteo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tm 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimo: Conjuro-te diante de Deus e de Jesus Cristo, que há-de julgar vivos e mortos na sua vinda e no seu reino, a que pregues a palavra; instes oportuna e inoportunamente; repreendas; supliques; e ameaces com toda a paciência e doutrina; pois virá tempo em que não suportarão a sã doutrina, mas, indo ao sabor dos seus desejos, procurarão para si muitos mestres, que lhes preguem o que os ouvidos gostam de escutar, e fechem os ouvidos à verdade, para os abrirem às fábulas. Tu, porém, vigia, trabalha em tudo, cumpre o ministério de evangelista e desempenha o teu ministério. Sê sóbrio. Pois quanto a mim sou como uma vítima já aspergida para o sacrifício. O tempo da minha morte já se aproxima. Pelejei o bom combate; acabei a vida; permaneci na fé. Não me falta mais do que esperar a coroa da justiça, que me está reservada, a qual o Senhor, como justo juiz, me dará no grande dia: e não somente a mim, mas também àqueles que amam a sua vinda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo falará com sabedoria e a sua língua proclamará a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está sempre no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmou-o o Senhor e revestiu-o com a túnica da glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Sois o sal da terra. Se o sal perde a força, com que salgará? Para nada mais presta, senão para se lançar fora e ser pisado pelos homens. Sois a luz do mundo. Uma cidade situada no cimo de um monte não pode ficar escondida. Nem se acende uma luz para a meter debaixo do alqueire, mas para a colocar no candeeiro, a fim de alumiar todos os que estão em casa. Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem vosso Pai, que está nos céus. Não penseis que vim abrogar a Lei ou os Profetas: não vim abrogar, mas aperfeiçoar; porque em verdade vos digo: até que passe o céu e a terra, nem um iota, nem um til se omitirá na Lei. Quem quer, pois, que transgrida, ainda um dos mais pequenos mandamentos, ou ensine os homens a violá-los, será chamado o menor no reino dos céus. Porém, quem os cumprir e ensinar será chamado grande no reino dos céus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSacrifíciis præséntibus, Dómine, quǽsumus, inténde placátus: ut quod Passiónis Fílii tui Dómini nostri mystério gérimus, beáti Alberti intercessióne et exémplo, pio consequámur afféctu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPelos presentes sacrifícios, Senhor, Vos suplicamos, olhai aplacado para nós, a fim de que com o exemplo e intercessão do B. Alberto consigamos alcançar piedosos afectos pelo mystério, que celebramos, da paixão do vosso Filho e Nosso Senhor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>elo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPer hæc sancta quæ súmpsimus, ab hóstium nos, Dómine, impugnatióne defénde: et intercedénte beáto Albérto Confessóre tuo atque Pontífice, perpétua pace respiráre concéde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPor estes sacrossantos sacramentos, que recebemos, Senhor, defendei-nos dos ataques dos nossos inimigos, e, intercedendo o B. Alberto, vosso Confessor e Pontífice, permiti que gozemos a paz perpétua.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-16":{"date":"2027-11-16","title":"Santa Gertrudes, virgem","forms":[{"number":1,"title":"S. Gertrudis Virginis Duplex vide Commune Unius Virginis tantum (Missa Dilexisti) [Commune/C6a.txt]","winner":"Sancti/11-16.txt","rule":"vide C6a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>mastes a justiça e odiastes a iniquidade; pelo que ungiu-vos o Senhor, vosso Deus, com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui in corde beátæ Gertrudis Vírginis jucúndam tibi mansionem præparásti: ipsíus méritis et intercessióne; cordis nostri máculas cleménter abstérge, et ejúsdem tríbue gaudére consórtio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que para Vós preparastes uma morada agradável no coração da B. Virgem Gertrudes, atendendo aos seus méritos e intercessão, apagai misericordiosamente as máculas do nosso coração e concedei-nos o gozo da sua companhia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Cor 10:17-18; 11:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Aquele que se gloria, glorie-se no Senhor; pois não é aprovado o que se louva a si mesmo, mas aquele a quem Deus recomenda. Queira Deus que possais suportar um pouco ainda a minha loucura; mas suportai-me ainda, pois estou zeloso de vós da parte do zelo de Deus. Com efeito, desposei-vos com o único esposo, para vos apresentar a Cristo como virgem pura.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAdducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai com beleza e com majestade; ide gozar a vitória e reinai.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da verdade, da mansidão e da justiça, a vossa dextra praticará maravilhas! Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nApós ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: «Eis que chega o esposo; ide ao seu encontro». Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: «Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se». As prudentes responderam-lhes: «Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o». Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: «Senhor, senhor, abri-nos a porta». Ele respondeu: «Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nFíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:10\u003c/I>\u003c/FONT>\u003cbr/>\nAs filhas dos reis formam a vossa corte de glória: a própria rainha está colocada à vossa direita, envergando um vestido de ouro, recamado da mais rica variedade.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:4-6\u003c/I>\u003c/FONT>\u003cbr/>\nQuinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:4; 25:6\u003c/I>\u003c/FONT>\u003cbr/>\nAs cinco virgens prudentes levaram azeite em seus vasos para suas lâmpadas. Ora, no meio da noite, ouviu-se este clamor: «Eis que chega o esposo; comparecei diante de Cristo, vosso Senhor».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-17":{"date":"2027-11-17","title":"São Gregório Taumaturgo, bispo e confessor","forms":[{"number":1,"title":"S. Gregorii Thaumaturgi Episcopi et Confessoris Duplex vide Commune Confessoris Pontificis (Missa Statuit) [Commune/C4.txt]","winner":"Sancti/11-17.txt","rule":"Evangelium non appropriatum\nvide C4;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 131:1.\u003c/I>\u003c/FONT>\u003cbr/>\nMeménto, Dómine, David: et omnis mansuetúdinis ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>tátuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:30\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 131:1\u003c/I>\u003c/FONT>\u003cbr/>\nLembrai-vos de David, ó Senhor, e da sua grande mansidão.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>a, quǽsumus, omnípotens Deus: ut beáti Gregórii Confessóris tui atque Pontíficis veneránda solémnitas, et devotiónem nobis áugeat et salútem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDignai-Vos permitir, ó Deus omnipotente, que a veneranda solenidade do vosso Confessor e Pontífice Gregório aumente a nossa piedade e nos assegure a salvação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16-27; 45, 3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:16-27; 45:3-20\u003c/I>\u003c/FONT>\u003cbr/>\nEis o grande sacerdote, que nos dias da sua vida agradou a Deus e foi julgado justo; e no tempo da ira se tornou a reconciliação dos homens. Ninguém o igualou na observância das leis do Altíssimo. Eis porque o Senhor jurou que o tornaria grande no meio do seu povo. O Senhor abençoou nele todos os povos; e com ele ratificou a sua aliança. O Senhor deu-lhe as suas bênçãos e continuou a dispensar-lhe a sua misericórdia, vendo-se bem que este homem achou graça aos olhos do Senhor, que, por isso mesmo, o engrandeceu diante dos reis e lhe deu uma coroa de glória. Estabeleceu com ele uma aliança eterna, elevou-o ao sumo sacerdócio, e tornou-o feliz na glória para exercer o sacerdócio, louvar o seu nome e oferecer-lhe dignamente incenso de odor agradável.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEcce sacérdos magnus, qui in diébus suis plácuit Deo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 44:20\u003c/I>\u003c/FONT>\u003cbr/>\nNon est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 109:4\u003c/I>\u003c/FONT>\u003cbr/>\nTu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:16\u003c/I>\u003c/FONT>\u003cbr/>\nEis o grande sacerdote que nos dias da sua vida agradou a Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 44:20\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Não foi encontrado outrem semelhante a ele na observância das leis do Altíssimo. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 109:4\u003c/I>\u003c/FONT>\u003cbr/>\nTu és sacerdote para sempre, segundo a ordem de Melquisedeque. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Marcum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:22-24\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Respóndens Jesus discípulis suis, ait illis: Habéte fidem Dei. Amen, dico vobis, quia, quicúmque díxerit huic monti: Tóllere et míttere in mare, et non hæsitáverit in corde suo, sed credíderit, quia, quodcúmque díxerit, fiat, fiet ei. Proptérea dico vobis: Omnia quæcúmque orántes pétitis, crédite quia accipiétis, et evénient vobis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Marcos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:22-24\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, Jesus disse aos seus discípulos: «Tende fé em Deus. Em verdade vos digo que todo aquele que disser a esta montanha «tira-te e lança-te no mar», e disser isto sem hesitar no seu coração e até acreditando que tudo o que disse acontecerá, fique certo de que o verá cumprir-se. Eis porque vos digo: Tudo quanto pedirdes na oração acreditai que o alcançareis e vereis».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 88:21-22\u003c/I>\u003c/FONT>\u003cbr/>\nInvéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 88:21-22\u003c/I>\u003c/FONT>\u003cbr/>\nEncontrei o meu servo David: e ungi-o com meu óleo sagrado: a minha mão o socorrerá e o meu braço o fortalecerá.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue os vossos santos, Senhor, Vos suplicamos, nos alegrem em toda a parte, a fim de que, honrando os seus méritos, sintamos o efeito do seu patrocínio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nPræsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Gregório Confessóre tuo atque Pontífice, benefícia potióra sumámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDignai-Vos permitir, ó Deus omnipotente, que, dando-Vos nós graças pelos benefícios recebidos, alcancemos por intercessão do B. Gregório, vosso Confessor e Pontífice, ainda outros maiores.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-18":{"date":"2027-11-18","title":"Dedicação das Basílicas de São Pedro e São Paulo, apóstolos","forms":[{"number":1,"title":"In Dedicatione Basilicarum Ss. Apostolorum Petri et Pauli Duplex maius ex Commune Dedicationis Ecclesiae [Commune/C8.txt]","winner":"Sancti/11-18r.txt","rule":"ex C8;\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gen 28:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>erríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuam dilécta tabernácula tua, Dómine virtútum! Concupíscit, et déficit ánima mea in átria Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>erríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Gn 28:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue terrível é este lugar! É verdadeiramente a casa de Deus e a porta do céu: e será chamado o palácio de Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 83:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nQuão dilectos são os vossos tabernáculos, ó Senhor dos exércitos! Minha alma suspira com ardor e em êxtase, em desejos de viver junto dos átrios do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue terrível é este lugar! É verdadeiramente a casa de Deus e a porta do céu: e será chamado o palácio de Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>In Anniversario Dedicationis Ecclesiæ\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nobis per síngulos annos hujus sancti templi tui consecratiónis réparas diem, et sacris semper mystériis repræséntas incólumes: exáudi preces pópuli tui, et præsta; ut quisquis hoc templum benefícia petitúrus ingréditur, cuncta se impetrásse lætétur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que, anualmente, renovais em nosso favor o dia da consagração deste santo Templo e nos conservais incólumes para podermos sempre celebrar estes sagrados mystérios, ouvi as orações do vosso povo e concedei a todos aqueles que entrarem neste templo, para pedir as vossas graças, a alegria de as alcançarem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Apocalýpsis beáti Joánnis Apóstoli\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 21:2-5\u003c/I>\u003c/FONT>\u003cbr/>\nIn diébus illis: Vidi sanctam civitátem Jerúsalem novam descendéntem de cœlo a Deo, parátam sicut sponsam ornátam viro suo. Et audívi vocem magnam de throno dicéntem: Ecce tabernáculum Dei cum homínibus, et habitábit cum eis. Et ipsi pópulus ejus erunt, et ipse Deus cum eis erit eórum Deus: et abstérget Deus omnem lácrimam ab óculis eórum: et mors ultra non erit, neque luctus neque clamor neque dolor erit ultra, quia prima abiérunt. Et dixit, qui sedébat in throno: Ecce, nova fácio ómnia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro do Apocalipse do B. Ap.º S. João.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Apoc 21:2-5\u003c/I>\u003c/FONT>\u003cbr/>\nNaqueles dias, vi a cidade santa, a nova Jerusalém, que vinha de Deus e descia do céu, ornada como uma esposa que se prepara para receber o esposo. E ouvi uma voz forte, que falava do trono, e dizia: «Eis aqui o tabernáculo de Deus no meio dos homens. O Senhor habitará com eles, que serão o seu povo; e o próprio Deus permanecerá com eles e será o seu Deus, enxugando-lhes todas as lágrimas dos seus olhos. Então já não existirão nem a morte, nem as lágrimas, nem os clamores, nem as dores, porque o primeiro estado das cousas terá acabado». E aquele que estava sentado no trono disse: «Eu vou renovar todas as cousas!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLocus iste a Deo factus est, inæstimábile sacraméntum, irreprehensíbilis est.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Deus, cui astat Angelórum chorus, exáudi preces servórum tuórum. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 137:2\u003c/I>\u003c/FONT>\u003cbr/>\nAdorábo ad templum sanctum tuum: et confitébor nómini tuo. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nEste lugar foi feito por Deus: ele é um mystério inapreciável e isento de qualquer defeito.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Deus, diante de Quem se prostram os caros dos Anjos, ouvi as preces dos vossos servos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 137:2\u003c/I>\u003c/FONT>\u003cbr/>\nAdorar-Vos-ei no vosso santo Templo e louvarei o vosso santo Nome. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 19:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ingréssus Jesus perambulábat Jéricho. Et ecce, vir nómine Zachǽus: et hic princeps erat publicanórum, et ipse dives: et quærébat vidére Jesum, quis esset: et non póterat præ turba, quia statúra pusíllus erat. Et præcúrrens ascéndit in árborem sycómorum, ut vidéret eum; quia inde erat transitúrus. Et cum venísset ad locum, suspíciens Jesus vidit illum, et dixit ad eum: Zachǽe, festínans descénde; quia hódie in domo tua opórtet me manére. Et festínans descéndit, et excépit illum gaudens. Et cum vidérent omnes, murmurábant, dicéntes, quod ad hóminem peccatórem divertísset. Stans autem Zachǽus, dixit ad Dóminum: Ecce, dimídium bonórum meórum, Dómine, do paupéribus: et si quid áliquem defraudávi, reddo quádruplum. Ait Jesus ad eum: Quia hódie salus dómui huic facta est: eo quod et ipse fílius sit Abrahæ. Venit enim Fílius hóminis quǽrere et salvum fácere, quod períerat.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 19:1-10\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, havendo Jesus entrado em Jericó, atravessava a cidade. Ora, havia ali um homem, chamado Zaqueu, príncipe dos publicanos e muito rico, que procurava ver Jesus para o conhecer; mas o não conseguia por causa das turbas do povo, pois ele era de baixa estatura. Correu, pois, adiante e subiu para um sicómoro, para ver Jesus, que devia passar por aquele lugar. Chegando Jesus ali, ergueu os olhos e, vendo-o, disse-lhe: «Zaqueu, descei depressa, porque me convém hospedar-me hoje em vossa casa». Imediatamente Zaqueu desceu e recebeu Jesus com alegria. Vendo as pessoas isto, começaram a murmurar, dizendo que Jesus ia hospedar-se em casa de um pecador. Entretanto Zaqueu estava perante o Senhor e dizia-Lhe: «Senhor, eis que vou dar metade dos meus bens aos pobres; e, se defraudei alguém, restituirei o quádruplo». Jesus disse então: «Esta casa recebeu hoje a salvação, pois este também é filho de Abraão. O Filho do homem veio para procurar e salvar o que estava perdido!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Par 29:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nDómine Deus, in simplicitáte cordis mei lætus óbtuli univérsa; et pópulum tuum, qui repértus est, vidi cum ingénti gáudio: Deus Israël, custódi hanc voluntátem, allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cr 29:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, meu Deus, foi com simplicidade de coração e com alegria que Vos oferecer todas as cousas: foi com intenso júbilo que vi reunido o vosso povo. Ó Deus de Israel, conservai em minha alma estas boas disposições. Aleluia.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Extra Ecclesiam dedicatam\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>nnue, quǽsumus, Dómine, précibus nostris: ut, dum hæc vota præséntia réddimus, ad ætérna prǽmia, te adjuvánte, perveníre mereámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos, Senhor, ouvir as nossas orações de modo que todos os que nos encontramos neste santo Templo, de cuja Dedicação celebramos o aniversário, Vos agradecemos com a oferta inteira e perfeita, que Vos fazemos, do nosso corpo e da nossa alma; e permiti que, oferecendo-Vos estes dons, alcancemos a felicidade eterna com vosso auxílio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>in Dedicatione Ecclesiae\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Qui hanc oratiónis domum, quam ædificávimus, bonórum ómnium largítor inhábitas, et Ecclésiam, quam ipse fundásti, incessábili operatióne sanctíficas. Hæc est enim vere domus oratiónis, visibílibus ædifíciis adumbráta, templum habitatiónis glóriæ tuæ, sedes incommutábilis veritátis, sanctuárium ætérnæ caritátis. Hæc est arca, qui nos a mundi eréptos dilúvio, in portu salútis indúcit. Hæc est dilécta et única sponsa, quam acquisívit Christus sánguine suo, quam vivíficat Spíritu suo, cujus in sinu renáti per grátiam tuam, lacte verbi páscimur, pane vitæ roborámur, misericórdiæ tuæ subsídiis confovémur. Hæc fidéliter in terris, Sponso adiuvánte, mílitat, et perénniter in cælis, ipso coronánte, triúmphat. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Dedicação de Igreja (Prefácio Comum)\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 21:13\u003c/I>\u003c/FONT>\u003cbr/>\nDomus mea domus oratiónis vocábitur, dicit Dóminus: in ea omnis, qui petit, áccipit; et qui quærit, invénit; et pulsánti aperiétur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 21:13\u003c/I>\u003c/FONT>\u003cbr/>\nA minha casa será chamada casa de oração, diz o Senhor: e todo aquele que aí pede, recebe: e o que procura, acha: e ao que bate, abrir-se-lhe-á.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui de vivis et electis lapídibus ætérnum majestáti tuæ prǽparas habitáculum: auxiliáre pópulo tuo supplicánti; ut, quod Ecclésiæ tuæ corporálibus próficit spátiis, spirituálibus amplificétur augméntis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>No dia da dedicação\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>ignai-Vos conceder-nos, ó Deus omnipotente, que neste lugar, que, ainda que indignos, dedicámos ao vosso nome, ouçais benignamente todos os que Vos implorarem.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-19":{"date":"2027-11-19","title":"Santa Isabel da Hungria, viúva","forms":[{"number":1,"title":"S. Elisabeth Viduæ Duplex vide Commune Unius non Virginis nec Martyris (Missa Cognovi) [Commune/C7a.txt]","winner":"Sancti/11-19.txt","rule":"vide C7a;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:75; 118:120\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>onheço, Senhor, que os vossos juízos são equitativos e que me humilhastes com justiça. Esmagai as minhas carnes com vosso temor; os vossos Mandamentos inspiram-me temor.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nTuórum corda fidélium, Deus miserátor, illústra: et, beátæ Elisabeth précibus gloriósis; fac nos próspera mundi despícere, et cœlésti semper consolatióne gaudére.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Pontiani Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>G\u003c/I>\u003c/B>\u003c/FONT>regem tuum, Pastor ætérne, placátus inténde: et, per beátum Pontiánum Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus de misericórdia, esclarecei os corações dos vossos fiéis; e, pelas gloriosas preces da B. Isabel, concedei-nos a graça de desprezarmos as prosperidades deste mundo e de gozarmos perpetuamente a consolação celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ponciano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Ponciano Vosso Mártir e Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Prov 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nMulíerem fortem quis invéniet? Procul et de últimis fínibus prétium ejus. Confídit in ea cor viri sui, et spóliis non indigébit. Reddet ei bonum, et non malum, ómnibus diébus vitæ suæ. Quæsívit lanam et linum, et operáta est consílio mánuum suárum. Facta est quasi navis institóris, de longe portans panem suum. Et de nocte surréxit, dedítque prædam domésticis suis, et cibária ancíllis suis. Considerávit agrum, et emit eum: de fructu mánuum suárum plantávit víneam. Accínxit fortitúdine lumbos suos, et roborávit bráchium suum. Gustávit, et vidit, quia bona est negotiátio ejus: non exstinguétur in nocte lucérna ejus. Manum suam misit ad fórtia, et dígiti ejus apprehendérunt fusum. Manum suam apéruit ínopi, et palmas suas exténdit ad páuperem. Non timébit dómui suæ a frigóribus nivis: omnes enim doméstici ejus vestíti sunt duplícibus. Stragulátam vestem fecit sibi: byssus et púrpura induméntum ejus. Nóbilis in portis vir ejus, quando séderit cum senatóribus terræ. Síndonem fecit et véndidit, et cíngulum trádidit Chananǽo. Fortitúdo et decor induméntum ejus, et ridébit in die novíssimo. Os suum apéruit sapiéntiæ, et lex cleméntiæ in lingua ejus. Considerávit sémitas domus suæ, et panem otiósa non comédit. Surrexérunt fílii ejus, et beatíssimam prædicavérunt: vir ejus, et laudávit eam. Multæ fíliæ congregavérunt divítias: tu supergréssa es univérsas. Fallax grátia, et vana est pulchritúdo: múlier timens Dóminum, ipsa laudábitur. Date ei de fructu mánuum suárum: et laudent eam in portis ópera ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Pr 31:10-31\u003c/I>\u003c/FONT>\u003cbr/>\nQuem encontrará uma mulher forte? Seu valor é maior do que o das pérolas que vêm dos confins do mundo. Nela confia o coração do marido, que por isso lhe não faltará proveito. Ela procurará praticar o bem, e não o mal, em todos os dias da sua vida. Ela procurará a lã e o linho, e, diligentemente, trabalhará neles com suas mãos. Ela é como um navio de mercador que traz de longe o seu pão! Levanta-se quando ainda é noite, e dá alimento à família e trabalho aos servos. Ela pensa em um campo, compra-o e planta uma vinha com o trabalho de suas mãos. Cinge com vigor os seus rins e esforça os seus braços. Examina e vê que seu negócio é bom e que sua lâmpada se não apagará durante a noite. Emprega suas mãos em trabalhos rudes e seus dedos no fuso. Estende a sua mão ao indigente e o seu braço ao pobre. Não receia na sua casa nem o frio, nem a neve, porque todos os criados têm roupa em duplo. Fabrica para si tapeçarias e faz os seus vestidos de bom linho e de púrpura. Seu marido será enobrecido, quando se sentar às Portas da cidade com os senadores da terra. Faz vestidos, que vende, e cintas, que entrega aos mercadores. Revestiu-se de coragem e de glória, e, alegre, aguarda o futuro. Fala com sabedoria e a sua língua é clemente. Vigia os caminhos de sua casa e não come o pão na ociosidade. Erguem-se seus filhos e a proclamam bem-aventurada, e seu marido a louva também: «Muitas filhas reuniram virtudes, mas tu excedeste-las». Enganadora é a graça e vã é a formosura. Só a mulher, que teme o Senhor, será louvada. Dai-lhe o produto de suas mãos, e que a louvem às portas da cidade, por causa das suas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3; 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: eis porque Deus vos abençoou para a eternidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por causa da vossa verdade, mansidão e justiça, a vossa dextra praticará maravilhas. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nCaminhai, pois, com beleza e com majestade; ide gozar a vitória e reinai. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 13:44-52\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a um tesouro escondido no campo, o qual um homem acha e esconde; e, alegre com o achado, vai, vende tudo o que tem e compra o campo. Igualmente o reino dos céus é semelhante a um negociante, que busca pedras preciosas; e, achando uma de grande preço, vai, vende tudo o que tem e compra-a. O reino dos céus é ainda semelhante a uma rede que, lançada ao mar, prende toda a casta de peixes, e, estando já cheia, os pescadores a puxam para a praia, escolhem os bons peixes para os vasos e deitam fora os maus. Assim será no fim dos séculos: virão os Anjos e separarão os maus do meio dos justos e os lançarão na fornalha do fogo, onde não haverá senão fogo e ranger de dentes. Haveis compreendido tudo isto?». «Sim», responderam eles. E Jesus disse-lhes: «Por esta razão todo o escriba douto no que diz respeito ao reino dos céus é semelhante a um pai de família, que tira dos seus tesouros cousas novas e velhas».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nDiffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:3\u003c/I>\u003c/FONT>\u003cbr/>\nA graça espalhou-se nos vossos lábios: por isso Deus vos abençoou para a eternidade e para todos os séculos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAccépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Pontiani Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>blátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nAceitai, Senhor, esta oferta, que Vos consagra o vosso povo fiel em honra dos vossos santos, pelos méritos dos quais reconhece que tem alcançado a vossa assistência nas tribulações.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ponciano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>om as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nDilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nAmastes a justiça e odiastes a iniquidade: eis porque o Senhor, vosso Deus, vos ungiu com o óleo da alegria, de preferência às vossas companheiras.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Pontiani Papæ et Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo Vós, Senhor, saciado a vossa família com vossos dons sagrados, dignai-Vos favorecer-nos sempre com a intercessão daquela cuja festa celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Ponciano\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-20":{"date":"2027-11-20","title":"São Félix de Valois, confessor","forms":[{"number":1,"title":"S. Felicis de Valois Confessoris Duplex vide Commune Confessoris non Pontificis (Missa Justus) [Commune/C5-1.txt]","winner":"Sancti/11-20.txt","rule":"vide C5-1;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>J\u003c/I>\u003c/B>\u003c/FONT>ustus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13-14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT> justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano, plantado na casa do Senhor e nos átrios da casa do nosso Deus.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui beátum Felícem Confessórem tuum ex erémo ad munus rediméndi captívos cǽlitus vocáre dignátus es: præsta, quǽsumus; ut per grátiam tuam ex peccatórum nostrórum captivitáte, eius intercessióne, liberáti, ad cæléstem pátriam perducámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que, de um modo celestial, ao B. Félix, vosso Confessor, Vos dignastes chamar da solidão do deserto para a missão de remir os cativos, concedei-nos, Vos rogamos, que, sendo nós pela sua intercessão e pela vossa graça, livres do cativeiro dos nosso pecados, alcancemos a pátria celestial.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Corínthios\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 4:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Spectáculum facti sumus mundo et Angelis et homínibus. Nos stulti propter Christum, vos autem prudéntes in Christo: nos infírmi, vos autem fortes: vos nóbiles, nos autem ignóbiles. Usque in hanc horam et esurímus, et sitímus, et nudi sumus, et cólaphis cǽdimur, et instábiles sumus, et laborámus operántes mánibus nostris: maledícimur, et benedícimus: persecutiónem pátimur, et sustinémus: blasphemámur, et obsecrámus: tamquam purgaménta hujus mundi facti sumus, ómnium peripséma usque adhuc. Non ut confúndant vos, hæc scribo, sed ut fílios meos caríssimos móneo: in Christo Jesu, Dómino nostro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Coríntios.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>1 Cor 4:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Tornamo-nos espectáculo do mundo, dos Anjos e dos homens. Somos loucos por amor de Cristo; mas vós sois prudentes em Cristo. Nós somos fracos; mas vós sois fortes. Vós sois honrados; mas nós somos desprezados. Até agora padecemos a fome, a sede e a nudez; fomos maltratados; andamos errantes; trabalhamos penosamente com nossas próprias mãos. Somos amaldiçoados, mas abençoamos; somos perseguidos, e sofremos; somos blasfemados, e correspondemos com orações. Temos sido considerados até ao presente como o refugo deste mundo, como a escória de todos! Escrevo estas cousas, não para vos envergonhar, mas para vos admoestar, como meus filhos caríssimos em Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo fala com sabedoria e a sua língua proclama a justiça!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que teme o Senhor e que põe todo seu zelo em obedecer-Lhe. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:32-34\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: «Não temais, pequeno rebanho, pois agradou ao vosso Pai dar-vos o seu reino. Vendei tudo quanto possuís e dai-o em esmolas. Fazei para vós bolsas que se não estraguem com o tempo; ajuntai um tesouro no céu, onde o ladrão não pode chegar, nem a traça o pode corromper; pois, onde estiver o vosso tesouro, aí estará o vosso coração».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nIn virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:2-3\u003c/I>\u003c/FONT>\u003cbr/>\nCom o vosso poder, Senhor, se alegrará o justo, o qual exultará de alegria, vendo-se salvo por Vós. Concedestes-lhe, Senhor, o desejo da sua alma.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPræsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nDignai-Vos conceder-nos, Deus omnipotente, que esta oferta da nossa humildade, em honra dos vossos Santos, Vos seja agradável; e permiti que nos purifique ao mesmo tempo o corpo e a alma.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:28-29\u003c/I>\u003c/FONT>\u003cbr/>\nEm verdade vos digo: vós, que abandonastes tudo e me seguistes, recebereis o cêntuplo e possuireis a vida eterna.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nQuǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Felíce Confessóre tuo, per hæc contra ómnia advérsa muniámur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus omnipotente, Vos imploramos, havendo nós recebido o alimento celestial, fazei que, por intercessão do B. Confessor Félix sejamos fortificados contra todas as adversidades.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-21":{"date":"2027-11-21","title":"XXIV Domingo depois de Pentecostes","forms":[{"number":1,"title":"Dominica XXIV et ultima Post Pentecosten V. Novembris\tSemiduplex","winner":"Tempora/Pent24-0.txt","rule":"Gloria\nCredo\nPrefatio=Trinitate\nSuffr=Sanctorum;Maria3,Ecclesiæ,Papa;;\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 29:11; 29:12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nBenedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 29:11-12; 29:14\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:2\u003c/I>\u003c/FONT>\u003cbr/>\nAbençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nExcita, quǽsumus, Dómine, tuórum fidélium voluntátes: ut, divíni óperis fructum propénsius exsequéntes; pietátis tuæ remédia majóra percípiant.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nDespertai, Senhor, Vos imploramos, a vontade dos vossos fiéis, para que, procurando com mais fervor o fruto das obras divinas, alcancem da vossa misericórdia os melhores remédios.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Colossénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Non cessámus pro vobis orántes et postulántes, ut impleámini agnitióne voluntátis Dei, in omni sapiéntia et intelléctu spiritáli: ut ambulétis digne Deo per ómnia placéntes: in omni ópere bono fructificántes, et crescéntes in scientia Dei: in omni virtúte confortáti secúndum poténtiam claritátis ejus in omni patiéntia, et longanimitáte cum gáudio, grátias agentes Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Colossenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Col 1:9-14\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Não cessamos de orar a Deus por vós e de pedir-Lhe que vos conceda o verdadeiro conhecimento da sua vontade em toda a plenitude da sabedoria e da inteligência espiritual, para que tenhais uma conduta digna de Deus, agradando-Lhe em todas as cousas, dando frutos em todas as espécies de boas obras e progredindo no conhecimento de Deus. Que sejais fortificados com o poder da glória de Deus para suportardes tudo com paciência, longanimidade e alegria, dando graças a Deus Pai, que nos tornou dignos de tomar parte na herança dos Santos na luz e nos livrou do poder das trevas, para nos transportarmos ao reino do seu amantíssimo Filho, em quem alcançámos pelo seu Sangue a Redenção e a remissão dos pecados.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLiberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 43:8-9\u003c/I>\u003c/FONT>\u003cbr/>\nLivrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDo fundo do abysmo Vos invoquei, Senhor: escutai a minha oração. Aleluia.\u003cbr/>\nAlleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 24:15-35\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Cum vidéritis abominatiónem desolatiónis, quæ dicta est a Daniéle Prophéta, stantem in loco sancto: qui legit, intélligat: tunc qui in Judǽa sunt, fúgiant ad montes: et qui in tecto, non descéndat tóllere áliquid de domo sua: et qui in agro, non revertátur tóllere túnicam suam. Væ autem prægnántibus et nutriéntibus in illis diébus. Oráte autem, ut non fiat fuga vestra in híeme vel sábbato. Erit enim tunc tribulátio magna, qualis non fuit ab inítio mundi usque modo, neque fiet. Et nisi breviáti fuíssent dies illi, non fíeret salva omnis caro: sed propter eléctos breviabúntur dies illi. Tunc si quis vobis díxerit: Ecce, hic est Christus, aut illic: nolíte crédere. Surgent enim pseudochrísti et pseudoprophétæ, et dabunt signa magna et prodígia, ita ut in errórem inducántur - si fíeri potest - étiam elécti. Ecce, prædíxi vobis. Si ergo díxerint vobis: Ecce, in desérto est, nolíte exíre: ecce, in penetrálibus, nolíte crédere. Sicut enim fulgur exit ab Oriénte et paret usque in Occidéntem: ita erit et advéntus Fílii hóminis. Ubicúmque fúerit corpus, illic congregabúntur et áquilæ. Statim autem post tribulatiónem diérum illórum sol obscurábitur, et luna non dabit lumen suum, et stellæ cadent de cælo, et virtútes cœlórum commovebúntur: et tunc parébit signum Fílii hóminis in cœlo: et tunc plangent omnes tribus terræ: et vidébunt Fílium hóminis veniéntem in núbibus cæli cum virtúte multa et majestáte. Et mittet Angelos suos cum tuba et voce magna: et congregábunt eléctos ejus a quátuor ventis, a summis cœlórum usque ad términos eórum. Ab árbore autem fici díscite parábolam: Cum jam ramus ejus tener fúerit et fólia nata, scitis, quia prope est æstas: ita et vos cum vidéritis hæc ómnia, scitóte, quia prope est in jánuis. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia hæc fiant. Cœlum et terra transíbunt, verba autem mea non præteríbunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt. 24:15-35\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos: Quando virdes a abominação da desolação, anunciada pelo Profeta Daniel, reinando no lugar santo, que aquele que lê entenda: Então, aqueles que estão na Judeia fujam para as montanhas; aquele que se achar em cima do telhado não desça para ir buscar qualquer cousa a casa; e aquele que estiver nos campos não volte a casa para procurar algum vestido. Ai das mulheres que estiverem prestes a ser mães: ou a amamentar seus filhos nesses dias! Rogai ao Senhor que a vossa fuga não seja nem no Inverno, nem ao sábado; pois a aflição será tão grande que não houve cousa semelhante desde o princípio do mundo até ao presente, como não haverá nunca mais; e, se esses dias não fossem abreviados \u003cFONT SIZE='1' COLOR=\"red\">e sê-lo-ão em atenção aos escolhidos\u003c/FONT>, ninguém seria salvo. Então, se alguém vos disser: «O Cristo está aqui, ou está acolá», não acrediteis; pois aparecerão falsos cristos e falsos profetas, que praticarão grandes maravilhas e prodígios até mesmo seduzirem \u003cFONT SIZE='1' COLOR=\"red\">se tal fora possível\u003c/FONT> os próprios escolhidos. Eu vo-lo anuncio, desde já. Se, pois, vos disserem: «Ei-l’O está no deserto», não saiais; ou se vos disserem: «Ei-l’O aqui, no lugar mais retirado de casa», não acrediteis também; pois, assim como o relâmpago parte do Oriente e brilha até ao Ocidente, assim será também a vinda do Filho do homem. Em qualquer lugar em que estiver o cadáver aí se reunirão as águias. Imediatamente após a tribulação destes dias o sol se obscurecerá, a lua não projectará luz, as estrelas cairão do céu e os poderes dos céus serão abalados. E aparecerá no céu o sinal do Filho do homem, e todas as tribos da terra se lamentarão: e verão o Filho do homem sobre as nuvens do céu, revestido de grande poder e majestade! Ele enviará os seus Anjos, que farão retinir a trombeta em som estridente, e logo convocarão os escolhidos dos quatro ventos, desde uma extremidade dos céus até à outra! Compreendei isto por esta parábola, tirada da figueira: «Quando os seus ramos estão tenros e as folhas começam a despontar, conheceis que está próximo o estio; assim também, quando virdes todas estas cousas, sabereis que o Filho do homem está próximo, que está à porta». Em verdade vos digo: «Esta geração não passará sem que isto aconteça. Passarão o céu e a terra; mas as minhas palavras não passarão!».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDe profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 129:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nDas profundezas dos abysmos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abysmos Vos invoquei.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPropítius esto, Dómine, supplicatiónibus nostris: et, pópuli tui oblatiónibus precibúsque suscéptis, ómnium nostrum ad te corda convérte; ut, a terrenis cupiditátibus liberáti, ad cœléstia desidéria transeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSede propício, Senhor, às nossas súplicas, e, depois de haverdes recebido as ofertas e as orações do vosso povo, convertei a Vós os nossos corações, a fim de que, sendo livres das cobiças deste mundo, não tenhamos outra aspiração senão a dos bens do céu.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de sanctissima Trinitate\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da SS. Trindade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, que com vosso Filho Unigénito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Marc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nAmen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mc 11:24\u003c/I>\u003c/FONT>\u003cbr/>\nNa verdade vos digo: «Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nobis, quǽsumus, Dómine: ut per hæc sacraménta quæ súmpsimus, quidquid in nostra mente vitiósum est, ipsorum medicatiónis dono curétur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nPermiti, Senhor, Vos suplicamos, que pela virtude destes sacramentos, que recebemos, tudo quanto houver de vicioso na nossa alma seja curado pelo efeito deste remédio divino.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-22":{"date":"2027-11-22","title":"Santa Cecília, virgem e mártir","forms":[{"number":1,"title":"S. Cæciliæ Virginis et Martyris Duplex vide Commune Unius Virginis Martyris (Missa Loquebar) [Commune/C6.txt]","winner":"Sancti/11-22.txt","rule":"vide C6;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui nos ánnua beátæ Cæcíliæ Vírginis et Mártyris tuæ sollemnitáte lætíficas: da, ut, quam venerámur offício, étiam piæ conversatiónis sequámur exémplo.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que nos alegrais com a solenidade anual da B. Cecília, vossa Virgem e Mártir, dignai-Vos permitir que, honrando-a com estes cultos, imitemos também os exemplos da sua piedosa vida.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 51:13-17\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 51:13-17\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, meu Deus, elevastes a minha morada acima da terra. Roguei-Vos que me livrásseis da morte, que me ameaça. Supliquei ao Senhor, Pai do meu Senhor, que me não abandone sem socorro no dia da minha aflição e durante o poderio dos soberbos. Louvarei incessantemente o vosso nome e glorificá-lo-ei na minha acção de graças, porque ouvistes a minha oração, livrastes-me da perdição e arrancastes-me da ocasião iníqua! Eis porque Vos glorificarei, cantando louvores em vossa honra, ó Senhor, nosso Deus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:11; 44:12\u003c/I>\u003c/FONT>\u003cbr/>\nAudi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\nSpécie tua et pulchritúdine tua inténde, próspere procéde et regna.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:4; 25:6\u003c/I>\u003c/FONT>\u003cbr/>\nQuinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Ps 44:11; 44:12\u003c/I>\u003c/FONT>\u003cbr/>\nEscutai, ó minha filha, vede e inclinai o vosso ouvido; o Rei está cheio de amor por vós, por causa da vossa beleza!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Com a vossa glória e com vossa formosura caminhai, triunfai e reinai. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:4; 25:6\u003c/I>\u003c/FONT>\u003cbr/>\nAs cinco virgens prudentes tomaram óleo em seus vasos para suas lâmpadas. No meio da noite uma voz soou: eis que chega o esposo: ide ao encontro de Cristo, Senhor. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: «Eis que chega o esposo; ide ao seu encontro». Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: «Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se». As prudentes responderam-lhes: «Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o». Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: «Senhor, senhor, abri-nos a porta». Ele respondeu: «Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAfferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nApós ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria e do júbilo; elas serão conduzidas ao templo do Rei, seu Senhor.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc hóstia, Dómine, placatiónis et laudis, quǽsumus: ut, intercedénte beáta Cæcília Vírgine et Mártyre tua, nos propitiatióne tua dignos semper effíciat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQue esta hóstia de propiciação e de louvor, Senhor, Vos rogamos, nos torne sempre dignos da vossa misericórdia, pela intercessão da B. Cecília, vossa Virgem e Mártir.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:78; 118:80\u003c/I>\u003c/FONT>\u003cbr/>\nConfundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:78; 118:80\u003c/I>\u003c/FONT>\u003cbr/>\nSejam confundidos os soberbos, porque praticaram iniquidades contra mim. Para não ser confundido no último dia, cumprirei os vossos mandamentos e preceitos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSatiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSaciastes, Senhor, a vossa família com vossos sacratíssimos dons; e dignai-Vos favorecer-nos sempre, Vos imploramos, pela intercessão daquela cuja festa celebramos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-23":{"date":"2027-11-23","title":"São Clemente I, papa e mártir","forms":[{"number":1,"title":"S. Clementis Papæ et Martyris Duplex vide Commune Unius Martyris Summi Pontificis (Missa Si diligis) [Commune/C2b.txt]","winner":"Sancti/11-23.txt","rule":"vide C2b;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Is 59:21; 56:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Sermónes mei, quos dedi in os tuum, non defícient de ore tuo: et múnera tua accépta erunt super altáre meum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeátus vir, qui timet Dóminum: in mandátis ejus cupit nimis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>icit Dóminus: Sermónes mei, quos dedi in os tuum, non defícient de ore tuo: et múnera tua accépta erunt super altáre meum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Is 59:21; 56:7\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: Minhas palavras, que pus na vossa boca, não cessarão de estar nos vossos lábios; e então os dons, que apresentardes nos meus altares, ser-me-ão agradáveis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 111:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurado o varão que teme o Senhor: e cujo zelo é ardente no cumprimento dos seus mandamentos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>isse o Senhor: Minhas palavras, que pus na vossa boca, não cessarão de estar nos vossos lábios; e então os dons, que apresentardes nos meus altares, ser-me-ão agradáveis.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nGregem tuum, Pastor ætérne, placátus inténde: et, per beátum Cleméntem Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Felicitatis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ræsta, quǽsumus, omnípotens Deus: ut, beátæ Felicitátis Martyris tuæ sollémnia recenséntes, méritis ipsíus protegámur et précibus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Pastor eterno, atendei propício ao vosso rebanho; e guardai-o com vossa perpétua protecção por intercessão do bem-aventurado Clemente Vosso Mártir e Sumo Pontífice, o qual escolhestes como pastor de toda a Igreja.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santa Felicidade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>oncedei-nos, ó Deus omnipotente, Vos suplicamos, que, celebrando nós a solenidade da B. Felicidade, vossa Mártir, sejamos protegidos pelos seus méritos e preces.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Philippénses\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Phil 3:17-21; 4:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Imitatóres mei estóte, et observáte eos, qui ita ámbulant, sicut habétis formam nostram. Multi enim ámbulant, quos sæpe dicébam vobis - nunc autem et flens dico - inimícos Crucis Christi: quorum finis intéritus: quorum Deus venter est: et glória in confusióne ipsórum, qui terréna sápiunt. Nostra autem conversátio in cœlis est: unde étiam Salvatórem exspectámus, Dóminum nostrum Jesum Christum, qui reformábit corpus humilitátis nostræ, configurátum córpori claritátis suæ, secúndum operatiónem, qua étiam possit subjícere sibi ómnia. Itaque, fratres mei caríssimi et desideratíssimi, gáudium meum et coróna mea: sic state in Dómino, caríssimi. Evódiam rogo et Sýntychen déprecor idípsum sápere in Dómino. Etiam rogo et te, germáne compar, ádjuva illas, quæ mecum laboravérunt in Evangélio cum Cleménte et céteris adjutóribus meis, quorum nómina sunt in libro vitæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Filipenses.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Fl 3:17-21; 4:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Sede meus imitadores e segui aqueles que se conduzem segundo o modelo que tendes em nós; porque há muitos, de quem vos tenho falado \u003cFONT SIZE='1' COLOR=\"red\">e ainda falo deles com lágrimas\u003c/FONT>, que se portam como inimigos da cruz de Cristo. Seu fim será a condenação; pois fazem do estômago o seu deus, põem a sua glória naquilo que deveria ser motivo de vergonha e não têm prazer senão nas cousas terrenas. Mas, quanto a nós, o nosso pensamento está nos céus, donde também esperamos o Salvador, Nosso Senhor Jesus Cristo, que renovará o nosso corpo vil, tornando-o semelhante aoseu corpo glorioso, por meio daquela virtude, que Ele possui, de sujeitar a si todas as cousas. Portanto, queridos e amados irmãos, que sois a minha alegria e a minha coroa, permanecei firmes no Senhor, meus caríssimos irmãos. Peço a Evódia e suplico a Sintiquene que tenham os mesmos sentimentos no Senhor. Também vos rogo, ó fiel companheiro, que auxilieis aqueles que trabalharam comigo pelo Evangelho, com Clemente e com os outros meus coadjutores, cujos nomes estão no livro da vida.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 106:32; 106:31.\u003c/I>\u003c/FONT>\u003cbr/>\nExáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 106:32; 106:31\u003c/I>\u003c/FONT>\u003cbr/>\nQue seja exaltado na assembleia do povo; que seja louvado no conselho dos anciãos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glorifiquem o Senhor pelas suas misericórdias: e pelas suas maravilhas em favor dos filhos dos homens. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, foi Jesus para a região de Cesareia, de Filipe, e interrogou os seus discípulos, dizendo-lhes: «Quem dizem os homens que é o Filho do homem?». Eles responderam: «Uns dizem que é João Baptista, outros que é Elias e outros que é Jeremias ou algum dos Profetas». Jesus disse-lhes: «E quem dizeis vós que eu sou?». Respondendo, Simão-Pedro disse: «Tu és Cristo, Filho de Deus vivo!». E Jesus disse-lhe: «Bem-aventurado és tu, Simão Barjona, porque não foi a carne nem o sangue que te revelaram o que dizes, mas meu Pai, que está nos céus. E Eu digo-te: tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela. Eu te darei as chaves do reino dos céus; e tudo o que ligares sobre a terra será ligado também nos céus; e tudo o que desatares sobre a terra será desatado também nos céus».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jer 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEcce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Jr 1:9-10\u003c/I>\u003c/FONT>\u003cbr/>\nEis que pus as minhas palavras na tua boca: eis que te constituí sobre os povos e sobre os reinos para arrancares e destruíres, e para edificares e plantares.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nOblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Felicitatis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ota pópuli tui, Dómine, propitiátus inténde: et, cujus nos tríbuis sollémnia celebráre, fac gaudére suffrágiis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nCom as ofertas destes dons, Vos suplicamos, Senhor, iluminai benignamente a vossa Igreja, a fim de que não só o vosso rebanho triunfe em toda a parte, mas também pelo poder do vosso nome os pastores sejam bem acolhidos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santa Felicidade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>ceitai propício, Senhor, os votos do vosso povo e fazei-nos gozar o efeito dos sufrágios daquela cuja festa nos permitis celebrar.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu es Petrus, et super hanc petram ædificábo Ecclésiam meam.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 16:18\u003c/I>\u003c/FONT>\u003cbr/>\nTu és Pedro, e sobre esta pedra edificarei a minha Igreja.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nRefectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Felicitatis Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>úpplices te rogámus, omnípotens Deus: ut, intercedéntibus Sanctis tuis, et tua in nobis dona multíplices, et témpora nostra dispónas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, Vos suplicamos, governai com mansidão a vossa Igreja, agora que foi alimentada com a sagrada refeição, a fim de que, dirigida com firme suavidade, alcance o incremento da sua liberdade e persista na integridade da sua doutrina.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Santa Felicidade\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus omnipotente, humildemente Vos suplicamos, pela intercessão dos vossos Santos, que multipliqueis sobre nós os vossos benefícios e governeis os dias da nossa vida.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-24":{"date":"2027-11-24","title":"São João da Cruz, confessor e doutor","forms":[{"number":1,"title":"S. Joannis a Cruce Confessoris et Ecclesiæ Doctoris Duplex vide Commune Doctoris non Pontificis (Missa In medio) [Commune/C5a.txt]","winner":"Sancti/11-24.txt","rule":"vide C5a;\nGloria\nCredoDA\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nBonum est confitéri Dómino: et psállere nómini tuo, Altíssime.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>n médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 15:5\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:2\u003c/I>\u003c/FONT>\u003cbr/>\nÉ bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>briu-lhe o Senhor a boca no meio da Igreja, encheu-o com o espírito da sabedoria e da inteligência e revestiu-o com a túnica da glória.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui sanctum Joánnem Confessórem tuum atque Doctorem perféctæ sui abnegatiónis et Crucis amatórem exímium effecísti: concéde; ut, ejus imitatióni júgiter inhæréntes, glóriam assequámur ætérnam.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>désto, Dómine, supplicatiónibus nostris: ut, qui ex iniquitáte nostra reos nos esse cognóscimus, beáti Chrysógoni Mártyris tui intercessióne liberémur.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nVos suplicamos, Senhor, que a graça celestial aumente a vossa Igreja, a qual quisestes ilustrar com os gloriosos méritos e ensinos do B. João Crisóstomo, vosso Confessor e Pontífice.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>uvi as nossas súplicas, Senhor, a fim de que, reconhecendo-nos réus pelas nossas iniquidades, sejamos absolvidos pela intercessão do vosso B. Mártir Crisógono.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Timótheum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tim 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum imple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo a Timóteo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>2 Tm 4:1-8\u003c/I>\u003c/FONT>\u003cbr/>\nCaríssimo: Conjuro-te diante de Deus e de Jesus Cristo, que há-de julgar vivos e mortos na sua vinda e no seu reino, a que pregues a palavra; instes oportuna e inoportunamente; repreendas; supliques; e ameaces com toda a paciência e doutrina; pois virá tempo em que não suportarão a sã doutrina, mas, indo ao sabor dos seus desejos, procurarão para si muitos mestres, que lhes preguem o que os ouvidos gostam de escutar, e fechem os ouvidos à verdade, para os abrirem às fábulas. Tu, porém, vigia, trabalha em tudo, cumpre o ministério de evangelista e desempenha o teu ministério. Sê sóbrio. Pois quanto a mim sou como uma vítima já aspergida para o sacrifício. O tempo da minha morte já se aproxima. Pelejei o bom combate; acabei a vida; permaneci na fé. Não me falta mais do que esperar a coroa da justiça, que me está reservada, a qual o Senhor, como justo juiz, me dará no grande dia: e não somente a mim, mas também àqueles que amam a sua vinda.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nOs justi meditábitur sapiéntiam, et lingua ejus loquétur judícium.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\nA boca do justo falará com sabedoria e a sua língua proclamará a justiça.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> A lei do seu Deus está sempre no seu coração e os seus pés não tropeçarão. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:9\u003c/I>\u003c/FONT>\u003cbr/>\nAmou-o o Senhor e revestiu-o com a túnica da glória. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 5:13-19\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Sois o sal da terra. Se o sal perde a força, com que salgará? Para nada mais presta, senão para se lançar fora e ser pisado pelos homens. Sois a luz do mundo. Uma cidade situada no cimo de um monte não pode ficar escondida. Nem se acende uma luz para a meter debaixo do alqueire, mas para a colocar no candeeiro, a fim de alumiar todos os que estão em casa. Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem vosso Pai, que está nos céus. Não penseis que vim abrogar a Lei ou os Profetas: não vim abrogar, mas aperfeiçoar; porque em verdade vos digo: até que passe o céu e a terra, nem um iota, nem um til se omitirá na Lei. Quem quer, pois, que transgrida, ainda um dos mais pequenos mandamentos, ou ensine os homens a violá-los, será chamado o menor no reino dos céus. Porém, quem os cumprir e ensinar será chamado grande no reino dos céus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti Joánnis Confessóris tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>blátis, quǽsumus, Dómine, placáre munéribus: et, intercedénte beáto Chrysógono Mártyre tuo, a cunctis nos defénde perículis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSancti João Confessóris tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eixai-Vos aplacar, Senhor, com a oferta destes dons, Vos suplicamos; e, pela intercessão do B. Crisógono, vosso Mártir, preservai-nos de todos os perigos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nUt nobis, Dómine, tua sacrifícia dent salútem: beátus Joánnes Conféssor tuus et Doctor egrégius, quǽsumus, precátor accédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>T\u003c/I>\u003c/B>\u003c/FONT>ui, Dómine, perceptióne sacraménti, et a nostris mundémur occúltis, et ab hóstium liberémur insídiis.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nUt nobis, Dómine, tua sacrifícia dent salútem: beátus João Conféssor tuus et Doctor egrégius, quǽsumus, precátor accédat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Chrysogoni Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue a recepção do vosso sacramento, Senhor, nos purifique das nossas faltas ocultas e nos livre das insídias dos nossos inimigos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-25":{"date":"2027-11-25","title":"Santa Catarina de Alexandria, virgem e mártir","forms":[{"number":1,"title":"S. Catharinæ Virginis et Martyris Duplex vide Commune Unius Virginis Martyris (Missa Loquebar) [Commune/C6.txt]","winner":"Sancti/11-25.txt","rule":"vide C6;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBeáti immaculáti in via: qui ámbulant in lege Dómini.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>L\u003c/I>\u003c/B>\u003c/FONT>oquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:46-47\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:1\u003c/I>\u003c/FONT>\u003cbr/>\nBem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a Lei do Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>alava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDeus, qui dedísti legem Móysi in summitáte montis Sínai, et in eódem loco per sanctos Angelos tuos corpus beátæ Catharínæ Vírginis et Mártyris tuæ mirabíliter collocásti: præsta, quǽsumus; ut, ejus méritis et intercessióne, ad montem, qui Christus est, perveníre valeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ Deus, que destes a Lei a Moisés no cimo do monte Sinai e que nesse lugar colocastes miraculosamente pelos vossos Santos Anjos o corpo da B. Catarina, vossa Virgem e Mártir, concedei-nos, Vos rogamos, que pelos seus méritos e intercessão possamos chegar à montanha, que é Cristo:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 51:1-8; 51:12\u003c/I>\u003c/FONT>\u003cbr/>\nConfitébor tibi, Dómine, Rex, et collaudábo te Deum, Salvatórem meum. Confitébor nómini tuo: quóniam adjútor et protéctor factus es mihi, et liberásti corpus meum a perditióne, a láqueo línguæ iníquæ et a lábiis operántium mendácium, et in conspéctu astántium factus es mihi adjutor. Et liberasti me secúndum multitúdinem misericórdiæ nóminis tui a rugiéntibus, præparátis ad escam, de mánibus quæréntium ánimam meam, et de portis tribulatiónum, quæ circumdedérunt me: a pressúra flammæ, quæ circúmdedit me, et in médio ignis non sum æstuáta: de altitúdine ventris ínferi, et a lingua coinquináta, et a verbo mendácii, a rege iníquo, et a lingua injústa: laudábit usque ad mortem ánima mea Dóminum: quóniam éruis sustinéntes te, et líberas eos de mánibus géntium, Dómine, Deus noster.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 51:1-8; 51:12\u003c/I>\u003c/FONT>\u003cbr/>\nQuero glorificar-Vos, Senhor e Rei; quero louvar-Vos, ó Deus, meu salvador. Quero glorificar o vosso nome, porque fostes o meu sustentáculo e protector e livrastes o meu corpo da perdição, do laço da língua iníqua e dos lábios daqueles que tramam a mentira. Na presença dos meus adversários fostes o meu auxílio. Livrastes-me, segundo a grandeza da misericórdia do vosso nome, dos que rugiam prestes a devorar-me; livrastes-me das mãos dos que procuravam tirar-me a vida; livrastes-me das aflições, que me cercavam; livrastes-me da violência das chamas, que me rodeavam, no meio das quais não senti o calor do fogo; livrastes-me do abysmo profundo do inferno; da língua impura; das palavras mentirosas; do rei iníquo; e da língua injusta! Minha alma louvará o Senhor até à morte, porque Vós, Senhor, nosso Deus, livrais dos perigos aqueles que confiam em Vós, salvando-os do poder dos inimigos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nDilexísti justítiam, et odísti iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAdducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:8\u003c/I>\u003c/FONT>\u003cbr/>\nAmastes a justiça e odiastes a iniquidade.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Por isso ungiu-vos o Senhor, vosso Deus, com o óleo da alegria. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 48:15; 48:16\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Serão apresentadas virgens ao Rei após ela: as suas companheiras serão introduzidas no meio da alegria. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 25:1-13\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus aos seus discípulos esta parábola: «O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: «Eis que chega o esposo; ide ao seu encontro». Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: «Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se». As prudentes responderam-lhes: «Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o». Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: «Senhor, senhor, abri-nos a porta». Ele respondeu: «Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nAfferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:15-16\u003c/I>\u003c/FONT>\u003cbr/>\nApós ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria e do júbilo; elas serão conduzidas ao templo do Rei, seu Senhor.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSúscipe, Dómine, múnera, quæ in beátæ Catharínæ Vírginis et Mártyris tuæ sollemnitáte deférimus: cujus nos confídimus patrocínio liberári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nRecebei benigno, Senhor, as ofertas que Vos apresentamos nesta solenidade da B. Virgem Catarina, vossa Mártir, com o patrocínio da qual esperamos ser livres.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 118:78; 118:80\u003c/I>\u003c/FONT>\u003cbr/>\nConfundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 118:78; 118:80\u003c/I>\u003c/FONT>\u003cbr/>\nSejam confundidos os soberbos, porque praticaram iniquidades contra mim. Para não ser confundido no último dia, cumprirei os vossos mandamentos e preceitos.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nAuxiliéntur nobis, Dómine, sumpta mystéria: et, intercedénte beáta Catharína Vírgine et Mártyre tua, sempitérna fáciant protectióne gaudére.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nQue nos auxiliem os sagrados mystérios, que acabámos de receber, Senhor, e que, por intercessão da B. Virgem Catarina, vossa Mártir, nos façam gozar continuamente a sua protecção.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-26":{"date":"2027-11-26","title":"São Silvestre, abade","forms":[{"number":1,"title":"S. Silvestri Abbatis Duplex vide Commune Abbatum (Missa altera Os justi) [Commune/C5b.txt]","winner":"Sancti/11-26.txt","rule":"vide C5b;\nGloria\n\n","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNoli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>s justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:30-31\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 36:1\u003c/I>\u003c/FONT>\u003cbr/>\nNão vos irriteis contra os maus, nem tenhais inveja daqueles que cometem iniquidades.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> boca do justo fala com sabedoria: e a sua língua proclama a justiça. A lei do seu Deus estará no seu coração.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nClementíssime Deus, qui sanctum Silvéstrum Abbátem, sǽculi hujus vanitátem in apérto túmulo pie meditántem, ad erémum vocáre et præcláris vitæ méritis decoráre dignátus es: te súpplices exorámus; ut, ejus exémplo terréna despiciéntes, tui consórtio perfruámur ætérno.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Petri Alexandrini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>I\u003c/I>\u003c/B>\u003c/FONT>nfirmitátem nostram réspice, omnípotens Deus: et, quia pondus própriæ actiónis gravat, beáti Petri Mártyris tui atque Pontíficis intercéssio gloriósa nos prótegat.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nÓ clementíssimo Deus, que Vos dignastes chamar à solidão o Santo Abade Silvestre quando meditava piedosamente em um túmulo aberto sobre a vaidade deste mundo, assim como o ornastes com os méritos de uma vida preclara, humildemente Vos suplicamos que, imitando o seu exemplo, desprezemos os bens terrenos, a fim de gozarmos eternamente a vossa companhia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Pedro Alexandrino\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>lhai para a nossa fraqueza, ó Deus omnipotente; e, visto que estamos oprimidos sob o peso dos nossos pecados, fazei que nos proteja a gloriosa intercessão do B. Pedro, vosso Pontífice e Mártir.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 45:1-6\u003c/I>\u003c/FONT>\u003cbr/>\nDiléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 45:1-6\u003c/I>\u003c/FONT>\u003cbr/>\nFoi amado de Deus e dos homens; a sua memória é uma bênção. O Senhor deu-lhe uma glória, semelhante à dos Santos; tornou-o temeroso e invencível perante seus inimigos; e com suas palavras aplacou os monstros. O Senhor honrou-o diante dos reis; deu-lhe as suas ordens diante do seu povo; e mostrou-lhe a sua glória. O Senhor santificou-o pela sua fé e mansidão; e escolheu-o entre todos os homens. Deus escutou-o; ouviu a sua voz; e fê-lo entrar na nuvem. Então, deu-lhe face a face os seus preceitos e a lei da vida e da doutrina.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nJustus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:4-5\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, concedestes-lhe bênçãos escolhidas as mais suaves; e impusestes na sua cabeça uma coroa de pedras preciosas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Concedestes-lhe a vida, que Vos suplicara, e prolongastes-lhe a duração dos seus dias pelos séculos dos séculos. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 91:13\u003c/I>\u003c/FONT>\u003cbr/>\nO justo florescerá, como a palmeira, e crescerá, como o cedro do Líbano. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 19:27-29\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 19:27-29\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Pedro a Jesus: «Eis que deixámos tudo e Vos seguimos. Que recompensa teremos por isso?». Jesus disse-lhes: «Em verdade vos digo: vós, que me seguistes, quando, no tempo da regeneração, o Filho do homem se sentar no trono da sua glória, também vos sentareis sobre doze tronos para julgar as doze tribos de Israel. Todo aquele que deixar a sua casa, ou os seus irmãos, ou os seus campos, ou o seu pai, ou a sua mãe, ou a sua mulher por causa do meu nome receberá o cêntuplo e possuirá a vida eterna».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 20:3-4\u003c/I>\u003c/FONT>\u003cbr/>\nDesidérium ánimæ ejus tribuísti ei, Dómine, et voluntáte labiórum ejus non fraudásti eum: posuísti in cápite ejus corónam de lápide pretióso.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 20:3; 20:4\u003c/I>\u003c/FONT>\u003cbr/>\nConcedestes-lhe o desejo da sua alma e não desprezastes a prece dos seus lábios. Impusestes na sua cabeça uma coroa de pedras preciosas.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nQuǽsumus, Dómine: ut, dum hæc múnera divínæ majestáti tuæ reverénter offérimus; pia mentis præparatióne et cordis puritáte, beáti Silvéstri Abbátis imitatóres effécti, Corpus et Sánguinem Fílii tui sancte percípere mereámur:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Petri Alexandrini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>óstias tibi, Dómine, beáti Petri Mártyris tui atque Pontíficis dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, Vos suplicamos, permiti que, oferecendo reverentemente à vossa divina majestade estes dons, nos tornemos imitadores do B. Abade Silvestre pela piedosa disposição da alma e pela pureza de coração, a fim de que mereçamos receber santamente o Corpo e o Sangue de vosso Filho.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ue, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Pedro Alexandrino\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>ecebei benigno, Senhor, as hóstias que Vos oferecemos pelos merecimentos do B. Pedro, vosso Mártir e Pontífice, e fazei que elas nos alcancem o vosso perpétuo socorro.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Communis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Comum\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nFidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 12:42\u003c/I>\u003c/FONT>\u003cbr/>\nEis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nDivína dape reféctis tríbue, quǽsumus, Dómine: sancti Silvéstri Abbátis vestígiis ita inhærére; ut copiósam mercédem in regno glóriæ tuæ cum Sanctis habeámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Petri Alexandrini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>R\u003c/I>\u003c/B>\u003c/FONT>efécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedénte beáto Petro Mártyre tuo atque Pontífice, sentiámus efféctum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo comparticipado do divino banquete, concedei-nos, Senhor, Vos suplicamos, que sigamos de tal sorte os passos do Santo Abade Silvestre que tenhamos com vossos Santos copiosa recompensa no reino da vossa glória.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Pedro Alexandrino\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>F\u003c/I>\u003c/B>\u003c/FONT>ortalecidos com a participação do dom sacratíssimo, Vos pedimos, Senhor, nosso Deus, que, por intercessão do B. Pedro, vosso Mártir e Pontífice, sintamos o efeito do mystério que hoje celebrámos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-27":{"date":"2027-11-27","title":"Ofício de Nossa Senhora no sábado","forms":[{"number":1,"title":"Sanctæ Mariæ Sabbato\tSimplex vide  [Commune/C10.txt]","winner":"Commune/C10.txt","rule":"vide C10\nSpecial Benedictio\nSpecial Lectio 3\nDoxology=Nat\nAntiphonas horas\nGloria\nSuffr=Spiritu;Ecclesiæ,Papa;;\nPrefatio=Maria=veneratione;\n\nex C10","gloria":true,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nEructávit cor meum verbum bonum: dico ego ópera mea Regi.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> Sedulius\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:2\u003c/I>\u003c/FONT>\u003cbr/>\nMeu coração exprimiu uma excelente palavra: Consagro ao Rei as minhas obras.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>alve, ó Santa Maria, em cujo seio foi gerado o Rei que governa o céu e a terra em todos os séculos dos séculos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nConcéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nConcedei aos vossos servos, Senhor Deus, Vos suplicamos, o gozo da perpétua saúde da alma e do corpo, e que pela gloriosa intercessão da B. Maria, sempre Virgem, sejamos livres das tristezas dos tempos presentes e alcancemos o gozo da eterna alegria.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio libri Sapiéntiæ\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Eccli 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nAb inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição do Livro da Sabedoria.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sb 24:14-16\u003c/I>\u003c/FONT>\u003cbr/>\nFui criada desde o princípio, antes de todos os séculos, e não deixarei de existir até à eternidade. Exerci perante Ele o meu ministério; e deste modo tenho habitação fixa em Sião. Ele deixa-me descansar na cidade santa e tenho poder em Jerusalém. Arraiguei-me em um povo glorioso, da parte do meu Deus e da sua herança, e permaneço na companhia dos santos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBenedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBendita e venerável sois vós, ó Virgem Maria, que fostes Mãe do Salvador, sem que a vossa pureza sofresse a mais leve ofensa.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Ó Virgem Mãe de Deus, Aquele que nem todo o universo é capaz de conter, esteve encerrado, quando se fez homem, no vosso seio. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Depois de haverdes dado à luz, permanecestes Virgem Imaculada: Intercedei por nós, ó Mãe de Deus. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 11:27-28\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, falando Jesus às turbas, eis que uma mulher, elevando a voz no meio da multidão, Lhe disse: «Bem-aventurado o seio que Vos trouxe; bem-aventurados os peitos que Vos amamentaram!». E Jesus respondeu, dizendo: «Bem-aventurados, antes, aqueles que ouvem a palavra de Deus e a cumprem».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 1:28 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 1:28; 1:42\u003c/I>\u003c/FONT>\u003cbr/>\nAve, Maria, cheia de graça: o Senhor é convosco: bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nTua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPela vossa misericórdia, Senhor, e pela intercessão da B. Maria, sempre Virgem, fazei que esta oblação nos assegure a prosperidade e a paz, agora e sempre.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Beata Maria Virgine\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in veneratione beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> da B. Virgem Maria\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai omnipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigénito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nBeáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nBem-aventuradas as entranhas da Virgem Maria, que trouxeram encerrado o Filho do Pai Eterno.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHavendo nós, Senhor, alcançado o poderoso auxílio da nossa salvação, concedei-nos, Vos imploramos, que sejamos protegidos com o patrocínio da B. Maria, sempre Virgem, em cuja honra oferecemos à vossa majestade este sacrifício.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-28":{"date":"2027-11-28","title":"I Domingo do Advento","forms":[{"number":1,"title":"Dominica I Adventus\tSemiduplex","winner":"Tempora/Adv1-0.txt","rule":"no Gloria\nCredo\nSuffr=Maria1;Ecclesiæ,Papa;;\n\n","gloria":false,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>d te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nVias tuas, Dómine, demónstra mihi: et sémitas tuas édoce me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>d te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nMostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nExcita, quǽsumus, Dómine, poténtiam tuam, et veni: ut ab imminéntibus peccatórum nostrórum perículis, te mereámur protegénte éripi, te liberánte salvári:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor Vos suplicamos, manifestai o vosso poder, e «vinde já ao mundo», a fim de que com vossa protecção mereçamos ser preservados dos iminentes perigos em que incorremos por causa dos nossos pecados, e sejamos livres e salvos:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLectio Epístolæ beáti Pauli Apóstoli ad Romános\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:11-14.\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Sciéntes, quia hora est jam nos de somno súrgere. Nunc enim própior est nostra salus, quam cum credídimus. Nox præcéssit, dies autem appropinquávit. Abjiciámus ergo ópera tenebrárum, et induámur arma lucis. Sicut in die honéste ambulémus: non in comessatiónibus et ebrietátibus, non in cubílibus et impudicítiis, non in contentióne et æmulatióne: sed induímini Dóminum Jesum Christum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Romanos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:11-14\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Sabeis que soou a hora em que devemos despertar do sono. Agora, a nossa salvação está mais próxima do que quando recebemos o dom da fé. A noite passou e o dia vem chegando. Despojemo-nos, pois, das obras das trevas, e revistamo-nos das armas da luz. Andemos honestamente, como de dia: nem em excessos de comidas e bebidas nem em luxúrias e impurezas, nem em contendas e invejas; mas revistamo-nos de Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:3; 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nUnivérsi, qui te exspéctant, non confundéntur, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vias tuas, Dómine, notas fac mihi: et sémitas tuas édoce me. Allelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:8.\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Osténde nobis, Dómine, misericórdiam tuam: et salutáre tuum da nobis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:3-4\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, todos os que esperam em Vós não serão confundidos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Mostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:8\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Mostrai-nos, Senhor, a vossa misericórdia: e dai-nos a salvação. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secundum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 21:25-33.\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Erunt signa in sole et luna et stellis, et in terris pressúra géntium præ confusióne sónitus maris et flúctuum: arescéntibus homínibus præ timóre et exspectatióne, quæ supervénient univérso orbi: nam virtútes cœlórum movebúntur. Et tunc vidébunt Fílium hóminis veniéntem in nube cum potestáte magna et majestáte. His autem fíeri incipiéntibus, respícite et leváte cápita vestra: quóniam appropínquat redémptio vestra. Et dixit illis similitúdinem: Vidéte ficúlneam et omnes árbores: cum prodúcunt jam ex se fructum, scitis, quóniam prope est æstas. Ita et vos, cum vidéritis hæc fíeri, scitóte, quóniam prope est regnum Dei. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia fiant. Cœlum et terra transíbunt: verba autem mea non transíbunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 21:25-33\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Haverá sinais no sol, na lua e nas estrelas; e haverá angústia nos povos da terra por causa do bramido do mar e das ondas, mirrando-se os homens de susto, na expectativa daquelas cousas que irão acontecer em todo o mundo; pois os poderes do céu estremecerão. Então aparecerá o Filho do homem, que virá em uma nuvem, revestido de grande poder e majestade. Quando estas cousas começarem a acontecer, olhai para o alto e erguei as vossas cabeças, porque se avizinha a vossa redenção». Depois deu-lhes esta comparação: «Vede a figueira e as demais árvores. Quando elas começam a frutificar, por aí conheceis que está próximo o estio. Do mesmo modo, quando estas cousas acontecerem, sabereis que está próximo o reino de Deus. Em verdade vos digo: não acabará esta geração sem que isto aconteça. O céu e a terra passarão; mas as minhas palavras permanecerão para sempre».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3.\u003c/I>\u003c/FONT>\u003cbr/>\nAd te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc sacra nos, Dómine, poténti virtúte mundátos ad suum fáciant purióres veníre princípium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, Senhor, que estes mystérios, depois de nos haverem purificado com vossa poderosa virtude, nos façam chegar mais puros ainda junto daquele que é o seu princípio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Adventu\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Quem pérdito hóminum géneri Salvatórem miséricors et fidélis promisísti: cujus véritas instrúeret ínscios, sánctitas justificáret ímpios, virtus adiuváret infírmos. Dum ergo prope est ut véniat quem missúrus es, et dies affúlget liberatiónis nostræ, in hac promissiónum tuárum fide, piis gáudiis exsultámus. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Adventu\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Quem pérdito hóminum géneri Salvatórem miséricors et fidélis promisísti: cujus véritas instrúeret ínscios, sánctitas justificáret ímpios, virtus adiuváret infírmos. Dum ergo prope est ut véniat quem missúrus es, et dies affúlget liberatiónis nostræ, in hac promissiónum tuárum fide, piis gáudiis exsultámus. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:13.\u003c/I>\u003c/FONT>\u003cbr/>\nDóminus dabit benignitátem: et terra nostra dabit fructum suum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:13\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor mostrará a sua bondade: e a nossa terra dará «o seu fruto».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSuscipiámus, Dómine, misericórdiam tuam in médio templi tui: ut reparatiónis nostræ ventúra sollémnia cóngruis honóribus præcedámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, permiti que alcancemos a vossa misericórdia no meio do vosso templo, para que celebremos com a conveniente preparação a próxima solenidade da nossa reparação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-29":{"date":"2027-11-29","title":"Féria da 1ª semana do Advento","forms":[{"number":1,"title":"Feria II infra Hebdomadam I Adventus\tFeria major","winner":"Tempora/Adv1-1.txt","rule":"Oratio Dominica\nno Gloria\nno Credo\nSuffr=Maria1;Ecclesiæ,Papa;;\n","gloria":false,"credo":false,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>d te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nVias tuas, Dómine, demónstra mihi: et sémitas tuas édoce me.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT>d te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nMostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>A\u003c/I>\u003c/B>\u003c/FONT> Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nExcita, quǽsumus, Dómine, poténtiam tuam, et veni: ut ab imminéntibus peccatórum nostrórum perículis, te mereámur protegénte éripi, te liberánte salvári:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Saturnini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>D\u003c/I>\u003c/B>\u003c/FONT>eus, qui nos beáti Saturníni Mártyris tui concédis natalícia pérfrui: ejus nos tríbue méritis adjuvári.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor Vos suplicamos, manifestai o vosso poder, e «vinde já ao mundo», a fim de que com vossa protecção mereçamos ser preservados dos iminentes perigos em que incorremos por causa dos nossos pecados, e sejamos livres e salvos:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Saturnino, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>Ó\u003c/I>\u003c/B>\u003c/FONT> Deus, que nos permitistes a alegria de celebrarmos o aniversário do nascimento do vosso B. Mártir Saturnino, concedei-nos ainda que sejamos auxiliados pelos seus méritos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLectio Epístolæ beáti Pauli Apóstoli ad Romános\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:11-14.\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Sciéntes, quia hora est jam nos de somno súrgere. Nunc enim própior est nostra salus, quam cum credídimus. Nox præcéssit, dies autem appropinquávit. Abjiciámus ergo ópera tenebrárum, et induámur arma lucis. Sicut in die honéste ambulémus: non in comessatiónibus et ebrietátibus, non in cubílibus et impudicítiis, non in contentióne et æmulatióne: sed induímini Dóminum Jesum Christum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Romanos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 13:11-14\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Sabeis que soou a hora em que devemos despertar do sono. Agora, a nossa salvação está mais próxima do que quando recebemos o dom da fé. A noite passou e o dia vem chegando. Despojemo-nos, pois, das obras das trevas, e revistamo-nos das armas da luz. Andemos honestamente, como de dia: nem em excessos de comidas e bebidas nem em luxúrias e impurezas, nem em contendas e invejas; mas revistamo-nos de Nosso Senhor Jesus Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:3; 24:4\u003c/I>\u003c/FONT>\u003cbr/>\nUnivérsi, qui te exspéctant, non confundéntur, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Vias tuas, Dómine, notas fac mihi: et sémitas tuas édoce me.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:3-4\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, todos os que esperam em Vós não serão confundidos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Mostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secundum Lucam\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Luc 21:25-33.\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Dixit Jesus discípulis suis: Erunt signa in sole et luna et stellis, et in terris pressúra géntium præ confusióne sónitus maris et flúctuum: arescéntibus homínibus præ timóre et exspectatióne, quæ supervénient univérso orbi: nam virtútes cœlórum movebúntur. Et tunc vidébunt Fílium hóminis veniéntem in nube cum potestáte magna et majestáte. His autem fíeri incipiéntibus, respícite et leváte cápita vestra: quóniam appropínquat redémptio vestra. Et dixit illis similitúdinem: Vidéte ficúlneam et omnes árbores: cum prodúcunt jam ex se fructum, scitis, quóniam prope est æstas. Ita et vos, cum vidéritis hæc fíeri, scitóte, quóniam prope est regnum Dei. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia fiant. Cœlum et terra transíbunt: verba autem mea non transíbunt.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Lucas.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Lc 21:25-33\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, disse Jesus a seus discípulos: «Haverá sinais no sol, na lua e nas estrelas; e haverá angústia nos povos da terra por causa do bramido do mar e das ondas, mirrando-se os homens de susto, na expectativa daquelas cousas que irão acontecer em todo o mundo; pois os poderes do céu estremecerão. Então aparecerá o Filho do homem, que virá em uma nuvem, revestido de grande poder e majestade. Quando estas cousas começarem a acontecer, olhai para o alto e erguei as vossas cabeças, porque se avizinha a vossa redenção». Depois deu-lhes esta comparação: «Vede a figueira e as demais árvores. Quando elas começam a frutificar, por aí conheceis que está próximo o estio. Do mesmo modo, quando estas cousas acontecerem, sabereis que está próximo o reino de Deus. Em verdade vos digo: não acabará esta geração sem que isto aconteça. O céu e a terra passarão; mas as minhas palavras permanecerão para sempre».\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 24:1-3.\u003c/I>\u003c/FONT>\u003cbr/>\nAd te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 24:1-3\u003c/I>\u003c/FONT>\u003cbr/>\nA Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nHæc sacra nos, Dómine, poténti virtúte mundátos ad suum fáciant purióres veníre princípium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Saturnini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>únera, Dómine, tibi dicáta sanctífica: et, intercedénte beáto Saturníno Mártyre tuo, per hæc eádem nos placátus inténde.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nPermiti, Senhor, que estes mystérios, depois de nos haverem purificado com vossa poderosa virtude, nos façam chegar mais puros ainda junto daquele que é o seu princípio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Saturnino, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>antificai, Senhor, estas ofertas, que Vos dedicamos, e por intercessão do B. Saturnino, vosso Mártir, olhai aplacado para nós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Adventu\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Quem pérdito hóminum géneri Salvatórem miséricors et fidélis promisísti: cujus véritas instrúeret ínscios, sánctitas justificáret ímpios, virtus adiuváret infírmos. Dum ergo prope est ut véniat quem missúrus es, et dies affúlget liberatiónis nostræ, in hac promissiónum tuárum fide, piis gáudiis exsultámus. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Adventu\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: per Christum Dóminum nostrum. Quem pérdito hóminum géneri Salvatórem miséricors et fidélis promisísti: cujus véritas instrúeret ínscios, sánctitas justificáret ímpios, virtus adiuváret infírmos. Dum ergo prope est ut véniat quem missúrus es, et dies affúlget liberatiónis nostræ, in hac promissiónum tuárum fide, piis gáudiis exsultámus. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus, cumque omni milítia cœléstis exércitus, hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 84:13.\u003c/I>\u003c/FONT>\u003cbr/>\nDóminus dabit benignitátem: et terra nostra dabit fructum suum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 84:13\u003c/I>\u003c/FONT>\u003cbr/>\nO Senhor mostrará a sua bondade: e a nossa terra dará «o seu fruto».\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSuscipiámus, Dómine, misericórdiam tuam in médio templi tui: ut reparatiónis nostræ ventúra sollémnia cóngruis honóribus præcedámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio S. Saturnini Martyris\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>anctíficet nos, quǽsumus, Dómine, tui percéptio sacraménti: et intercessióne Sanctórum tuórum tibi reddat accéptos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, permiti que alcancemos a vossa misericórdia no meio do vosso templo, para que celebremos com a conveniente preparação a próxima solenidade da nossa reparação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: S. Saturnino, Mártir\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, Vos suplicamos, permiti que a recepção do vosso sacramento nos santifique e que por intercessão dos vossos santos nos alcance a graça de Vos agradarmos.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]},"2027-11-30":{"date":"2027-11-30","title":"Santo André, apóstolo","forms":[{"number":1,"title":"S. Andreæ Apostoli Duplex 2 classis ex Commune Apostolorum [Commune/C1.txt]","winner":"Sancti/11-30.txt","rule":"ex C1;\nGloria\nCredo\nPrefatio=Apostolis\n\n","gloria":true,"credo":true,"omitPsalm":false,"omitLastGospel":false,"slots":{"1":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Introitus\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:1-2.\u003c/I>\u003c/FONT>\u003cbr/>\nDómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória Patri, et Fílio, et Spirítui Sancto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>M\u003c/I>\u003c/B>\u003c/FONT>ihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Intróito\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ejo, ó Deus, que honrastes largamente os vossos amigos: e que seu poder se fortaleceu extraordinariamente.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:1-2\u003c/I>\u003c/FONT>\u003cbr/>\nSenhor, perscrutastes o meu íntimo e ficastes conhecendo-me: ficastes conhecendo quando me deito e quando me levanto.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Glória ao Pai, e ao Filho e ao Espírito Santo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amen.\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ejo, ó Deus, que honrastes largamente os vossos amigos: e que seu poder se fortaleceu extraordinariamente.\u003cbr/>\n"}],"2":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oratio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nMajestátem tuam, Dómine, supplíciter exorámus: ut, sicut Ecclésiæ tuæ beátus Andréas Apóstolus éxstitit prædicátor et rector; ita apud te sit pro nobis perpétuus intercéssor.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>E\u003c/I>\u003c/B>\u003c/FONT>xcita, quǽsumus, Dómine, poténtiam tuam, et veni: ut ab imminéntibus peccatórum nostrórum perículis, te mereámur protegénte éripi, te liberánte salvári:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Q\u003c/I>\u003c/B>\u003c/FONT>ui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Oração\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nHumildemente suplicamos à vossa divina majestade que, assim como o Apóstolo André foi pregador e guia da vossa Igreja, assim também interceda por nós perpetuamente junto de Vós.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor Vos suplicamos, manifestai o vosso poder, e «vinde já ao mundo», a fim de que com vossa protecção mereçamos ser preservados dos iminentes perigos em que incorremos por causa dos nossos pecados, e sejamos livres e salvos:\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen\u003cbr/>\n"}],"3":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Lectio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\nLéctio Epístolæ beáti Pauli Apóstoli ad Romános\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rom 10:10-18\u003c/I>\u003c/FONT>\u003cbr/>\nFratres: Corde enim créditur ad justítiam: ore autem conféssio fit ad salútem. Dicit enim Scriptúra: Omnis, qui credit in illum, non confundétur. Non enim est distínctio Judǽi et Græci: nam idem Dóminus ómnium, dives in omnes, qui ínvocant illum. Omnis enim, quicúmque invocáverit nomen Dómini, salvus erit. Quómodo ergo invocábunt, in quem non credidérunt? Aut quómodo credent ei, quem non audiérunt? Quómodo autem áudient sine prædicánte? Quómodo vero prædicábunt, nisi mittántur? sicut scriptum est: Quam speciósi pedes evangelizántium pacem, evangelizándum bona! Sed non omnes obédiunt Evangélio. Isaías enim dicit: Dómine, quis crédidit audítui nostro? Ergo fides ex audítu, audítus autem per verbum Christi. Sed dico: Numquid non audiérunt? Et quidem in omnem terram exívit sonus eórum, et in fines orbis terræ verba eórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Deo grátias.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Epístola\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nLição da Ep.ª do B. Ap.º Paulo aos Romanos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Rm 10:10-18\u003c/I>\u003c/FONT>\u003cbr/>\nMeus irmãos: Com o coração se crê para chegar à justiça; e com a boca se faz profissão de fé para alcançar a salvação. Com efeito diz a Escritura: «Todo aquele que crê n’Ele não será confundido», porque não há diferença entre judeu e grego, visto que não há senão um só e o mesmo Senhor de todos, que é rico para todos os que O invocam; pois todo o que invocar o nome do Senhor será salvo. Porém como invocarão Aquele em quem não acreditam? E como hão-de crer sem haverem ouvido falar d’Ele? E como se ouvirá falar, se não houver pregadores? E como haverá pregadores se não tiverem sido enviados? Pois está escrito: «Como são preciosos os pés daqueles que evangelizam a paz, que evangelizam a felicidade!». Mas nem todos obedecem ao Evangelho. Isaías disse: «Senhor, quem acreditou na nossa pregação?». Assim, a fé nasce da pregação ouvida, e a pregação vem da palavra de Cristo. E eu vos pergunto: «Porventura eles a não ouviram?». Sim, por certo: pois por toda a terra se espalhou a sua voz, e suas palavras soaram até aos extremos do mundo!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Graças a Deus.\u003cbr/>\n"}],"4":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Graduale\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 44:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nConstítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi.\u003cbr/>\nAllelúja, allelúja.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Diléxit Andréam Dóminus in odórem suavitátis. Allelúja.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Gradual\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 44:17-18\u003c/I>\u003c/FONT>\u003cbr/>\nSerão constituídos príncipes em toda a terra e perpetuarão a glória do vosso nome, Senhor!\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> Para substituir os vossos pais nasceram-vos filhos; por isso os povos Vos louvarão eternamente. Aleluia, aleluia.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℣.\u003c/I>\u003c/FONT> O Senhor amou André, como um perfume suave. Aleluia.\u003cbr/>\n"}],"5":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>equéntia \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> sancti Evangélii secúndum Matthǽum\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória tibi, Dómine.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 4:18-22\u003c/I>\u003c/FONT>\u003cbr/>\nIn illo témpore: Ambulans Jesus juxta mare Galilǽæ, vidit duos fratres, Simónem, qui vocátur Petrus, et Andréam fratrem ejus, mitténtes rete in mare - erant enim piscatóres -  et ait illis: Veníte post me, et fáciam vos fíeri piscatóres hóminum. At illi contínuo, relíctis rétibus, secúti sunt eum. Et procédens inde, vidit álios duos fratres, Jacóbum Zebedæi et Joánnem, fratrem ejus, in navi cum Zebedæo patre eórum reficiéntes rétia sua: et vocávit eos. Illi autem statim, relíctis rétibus et patre, secúti sunt eum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Laus tibi, Christe.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Per Evangélica dicta, deleántur nostra delícta.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Evangelho\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ontinuação \u003cspan style='color:red; font-size:1.25em'>+\u003c/span> do santo Evangelho segundo S. Mateus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Glória a Vós, Senhor.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 4:18-22\u003c/I>\u003c/FONT>\u003cbr/>\nNaquele tempo, caminhando Jesus junto ao mar da Galileia, viu dois irmãos: Simão, que se chama Pedro, e André, irmão deste, os quais lançavam as redes no mar, pois eram pescadores. Disse-lhes Jesus: «Vinde comigo e far-vos-ei pescadores de homens». Imediatamente eles, deixando as redes, O seguiram. Continuando Jesus a andar, encontrou mais adiante em uma barca, consertando as redes, outros dois irmãos: Tiago, filho de Zebedeu, e João, seu irmão, com seu pai Zebedeu. Então chamou-os. Logo, no mesmo instante, eles, deixando as redes e o pai, seguiram-n’O.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Louvores a Vós, ó Cristo.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>S.\u003c/I>\u003c/FONT> Que pelas palavras do Evangelho nos sejam perdoados os nossos pecados.\u003cbr/>\n"}],"6":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Offertorium\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Ps 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nMihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Ofertório\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Sl 138:17\u003c/I>\u003c/FONT>\u003cbr/>\nVejo, ó Deus, que honrastes largamente os vossos amigos; por isso o seu poder se fortaleceu extraordinariamente.\u003cbr/>\n"}],"7":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSacrificium nostrum tibi, Dómine, quǽsumus, beáti Andréæ Apóstoli precátio sancta concíliet: ut, in cujus honóre sollémniter exhibétur, ejus méritis efficiátur accéptum.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>H\u003c/I>\u003c/B>\u003c/FONT>æc sacra nos, Dómine, poténti virtúte mundátos ad suum fáciant purióres veníre princípium.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Secreta\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\nSenhor, permiti que a oração do B. Apóstolo André Vos torne agradável este nosso sacrifício, a fim de que seja aceite, em virtude dos méritos daquele em cuja honra Vos é solenemente oferecido.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>ermiti, Senhor, que estes mystérios, depois de nos haverem purificado com vossa poderosa virtude, nos façam chegar mais puros ainda junto daquele que é o seu princípio.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}],"8":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefatio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>de Apostolis\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>V\u003c/I>\u003c/B>\u003c/FONT>ere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Prefácio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI> dos Apóstolos\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>É\u003c/I>\u003c/B>\u003c/FONT> verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua protecção, a fim de que seja sempre governado pelos mesmos Directores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\u003cbr/>\n"}],"9":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Communio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Matt 4:19-20\u003c/I>\u003c/FONT>\u003cbr/>\nVeníte post me: fáciam vos fíeri piscatóres hóminum; at illi contínuo, relíctis rétibus, secúti sunt Dóminum.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Mt 4:19-20\u003c/I>\u003c/FONT>\u003cbr/>\nVinde comigo: e far-vos-ei pescadores de homens. Imediatamente eles, deixando as redes, seguiram o Senhor.\u003cbr/>\n"}],"10":[{"la":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Postcommunio\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\nSúmpsimus, Dómine, divína mystéria, beáti Andréæ Apóstoli festivitáte lætántes: quæ, sicut tuis Sanctis ad glóriam, ita nobis, quǽsumus, ad véniam prodésse perfícias.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>rémus.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Commemoratio Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>uscipiámus, Dómine, misericórdiam tuam in médio templi tui: ut reparatiónis nostræ ventúra sollémnia cóngruis honóribus præcedámus.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>er Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n","pt":"\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>Pós-comunhão\u003c/I>\u003c/B>\u003c/FONT> \n\u003cbr/>\n\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\nSenhor, que os divinos mystérios, que com alegria recebemos nesta festa do B. André, servindo para a glória dos vossos Santos, nos alcancem, também, o perdão das nossas culpas.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n_\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>O\u003c/I>\u003c/B>\u003c/FONT>remos\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>Comemoração: Feria III infra Hebdomadam I Adventus\u003c/I>\u003c/FONT>\u003cbr/>\n\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>S\u003c/I>\u003c/B>\u003c/FONT>enhor, permiti que alcancemos a vossa misericórdia no meio do vosso templo, para que celebremos com a conveniente preparação a próxima solenidade da nossa reparação.\u003cbr/>\n\u003cFONT SIZE='+1' COLOR=\"red\">\u003cB>\u003cI>P\u003c/I>\u003c/B>\u003c/FONT>or Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo,  por todos os séculos dos séculos.\u003cbr/>\n\u003cFONT COLOR=\"red\">\u003cI>℟.\u003c/I>\u003c/FONT> Amen.\u003cbr/>\n"}]},"communicantes":[{"la":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>C\u003c/I>\u003c/B>\u003c/FONT>ommunicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,\n\u003cbr/>\n","pt":"\u003cFONT SIZE='+2' COLOR=\"red\">\u003cB>\u003cI>U\u003c/I>\u003c/B>\u003c/FONT>nidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem,\n\u003cbr/>\n"}],"hancigitur":[],"lastGospel":[]}]}}};
